CREATE OR REPLACE FUNCTION public.close_market_swap_thread_v1(p_thread_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_thread dv_market_private.market_swap_threads%rowtype; v_action text:=lower(trim(coalesce(p_action,'')));
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  if v_action not in ('withdrawn','declined') then raise exception 'swap_close_action_invalid';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id for update;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) then raise exception 'swap_not_participant';end if;
  if v_thread.status<>'negotiating' then raise exception 'bound_swap_cannot_be_unilaterally_closed';end if;
  update dv_market_private.market_swap_threads set status=v_action,closed_at=now(),closed_reason=v_action,updated_at=now() where id=v_thread.id;
end
$function$

CREATE OR REPLACE FUNCTION public.complete_market_deal(p_listing_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d_id uuid; l public.market_listings;
begin
 select * into l from public.market_listings where id=p_listing_id for update;
 if l.id is null or l.seller_id<>auth.uid() then raise exception 'Only seller can confirm deal'; end if;
 select id into d_id from public.market_deals where listing_id=p_listing_id;
 if d_id is null then raise exception 'Deal record not found'; end if;
 perform public.confirm_market_deal_complete(d_id);
end $function$

CREATE OR REPLACE FUNCTION public.confirm_market_deal_complete(p_deal_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.market_deals; new_status text;
begin
 select * into d from public.market_deals where id=p_deal_id for update;
 if d.id is null or auth.uid() not in (d.seller_id,d.buyer_id) then raise exception 'Nicht erlaubt'; end if;
 if d.order_id is not null then raise exception 'Dieser Deal ist Teil einer DUELVANTA Order. Abschluss bitte über ORDERS bestätigen.'; end if;
 if d.status in ('completed','cancelled','disputed') then return d.status; end if;
 if d.payment_provider='stripe_connect' and d.payment_status<>'paid' then raise exception 'Zahlung ist noch nicht bestätigt'; end if;
 if d.status='accepted' then update public.market_deals set status='in_progress',started_at=coalesce(started_at,now()),fulfillment_status=case when payment_status in ('paid','not_required') then 'ready_to_ship' else fulfillment_status end,updated_at=now() where id=d.id; end if;
 select * into d from public.market_deals where id=p_deal_id for update;
 if d.payment_provider='stripe_connect' then
   if auth.uid()=d.seller_id and d.fulfillment_status not in ('shipped','received') then raise exception 'Bitte zuerst den Versand bestätigen'; end if;
   if auth.uid()=d.buyer_id and d.fulfillment_status<>'received' then raise exception 'Bitte zuerst den Erhalt bestätigen'; end if;
 end if;
 if auth.uid()=d.seller_id then update public.market_deals set seller_confirmed_at=coalesce(seller_confirmed_at,now()),updated_at=now() where id=d.id; else update public.market_deals set buyer_confirmed_at=coalesce(buyer_confirmed_at,now()),updated_at=now() where id=d.id; end if;
 select * into d from public.market_deals where id=p_deal_id for update;
 if d.seller_confirmed_at is not null and d.buyer_confirmed_at is not null then
   update public.market_deals set status='completed',completed_at=now(),payout_status=case when payment_provider='stripe_connect' then 'pending' else 'not_applicable' end,updated_at=now() where id=d.id;
   update public.market_listings set status='sold',ended_at=now(),updated_at=now() where id=d.listing_id;
   update public.market_offers set completed_at=now(),updated_at=now() where id=d.offer_id and status='accepted'; new_status:='completed';
 else new_status:='in_progress'; end if;
 return new_status;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_market_deal_received(p_deal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.market_deals;
begin
 select * into d from public.market_deals where id=p_deal_id for update;
 if d.id is null or auth.uid()<>d.buyer_id then raise exception 'Nur der Käufer kann den Erhalt bestätigen'; end if;
 if d.order_id is not null then raise exception 'Dieser Deal ist Teil einer DUELVANTA Order. Erhalt bitte über ORDERS bestätigen.'; end if;
 if d.status<>'in_progress' then raise exception 'Deal ist nicht in Abwicklung'; end if;
 if d.fulfillment_status not in ('shipped','received') then raise exception 'Versand wurde noch nicht bestätigt'; end if;
 update public.market_deals set fulfillment_status='received',received_at=coalesce(received_at,now()),updated_at=now() where id=d.id;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_market_order_complete(p_order_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare o public.market_orders;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet';end if;
  select * into o from public.market_orders where id=p_order_id;
  if not found or auth.uid() not in (o.seller_id,o.buyer_id) then raise exception 'Nicht erlaubt';end if;
  if o.status in ('completed','cancelled','disputed') then return o.status;end if;
  if auth.uid()<>o.buyer_id then raise exception 'Nur der Käufer kann "Erhalten – alles in Ordnung" bestätigen';end if;
  perform public.confirm_market_order_received(p_order_id);
  return 'completed';
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_market_order_received(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare o public.market_orders;v_now timestamptz:=now();
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet';end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if not found or auth.uid()<>o.buyer_id then raise exception 'Nur der Käufer kann den Erhalt bestätigen';end if;
  if o.fulfillment_group<>'shipping' then raise exception 'pickup_requires_handover_code';end if;
  if o.status='completed' then return;end if;
  if o.status not in ('shipped','received') or o.shipped_at is null then raise exception 'Order ist noch nicht als versendet markiert';end if;
  if o.payment_status not in ('not_required','paid') or (o.payment_provider<>'manual_beta' and o.payment_status<>'paid') then raise exception 'Zahlung ist noch offen';end if;
  if exists(select 1 from public.market_order_cases c where c.order_id=o.id and c.case_type='problem' and c.status='open') then raise exception 'Ein Problem ist noch offen';end if;
  update public.market_orders set buyer_received_ok_at=coalesce(buyer_received_ok_at,v_now),buyer_confirmed_at=coalesce(buyer_confirmed_at,v_now),received_at=coalesce(received_at,v_now),updated_at=now() where id=o.id;
  update public.market_deals set buyer_confirmed_at=coalesce(buyer_confirmed_at,v_now),received_at=coalesce(received_at,v_now),updated_at=now() where order_id=o.id and status in ('accepted','in_progress');
  perform dv_market_private.b07_complete_order(o.id,'buyer_received_ok',v_now);
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_market_order_shipping(p_order_id uuid, p_shipping_method text, p_shipping_cost numeric, p_shipping_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.market_orders;v_country text;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if o.id is null or auth.uid()<>o.seller_id then raise exception 'Nur der Verkäufer kann Combined Shipping bestätigen'; end if;
  if o.shipped_at is not null or o.status in ('completed','cancelled','disputed') then raise exception 'Versand kann nicht mehr geändert werden'; end if;
  if o.fulfillment_group='pickup' then p_shipping_method:='pickup';p_shipping_cost:=0;end if;
  if p_shipping_method not in ('standard_letter','tracked_letter','parcel','pickup','custom') then raise exception 'Ungültige Versandart';end if;
  if p_shipping_cost is null or p_shipping_cost<0 or p_shipping_cost>500 then raise exception 'Ungültige Versandkosten';end if;
  if o.fulfillment_group='shipping' and p_shipping_method='pickup' then raise exception 'Abholung kann nicht mit Versandartikeln kombiniert werden';end if;
  if o.fulfillment_group='shipping' and (o.subtotal>25 or o.risk_tracking_required) and p_shipping_method not in ('tracked_letter','parcel') then raise exception 'tracking_required_for_order';end if;
  select a.country_code into v_country from public.market_order_shipping_addresses a where a.order_id=o.id;
  if o.fulfillment_group='shipping' and v_country is distinct from 'DE' then raise exception 'release1_germany_only';end if;
  update public.market_orders set shipping_method=p_shipping_method,shipping_cost=round(p_shipping_cost,2),shipping_note=nullif(left(trim(coalesce(p_shipping_note,'')),240),''),shipping_quote_status='confirmed',shipping_profile_id=null,shipping_profile_rule_id=null,shipping_quote_country_code=v_country,total_amount=round(subtotal+p_shipping_cost,2),shipping_savings=round(separate_shipping_sum-p_shipping_cost,2),updated_at=now() where id=o.id;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_market_pickup_handover_b07(p_order_id uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare o public.market_orders;h dv_market_private.market_pickup_handovers;v_now timestamptz:=now();v_code text:=upper(trim(coalesce(p_code,'')));
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet';end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if not found or auth.uid()<>o.buyer_id then raise exception 'Nur der Käufer kann die Übergabe abschließen';end if;
  if o.fulfillment_group<>'pickup' or o.status not in ('open','in_progress') then raise exception 'pickup_not_available';end if;
  select * into h from dv_market_private.market_pickup_handovers where order_id=o.id for update;
  if not found or h.consumed_at is not null or h.expires_at<=v_now then raise exception 'pickup_code_expired';end if;
  if h.attempt_count>=8 then raise exception 'pickup_code_attempt_limit';end if;
  if digest(convert_to(v_code,'UTF8'),'sha256')<>h.code_hash then
    update dv_market_private.market_pickup_handovers set attempt_count=attempt_count+1,last_attempt_at=v_now,updated_at=v_now where order_id=o.id;
    return jsonb_build_object('ok',false,'error','pickup_code_invalid');
  end if;
  update dv_market_private.market_pickup_handovers set buyer_confirmed_at=v_now,consumed_at=v_now,last_attempt_at=v_now,attempt_count=attempt_count+1,updated_at=v_now where order_id=o.id;
  update public.market_orders set buyer_confirmed_at=coalesce(buyer_confirmed_at,v_now),buyer_received_ok_at=coalesce(buyer_received_ok_at,v_now),pickup_handover_completed_at=v_now,received_at=coalesce(received_at,v_now),updated_at=now() where id=o.id;
  update public.market_deals set buyer_confirmed_at=coalesce(buyer_confirmed_at,v_now),seller_confirmed_at=coalesce(seller_confirmed_at,h.seller_confirmed_at),received_at=coalesce(received_at,v_now),updated_at=now() where order_id=o.id and status in ('accepted','in_progress');
  perform dv_market_private.b07_complete_order(o.id,'pickup_bilateral_handover',v_now);
  return jsonb_build_object('ok',true,'completed_at',v_now);
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_market_swap_pickup_v1(p_thread_id uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_uid uuid:=auth.uid();v_thread dv_market_private.market_swap_threads%rowtype;v_h dv_market_private.market_swap_pickup_handovers%rowtype;
  v_now timestamptz:=now();v_code text:=upper(trim(coalesce(p_code,'')));
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id for update;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) then raise exception 'swap_not_participant';end if;
  if v_thread.status<>'bound' or v_thread.fulfillment_mode<>'pickup' then raise exception 'swap_pickup_not_available';end if;
  select * into v_h from dv_market_private.market_swap_pickup_handovers where thread_id=v_thread.id for update;
  if not found or v_h.consumed_at is not null or v_h.expires_at<=v_now then raise exception 'swap_pickup_code_expired';end if;
  if v_h.generated_by=v_uid then raise exception 'swap_pickup_requires_other_party';end if;
  if v_h.attempt_count>=8 then raise exception 'pickup_code_attempt_limit';end if;
  if extensions.digest(pg_catalog.convert_to(v_code,'UTF8'),'sha256')<>v_h.code_hash then
    update dv_market_private.market_swap_pickup_handovers set attempt_count=attempt_count+1,last_attempt_at=v_now,updated_at=v_now where thread_id=v_thread.id;
    return jsonb_build_object('ok',false,'error','pickup_code_invalid');
  end if;
  update dv_market_private.market_swap_pickup_handovers set confirmed_by=v_uid,confirmed_at=v_now,consumed_at=v_now,last_attempt_at=v_now,attempt_count=attempt_count+1,updated_at=v_now where thread_id=v_thread.id;
  update dv_market_private.market_swap_threads set status='completed',completed_at=v_now,updated_at=v_now where id=v_thread.id;
  update public.market_listings l set status='sold',ended_at=coalesce(l.ended_at,v_now),updated_at=v_now
  where l.quantity_available=0
    and exists(select 1 from dv_market_private.market_swap_reservations r where r.thread_id=v_thread.id and r.listing_id=l.id)
    and not exists(select 1 from public.market_deals d where d.listing_id=l.id and d.status not in ('completed','cancelled'))
    and not exists(select 1 from public.market_offers o where o.listing_id=l.id and o.status='accepted' and not exists(select 1 from public.market_deals d2 where d2.offer_id=o.id))
    and not exists(select 1 from dv_market_private.market_swap_reservations r2 join dv_market_private.market_swap_threads t2 on t2.id=r2.thread_id where r2.listing_id=l.id and r2.thread_id<>v_thread.id and t2.status='bound');
  return jsonb_build_object('ok',true,'completed_at',v_now,'confirmation_mode','pickup_bilateral_handover');
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_market_swap_received_v1(p_thread_id uuid, p_sender_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_thread dv_market_private.market_swap_threads%rowtype;
  v_fulfillment dv_market_private.market_swap_fulfillments%rowtype;
  v_now timestamptz:=now();
  v_remaining integer;
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id for update;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) or v_thread.status not in ('bound','completed') then raise exception 'swap_not_receivable';end if;
  select * into v_fulfillment
  from dv_market_private.market_swap_fulfillments
  where thread_id=v_thread.id and sender_id=p_sender_id and receiver_id=v_uid for update;
  if not found or v_fulfillment.shipped_at is null then raise exception 'swap_shipment_not_confirmable';end if;
  if v_fulfillment.received_at is null then
    update dv_market_private.market_swap_fulfillments
    set received_at=v_now,receiver_confirmed_at=v_now,updated_at=v_now
    where thread_id=v_thread.id and sender_id=p_sender_id;
  end if;
  select count(*) into v_remaining
  from dv_market_private.market_swap_fulfillments
  where thread_id=v_thread.id and received_at is null;
  if v_remaining=0 and v_thread.status='bound' then
    update dv_market_private.market_swap_threads
    set status='completed',completed_at=v_now,updated_at=v_now
    where id=v_thread.id;
    update public.market_listings l
    set status='sold',ended_at=coalesce(l.ended_at,v_now),updated_at=v_now
    where l.quantity_available=0
      and exists(select 1 from dv_market_private.market_swap_reservations r where r.thread_id=v_thread.id and r.listing_id=l.id)
      and not exists(select 1 from public.market_deals d where d.listing_id=l.id and d.status not in ('completed','cancelled'))
      and not exists(
        select 1 from public.market_offers o
        where o.listing_id=l.id and o.status='accepted'
          and not exists(select 1 from public.market_deals d2 where d2.offer_id=o.id)
      )
      and not exists(
        select 1 from dv_market_private.market_swap_reservations r2
        join dv_market_private.market_swap_threads t2 on t2.id=r2.thread_id
        where r2.listing_id=l.id and r2.thread_id<>v_thread.id and t2.status='bound'
      );
  end if;
  return jsonb_build_object('received_at',coalesce(v_fulfillment.received_at,v_now),
    'swap_completed',(v_remaining=0),'completed_at',case when v_remaining=0 then v_now else null end);
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_market_swap_revision_v1(p_thread_id uuid, p_revision_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();v_thread dv_market_private.market_swap_threads%rowtype;v_revision dv_market_private.market_swap_revisions%rowtype;
  v_confirmations integer;v_item record;v_bound_at timestamptz:=now();v_due_at timestamptz;v_owner uuid;v_receiver uuid;
  v_count integer;v_available_count integer;v_reference numeric(14,2);v_source jsonb;v_status text;v_source_hash bytea;
  v_address public.market_default_shipping_addresses%rowtype;v_address_json jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id for update;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) then raise exception 'swap_not_participant';end if;
  if v_thread.status='bound' and v_thread.bound_revision_id=p_revision_id then
    return jsonb_build_object('state','bound','thread_id',v_thread.id,'revision_id',p_revision_id,'fulfillment_mode',v_thread.fulfillment_mode,'binding_at',v_thread.binding_at,'shipping_due_at',v_thread.shipping_due_at);
  end if;
  if v_thread.status<>'negotiating' or v_thread.current_revision_id<>p_revision_id then raise exception 'swap_revision_not_current';end if;
  select * into v_revision from dv_market_private.market_swap_revisions where id=p_revision_id and thread_id=v_thread.id;
  if not found or v_revision.fulfillment_mode<>v_thread.fulfillment_mode then raise exception 'swap_revision_not_found';end if;
  perform dv_market_private.require_private_c2c_user(v_thread.party_a_id);perform dv_market_private.require_private_c2c_user(v_thread.party_b_id);
  insert into dv_market_private.market_swap_confirmations(revision_id,thread_id,user_id,content_sha256)
  values(v_revision.id,v_thread.id,v_uid,v_revision.content_sha256) on conflict(revision_id,user_id) do nothing;
  select count(*) into v_confirmations from dv_market_private.market_swap_confirmations
  where revision_id=v_revision.id and user_id in (v_thread.party_a_id,v_thread.party_b_id) and content_sha256=v_revision.content_sha256;
  if v_confirmations<2 then return jsonb_build_object('state','awaiting_other_confirmation','thread_id',v_thread.id,'revision_id',v_revision.id,'confirmation_count',v_confirmations);end if;

  for v_item in
    select ri.listing_id,ri.owner_id,ri.quantity,ri.item_snapshot,l.status,l.seller_id,l.listing_type,l.quantity_available,l.updated_at
    from dv_market_private.market_swap_revision_items ri join public.market_listings l on l.id=ri.listing_id
    where ri.revision_id=v_revision.id order by ri.listing_id for update of l
  loop
    if v_item.seller_id<>v_item.owner_id or v_item.listing_type not in ('trade','sale_or_trade') or v_item.status<>'active'
       or coalesce(v_item.quantity_available,0)<v_item.quantity or v_item.updated_at is distinct from (v_item.item_snapshot->>'listing_updated_at')::timestamptz then raise exception 'swap_listing_changed_before_binding';end if;
    update public.market_listings set quantity_available=quantity_available-v_item.quantity,status=case when quantity_available-v_item.quantity=0 then 'reserved' else status end,updated_at=now() where id=v_item.listing_id;
    insert into dv_market_private.market_swap_reservations(thread_id,revision_id,listing_id,owner_id,quantity,reserved_at)
    values(v_thread.id,v_revision.id,v_item.listing_id,v_item.owner_id,v_item.quantity,v_bound_at);
  end loop;
  if (select count(*) from dv_market_private.market_swap_reservations where thread_id=v_thread.id)<>(select count(*) from dv_market_private.market_swap_revision_items where revision_id=v_revision.id) then raise exception 'swap_reservation_incomplete';end if;

  v_due_at:=case when v_thread.fulfillment_mode='shipping' then dv_market_private.b07_add_workdays_de(v_bound_at,3) else null end;
  foreach v_owner in array array[v_thread.party_a_id,v_thread.party_b_id]::uuid[] loop
    v_receiver:=case when v_owner=v_thread.party_a_id then v_thread.party_b_id else v_thread.party_a_id end;
    if v_thread.fulfillment_mode='shipping' then
      select * into v_address from public.market_default_shipping_addresses where user_id=v_owner;
      if not found or v_address.country_code<>'DE' then raise exception 'swap_shipping_address_required';end if;
      v_address_json:=jsonb_build_object('recipient_name',v_address.recipient_name,'street_line1',v_address.street_line1,'street_line2',v_address.street_line2,'postal_code',v_address.postal_code,'city',v_address.city,'country_code',v_address.country_code);
      insert into dv_market_private.market_swap_shipping_addresses(thread_id,user_id,recipient_name,street_line1,street_line2,postal_code,city,country_code,captured_at,content_sha256)
      values(v_thread.id,v_owner,v_address.recipient_name,v_address.street_line1,v_address.street_line2,v_address.postal_code,v_address.city,'DE',v_bound_at,extensions.digest(pg_catalog.convert_to(v_address_json::text,'UTF8'),'sha256'));
    end if;

    select count(*),count(reference_value_eur),case when count(*)=count(reference_value_eur) then round(sum(reference_value_eur*quantity),2) else null end,
      coalesce(jsonb_agg(jsonb_build_object('listing_id',listing_id,'quantity',quantity,'reference_value_eur',reference_value_eur,'reference_value_source',reference_value_source,'item_sha256',encode(item_sha256,'hex')) order by listing_id),'[]'::jsonb)
    into v_count,v_available_count,v_reference,v_source from dv_market_private.market_swap_revision_items where revision_id=v_revision.id and owner_id=v_owner;
    if v_count<1 then raise exception 'swap_side_empty_at_binding';end if;
    v_status:=case when v_count=v_available_count then 'reference_only_unapproved' else 'incomplete_reference' end;
    v_source_hash:=extensions.digest(pg_catalog.convert_to(v_source::text,'UTF8'),'sha256');
    insert into dv_market_private.market_swap_value_snapshots(thread_id,revision_id,owner_id,item_count,reference_value_eur,valuation_status,source_snapshot,source_snapshot_sha256,captured_at)
    values(v_thread.id,v_revision.id,v_owner,v_count,v_reference,v_status,v_source,v_source_hash,v_bound_at);
    if v_thread.fulfillment_mode='shipping' then
      insert into dv_market_private.market_swap_fulfillments(thread_id,sender_id,receiver_id,shipping_due_at,goods_reference_value_eur,tracking_required)
      values(v_thread.id,v_owner,v_receiver,v_due_at,v_reference,(v_reference is null or v_reference>25));
    end if;
  end loop;

  update dv_market_private.market_swap_threads set status='bound',bound_revision_id=v_revision.id,binding_at=v_bound_at,shipping_due_at=v_due_at,updated_at=v_bound_at where id=v_thread.id;
  return jsonb_build_object('state','bound','thread_id',v_thread.id,'revision_id',v_revision.id,'fulfillment_mode',v_thread.fulfillment_mode,'binding_at',v_bound_at,'shipping_due_at',v_due_at,'confirmation_count',2);
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_market_withdrawal_v1(p_draft_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare v_uid uuid:=auth.uid();d dv_market_private.market_withdrawal_drafts%rowtype;
  s dv_market_private.market_contract_snapshots%rowtype;w dv_market_private.market_withdrawals%rowtype;
  v_contract_id uuid;v_text text;v_evidence jsonb;v_submitted timestamptz:=clock_timestamp();
  v_seller_email text;v_seller_name text;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  select * into w from dv_market_private.market_withdrawals where draft_id=p_draft_id;
  if found then
    if w.buyer_id<>v_uid then raise exception 'withdrawal_access_denied'; end if;
    return jsonb_build_object('replayed',true,'withdrawal_id',w.id,'submitted_at',w.submitted_at,
      'contract_snapshot_id',w.contract_snapshot_id,'confirmation_email',w.confirmation_email,
      'receipt_sha256',encode(w.content_sha256,'hex'));
  end if;
  select contract_snapshot_id into v_contract_id
  from dv_market_private.market_withdrawal_drafts where id=p_draft_id and buyer_id=v_uid;
  if not found then raise exception 'withdrawal_draft_expired'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_contract_id::text,0));
  select * into d from dv_market_private.market_withdrawal_drafts where id=p_draft_id and buyer_id=v_uid for update;
  if not found then
    select * into w from dv_market_private.market_withdrawals where draft_id=p_draft_id;
    if found then
      return jsonb_build_object('replayed',true,'withdrawal_id',w.id,'submitted_at',w.submitted_at,
        'contract_snapshot_id',w.contract_snapshot_id,'confirmation_email',w.confirmation_email,
        'receipt_sha256',encode(w.content_sha256,'hex'));
    end if;
    raise exception 'withdrawal_draft_expired';
  end if;
  if d.expires_at<=now() then raise exception 'withdrawal_draft_expired'; end if;
  select * into w from dv_market_private.market_withdrawals
  where contract_snapshot_id=d.contract_snapshot_id and buyer_id=v_uid;
  if found then
    delete from dv_market_private.market_withdrawal_drafts where id=d.id;
    return jsonb_build_object('replayed',true,'withdrawal_id',w.id,'submitted_at',w.submitted_at,
      'contract_snapshot_id',w.contract_snapshot_id,'confirmation_email',w.confirmation_email,
      'receipt_sha256',encode(w.content_sha256,'hex'));
  end if;
  select * into s from dv_market_private.market_contract_snapshots
  where id=d.contract_snapshot_id
    and buyer_id=v_uid
    and contract_classification='b2c'
    and withdrawal_eligible
    and seller_type='trader'
    and buyer_type='consumer'
    and nullif(trim(seller_party->>'public_email'),'') is not null;
  if not found then raise exception 'withdrawal_contract_not_eligible'; end if;
  if s.seller_id<>d.seller_id then raise exception 'withdrawal_snapshot_mismatch'; end if;
  v_seller_email:=lower(trim(s.seller_party->>'public_email'));
  v_seller_name:=coalesce(nullif(s.seller_party->>'business_name',''),s.seller_party->>'legal_name');
  v_text:=format(
    E'Widerrufserklärung\nName: %s\nVertrag: %s\nOrder: %s\nProdukt: %s\nErklärung: Hiermit widerrufe ich den oben bezeichneten Vertrag.\nEingang: %s',
    d.consumer_name,s.id,s.order_id,coalesce(s.product_snapshot->>'title','DUELVANTA Produkt'),
    to_char(v_submitted at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
  v_evidence:=jsonb_build_object(
    'contract_domain','marketplace_b2c','contract_snapshot_id',s.id,'order_id',s.order_id,'deal_id',s.deal_id,
    'buyer_id',v_uid,'seller_id',s.seller_id,'seller_recipient_email',v_seller_email,
    'consumer_name',d.consumer_name,'confirmation_email',d.confirmation_email,
    'declaration_text',v_text,'submitted_at',v_submitted
  );
  insert into dv_market_private.market_withdrawals(
    draft_id,contract_snapshot_id,order_id,deal_id,buyer_id,seller_id,contract_domain,consumer_name,
    confirmation_email,declaration_text,submitted_at,evidence_snapshot,content_sha256
  ) values(
    d.id,s.id,s.order_id,s.deal_id,v_uid,s.seller_id,'marketplace_b2c',d.consumer_name,d.confirmation_email,
    v_text,v_submitted,v_evidence,digest(convert_to(v_evidence::text,'UTF8'),'sha256')
  ) returning * into w;
  insert into dv_market_private.marketplace_message_outbox(
    contract_snapshot_id,recipient_kind,recipient_user_id,recipient_email,message_kind,payload,dedupe_key
  ) values(
    s.id,'buyer',v_uid,d.confirmation_email,'withdrawal_receipt',
    jsonb_build_object('withdrawal_id',w.id,'contract_domain','marketplace_b2c','contract_snapshot_id',s.id,'order_id',s.order_id,
      'product_title',s.product_snapshot->>'title','consumer_name',d.consumer_name,
      'submitted_at',v_submitted,'declaration_text',v_text,'evidence_sha256',encode(w.content_sha256,'hex')),
    'withdrawal_receipt:'||s.id::text
  ) on conflict(dedupe_key) do nothing;
  insert into dv_market_private.marketplace_message_outbox(
    contract_snapshot_id,recipient_kind,recipient_user_id,recipient_email,message_kind,payload,dedupe_key
  ) values(
    s.id,'seller',s.seller_id,v_seller_email,'withdrawal_notice',
    jsonb_build_object('withdrawal_id',w.id,'contract_domain','marketplace_b2c','contract_snapshot_id',s.id,'order_id',s.order_id,
      'product_title',s.product_snapshot->>'title','seller_name',v_seller_name,'consumer_name',d.consumer_name,
      'submitted_at',v_submitted,'declaration_text',v_text,'evidence_sha256',encode(w.content_sha256,'hex')),
    'withdrawal_notice:'||s.id::text
  ) on conflict(dedupe_key) do nothing;
  delete from dv_market_private.market_withdrawal_drafts where id=d.id;
  return jsonb_build_object('replayed',false,'withdrawal_id',w.id,'submitted_at',w.submitted_at,
    'contract_snapshot_id',w.contract_snapshot_id,'confirmation_email',w.confirmation_email,
    'receipt_sha256',encode(w.content_sha256,'hex'));
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_my_market_trade_eligibility(p_date_of_birth date, p_residence_country_code text, p_confirm_private_buyer boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_country text := upper(trim(coalesce(p_residence_country_code,'')));
  v_buyer boolean := coalesce(p_confirm_private_buyer,false);
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_date_of_birth is null
     or p_date_of_birth > current_date - interval '18 years'
     or p_date_of_birth < current_date - interval '120 years' then
    raise exception 'trade_must_be_adult';
  end if;
  if v_country <> 'DE' then raise exception 'trade_release1_germany_only'; end if;
  insert into dv_market_private.trade_user_eligibility(
    user_id,date_of_birth,residence_country_code,private_buyer_confirmed,confirmed_at,buyer_confirmed_at,updated_at
  ) values(v_uid,p_date_of_birth,'DE',v_buyer,now(),case when v_buyer then now() else null end,now())
  on conflict(user_id) do update set
    date_of_birth=excluded.date_of_birth,
    residence_country_code='DE',
    private_buyer_confirmed=dv_market_private.trade_user_eligibility.private_buyer_confirmed or excluded.private_buyer_confirmed,
    buyer_confirmed_at=case
      when dv_market_private.trade_user_eligibility.private_buyer_confirmed then dv_market_private.trade_user_eligibility.buyer_confirmed_at
      when excluded.private_buyer_confirmed then now()
      else null
    end,
    updated_at=now();
  return public.get_my_market_trade_eligibility();
end
$function$

CREATE OR REPLACE FUNCTION public.correct_market_tax_remuneration(p_original_event_id uuid, p_event_key text, p_occurred_at timestamp with time zone, p_gross_reversal numeric, p_platform_fee_reversal numeric DEFAULT 0, p_commission_reversal numeric DEFAULT 0, p_withheld_tax_reversal numeric DEFAULT 0, p_void_activity boolean DEFAULT false, p_source_reference text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_original dv_market_private.market_tax_events%rowtype;
  v_event dv_market_private.market_tax_events%rowtype;
  v_gross numeric:=round(coalesce(p_gross_reversal,0),2);
  v_fee numeric:=round(coalesce(p_platform_fee_reversal,0),2);
  v_commission numeric:=round(coalesce(p_commission_reversal,0),2);
  v_tax numeric:=round(coalesce(p_withheld_tax_reversal,0),2);
  v_net numeric;
  v_used record;
  v_evidence jsonb:=coalesce(p_evidence,'{}'::jsonb);
begin
  if p_original_event_id is null or p_occurred_at is null
     or char_length(trim(coalesce(p_event_key,''))) not between 8 and 200 then
    raise exception 'tax_correction_input_invalid';
  end if;
  select * into v_original from dv_market_private.market_tax_events
  where id=p_original_event_id and event_type='remuneration_paid_or_credited' for update;
  if not found then raise exception 'tax_original_event_not_found'; end if;
  if p_occurred_at<v_original.occurred_at then raise exception 'tax_correction_time_invalid'; end if;
  if v_gross<=0 or v_fee<0 or v_commission<0 or v_tax<0
     or v_gross<v_fee+v_commission+v_tax then raise exception 'tax_correction_amount_invalid'; end if;

  select coalesce(-sum(gross_consideration_delta),0) gross,
         coalesce(-sum(platform_fee_delta),0) fee,
         coalesce(-sum(commission_delta),0) commission,
         coalesce(-sum(withheld_tax_delta),0) tax,
         coalesce(-sum(remuneration_delta),0) net,
         coalesce(-sum(activity_count_delta),0) voided
  into v_used
  from dv_market_private.market_tax_events where correction_of=v_original.id;

  v_net:=round(v_gross-v_fee-v_commission-v_tax,2);
  if v_used.gross+v_gross>v_original.gross_consideration_delta
     or v_used.fee+v_fee>v_original.platform_fee_delta
     or v_used.commission+v_commission>v_original.commission_delta
     or v_used.tax+v_tax>v_original.withheld_tax_delta
     or v_used.net+v_net>v_original.remuneration_delta then
    raise exception 'tax_correction_exceeds_original';
  end if;
  if coalesce(p_void_activity,false) and (
       v_used.voided<>0
       or v_used.gross+v_gross<>v_original.gross_consideration_delta
       or v_used.fee+v_fee<>v_original.platform_fee_delta
       or v_used.commission+v_commission<>v_original.commission_delta
       or v_used.tax+v_tax<>v_original.withheld_tax_delta
       or v_used.net+v_net<>v_original.remuneration_delta
     ) then raise exception 'tax_activity_void_requires_full_reversal'; end if;

  v_evidence:=v_evidence||jsonb_build_object(
    'original_event_id',v_original.id,'contract_snapshot_id',v_original.contract_snapshot_id,
    'source_reference',nullif(trim(coalesce(p_source_reference,'')),''),
    'void_activity',coalesce(p_void_activity,false)
  );
  insert into dv_market_private.market_tax_events(
    event_key,event_type,seller_id,deal_id,contract_snapshot_id,correction_of,occurred_at,
    reporting_year,reporting_quarter,currency,gross_consideration_delta,
    platform_fee_delta,commission_delta,withheld_tax_delta,remuneration_delta,
    activity_count_delta,source_type,source_reference,evidence,evidence_sha256,recorded_by
  ) values (
    trim(p_event_key),'remuneration_correction',v_original.seller_id,v_original.deal_id,
    v_original.contract_snapshot_id,v_original.id,p_occurred_at,
    v_original.reporting_year,v_original.reporting_quarter,v_original.currency,
    -v_gross,-v_fee,-v_commission,-v_tax,-v_net,
    case when coalesce(p_void_activity,false) then -1 else 0 end,
    'system_correction',nullif(left(trim(coalesce(p_source_reference,'')),500),''),
    v_evidence,digest(v_evidence::text,'sha256'),auth.uid()
  ) returning * into v_event;
  return jsonb_build_object('event_id',v_event.id,'event_type',v_event.event_type,
    'reporting_year',v_event.reporting_year,'reporting_quarter',v_event.reporting_quarter,
    'remuneration',v_event.remuneration_delta,'activity_count_delta',v_event.activity_count_delta);
exception when unique_violation then
  select * into v_event from dv_market_private.market_tax_events where event_key=trim(p_event_key);
  if v_event.correction_of=p_original_event_id and v_event.event_type='remuneration_correction'
     and v_event.gross_consideration_delta=-v_gross and v_event.platform_fee_delta=-v_fee
     and v_event.commission_delta=-v_commission and v_event.withheld_tax_delta=-v_tax
     and v_event.occurred_at=p_occurred_at then
    return jsonb_build_object('event_id',v_event.id,'event_type',v_event.event_type,
      'reporting_year',v_event.reporting_year,'reporting_quarter',v_event.reporting_quarter,
      'remuneration',v_event.remuneration_delta,'activity_count_delta',v_event.activity_count_delta,'replayed',true);
  end if;
  raise exception 'tax_event_idempotency_conflict';
end
$function$

CREATE OR REPLACE FUNCTION public.create_battle_match_v2(p_tcg text, p_visibility text DEFAULT 'public'::text, p_title text DEFAULT NULL::text, p_language text DEFAULT 'de'::text, p_mode text DEFAULT 'casual'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_profile public.profiles; v_code text;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_tcg not in ('pokemon','one_piece') then raise exception 'Ungültiges TCG'; end if;
  if p_visibility not in ('public','private') then raise exception 'Ungültige Sichtbarkeit'; end if;
  if p_mode not in ('casual','ranked') then raise exception 'Ungültiger Modus'; end if;
  if p_mode='ranked' and p_visibility<>'public' then raise exception 'Ranked Matches sind in der Beta nur öffentlich'; end if;

  select * into v_profile from public.profiles where id=auth.uid() for share;
  if v_profile.id is null then raise exception 'Profil nicht gefunden'; end if;
  if coalesce(v_profile.account_status,'beta') not in ('beta','active') then raise exception 'Account ist nicht aktiv'; end if;
  if coalesce(v_profile.safety_restricted,false) then raise exception 'BATTLE ist für diesen Account eingeschränkt'; end if;
  if v_profile.data_processing_restricted_at is not null then
    raise exception 'account_data_processing_restricted' using errcode='42501';
  end if;

  if exists(select 1 from public.battle_matches where (host_id=auth.uid() or guest_id=auth.uid()) and status in ('waiting','ready','live','dispute')) then
    raise exception 'Du hast bereits ein aktives Match';
  end if;

  if p_visibility='private' then v_code:=upper(substr(md5(gen_random_uuid()::text),1,6)); end if;
  insert into public.battle_matches(host_id,tcg,mode,visibility,invite_code,title,language,host_display_name,host_founder_number)
  values(auth.uid(),p_tcg,p_mode,p_visibility,v_code,nullif(trim(p_title),''),coalesce(nullif(p_language,''),'de'),coalesce(v_profile.display_name,v_profile.username,'DUELVANTA Player'),v_profile.founder_number)
  returning id into v_id;
  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_market_offer_v2(p_listing_id uuid, p_requested_quantity integer, p_amount numeric, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  l public.market_listings;
  v_id uuid;
  v_list_unit numeric;
  t jsonb;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into l from public.market_listings where id=p_listing_id and status='active' for update;
  if l.id is null or l.seller_id=auth.uid() then raise exception 'Angebot nicht möglich'; end if;
  if l.pricing_mode='fixed' then raise exception 'Dieses Produkt wird zum Festpreis angeboten'; end if;
  if p_requested_quantity is null or p_requested_quantity not between 1 and 1000 then raise exception 'Ungültige Menge'; end if;
  if l.active_until is not null and l.active_until<=now() then raise exception 'Angebot abgelaufen'; end if;
  if (l.product_kind='sealed' and (p_requested_quantity<l.minimum_purchase_quantity or p_requested_quantity>l.quantity_available))
     or (l.product_kind<>'sealed' and p_requested_quantity<>1) then
    raise exception 'Gewünschte Menge ist nicht verfügbar';
  end if;
  if p_amount::text in ('NaN','Infinity','-Infinity') or coalesce(round(p_amount,2),0)<=0 then raise exception 'Ungültige Angebotssumme'; end if;

  v_list_unit:=l.asking_price;
  if l.product_kind='sealed' then
    for t in select value from jsonb_array_elements(coalesce(l.quantity_pricing,'[]'::jsonb)) order by (value->>'min_quantity')::int loop
      if p_requested_quantity >= (t->>'min_quantity')::int then v_list_unit:=(t->>'unit_price')::numeric; end if;
    end loop;
  end if;

  insert into public.market_offers(
    listing_id,buyer_id,seller_id,offer_type,amount,currency,message,requested_quantity,
    unit_price_snapshot,listed_unit_price_snapshot,listed_total_snapshot
  ) values(
    l.id,auth.uid(),l.seller_id,'price',round(p_amount,2),'EUR',nullif(left(trim(coalesce(p_message,'')),500),''),p_requested_quantity,
    round(p_amount/p_requested_quantity,2),round(v_list_unit,2),round(v_list_unit*p_requested_quantity,2)
  ) returning id into v_id;
  update public.market_offers set listing_snapshot=jsonb_build_object(
    'card_name',l.card_name,'product_kind',l.product_kind,'sealed_category',l.sealed_category,
    'language',l.language,'set_name',l.set_name,'base_unit_price',l.asking_price,'shipping_method',l.shipping_method,'shipping_cost',l.shipping_cost
  ) where id=v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_market_offer_v3(p_listing_id uuid, p_requested_quantity integer, p_amount numeric, p_message text, p_expected_updated_at timestamp with time zone, p_offer_review_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare l public.market_listings;v_id uuid;v_review jsonb;v_hash text;
begin
 if auth.uid() is null then raise exception 'not_authenticated'; end if;
 if p_expected_updated_at is null or nullif(lower(trim(coalesce(p_offer_review_hash,''))),'') is null then raise exception 'offer_review_required'; end if;
 select * into l from public.market_listings where id=p_listing_id for update;if not found then raise exception 'offer_not_available'; end if;
 v_review:=public.review_market_price_offer_v1(p_listing_id,p_requested_quantity,p_amount);v_hash:=v_review->>'offer_review_hash';
 if l.updated_at is distinct from p_expected_updated_at or (v_review->>'listing_updated_at')::timestamptz is distinct from p_expected_updated_at or lower(trim(p_offer_review_hash))<>v_hash then raise exception 'offer_review_changed'; end if;
 insert into public.market_offers(listing_id,buyer_id,seller_id,offer_type,amount,currency,message,requested_quantity,unit_price_snapshot,listed_unit_price_snapshot,listed_total_snapshot,buyer_type_snapshot,listing_snapshot,contract_review_snapshot,offer_review_hash)
 values(l.id,auth.uid(),l.seller_id,'price',(v_review->>'offered_goods_total')::numeric,'EUR',nullif(left(trim(coalesce(p_message,'')),500),''),p_requested_quantity,
   (v_review->>'offer_unit_price')::numeric,(v_review->>'listed_unit_price')::numeric,(v_review->>'listed_goods_total')::numeric,v_review->>'buyer_type',
   jsonb_build_object('card_name',v_review->'product'->>'title','product_kind',v_review->'fulfillment_snapshot'->>'product_kind','sealed_category',v_review->'fulfillment_snapshot'->>'sealed_category','language',v_review->'product'->>'language','set_name',v_review->'product'->>'set_name','base_unit_price',l.asking_price,'shipping_method',v_review->>'shipping_method','shipping_cost',(v_review->>'shipping_cost')::numeric),
   v_review-'offer_review_hash',v_hash) returning id into v_id;
 return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_market_pickup_handover_code_b07(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare o public.market_orders;v_code text;v_now timestamptz:=now();
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet';end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if not found or auth.uid()<>o.seller_id then raise exception 'Nur der Verkäufer kann den Übergabecode erzeugen';end if;
  if o.fulfillment_group<>'pickup' or o.status not in ('open','in_progress') then raise exception 'pickup_not_available';end if;
  if o.payment_status not in ('not_required','paid') or (o.payment_provider<>'manual_beta' and o.payment_status<>'paid') then raise exception 'Übergabe erst nach vollständiger Zahlung';end if;
  if exists(select 1 from public.market_order_cases c where c.order_id=o.id and c.status in ('open','accepted_refund_pending')) then raise exception 'Offener Vorgang blockiert die Übergabe';end if;
  v_code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
  insert into dv_market_private.market_pickup_handovers(order_id,code_hash,generated_at,expires_at,seller_confirmed_at,buyer_confirmed_at,consumed_at,attempt_count,updated_at)
  values(o.id,digest(convert_to(v_code,'UTF8'),'sha256'),v_now,v_now+interval '2 hours',v_now,null,null,0,v_now)
  on conflict(order_id) do update set code_hash=excluded.code_hash,generated_at=v_now,expires_at=v_now+interval '2 hours',seller_confirmed_at=v_now,buyer_confirmed_at=null,consumed_at=null,attempt_count=0,updated_at=v_now;
  update public.market_orders set status='in_progress',seller_confirmed_at=coalesce(seller_confirmed_at,v_now),updated_at=now() where id=o.id;
  return jsonb_build_object('order_id',o.id,'handover_code',v_code,'expires_at',v_now+interval '2 hours');
end
$function$

CREATE OR REPLACE FUNCTION public.create_market_swap_pickup_code_v1(p_thread_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'dv_market_private', 'extensions'
AS $function$
declare
  v_uid uuid:=auth.uid();v_thread dv_market_private.market_swap_threads%rowtype;v_h dv_market_private.market_swap_pickup_handovers%rowtype;
  v_now timestamptz:=now();v_code text:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id for update;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) then raise exception 'swap_not_participant';end if;
  if v_thread.status<>'bound' or v_thread.fulfillment_mode<>'pickup' then raise exception 'swap_pickup_not_available';end if;
  select * into v_h from dv_market_private.market_swap_pickup_handovers where thread_id=v_thread.id for update;
  if found and v_h.consumed_at is null and v_h.expires_at>v_now and v_h.generated_by<>v_uid then raise exception 'swap_pickup_code_already_active';end if;
  insert into dv_market_private.market_swap_pickup_handovers(thread_id,code_hash,generated_by,generated_at,expires_at,confirmed_by,confirmed_at,consumed_at,last_attempt_at,attempt_count,updated_at)
  values(v_thread.id,extensions.digest(pg_catalog.convert_to(v_code,'UTF8'),'sha256'),v_uid,v_now,v_now+interval '2 hours',null,null,null,null,0,v_now)
  on conflict(thread_id) do update set code_hash=excluded.code_hash,generated_by=v_uid,generated_at=v_now,expires_at=v_now+interval '2 hours',confirmed_by=null,confirmed_at=null,consumed_at=null,last_attempt_at=null,attempt_count=0,updated_at=v_now;
  return jsonb_build_object('thread_id',v_thread.id,'handover_code',v_code,'expires_at',v_now+interval '2 hours');
end
$function$

CREATE OR REPLACE FUNCTION public.create_market_swap_proposal_v1(p_target_listing_id uuid, p_offered_listing_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_target public.market_listings%rowtype; v_thread_id uuid; v_revision_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  select * into v_target from public.market_listings where id=p_target_listing_id;
  if not found or v_target.seller_id=v_uid or v_target.status<>'active' or v_target.listing_type not in ('trade','sale_or_trade') or coalesce(v_target.quantity_available,0)<1 then raise exception 'swap_target_unavailable'; end if;
  perform dv_market_private.require_private_c2c_user(v_uid);
  perform dv_market_private.require_private_c2c_user(v_target.seller_id);
  insert into dv_market_private.market_swap_threads(party_a_id,party_b_id) values(v_uid,v_target.seller_id) returning id into v_thread_id;
  v_revision_id:=dv_market_private.create_market_swap_revision(v_thread_id,v_uid,p_offered_listing_ids,array[p_target_listing_id]::uuid[]);
  return v_thread_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_market_swap_proposal_v2(p_target_listing_id uuid, p_offered_listing_ids uuid[], p_fulfillment_mode text DEFAULT 'shipping'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();v_target public.market_listings%rowtype;v_thread_id uuid;v_mode text:=lower(trim(coalesce(p_fulfillment_mode,'shipping')));
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  if v_mode not in ('shipping','pickup') then raise exception 'swap_fulfillment_mode_invalid';end if;
  select * into v_target from public.market_listings where id=p_target_listing_id;
  if not found or v_target.seller_id=v_uid or v_target.status<>'active' or v_target.listing_type not in ('trade','sale_or_trade') or coalesce(v_target.quantity_available,0)<1 then raise exception 'swap_target_unavailable';end if;
  perform dv_market_private.require_private_c2c_user(v_uid);perform dv_market_private.require_private_c2c_user(v_target.seller_id);
  insert into dv_market_private.market_swap_threads(party_a_id,party_b_id,fulfillment_mode)
  values(v_uid,v_target.seller_id,v_mode) returning id into v_thread_id;
  perform dv_market_private.create_market_swap_revision(v_thread_id,v_uid,p_offered_listing_ids,array[p_target_listing_id]::uuid[]);
  return v_thread_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_sealed_market_listing_draft(p_tcg text, p_product_name text, p_set_code text, p_language text, p_sealed_category text, p_sealed_condition text, p_bundle_quantity integer, p_package_contents text, p_units_per_container integer, p_weight_grams integer, p_length_mm integer, p_width_mm integer, p_height_mm integer, p_listing_type text, p_asking_price numeric, p_seller_note text, p_shipping_method text, p_shipping_cost numeric, p_shipping_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; p public.profiles; v_name text;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  if p_tcg not in ('pokemon','one_piece','other') then raise exception 'Ungültiges TCG'; end if;
  if nullif(trim(coalesce(p_product_name,'')),'') is null then raise exception 'Produktname fehlt'; end if;
  if p_sealed_category not in ('booster','display','promo_pack','etb_collection','deck','tin','box','case','other') then raise exception 'Ungültige Produktart'; end if;
  if p_sealed_condition not in ('factory_sealed','sealed_minor_wear','sealed_damage','opened_case_sealed_units') then raise exception 'Ungültiger Versiegelungszustand'; end if;
