  if p_listing_type='sale' and (p_asking_price is null or p_asking_price<=0) then raise exception 'Verkauf benötigt einen positiven Preis'; end if;
  if coalesce(p_bundle_quantity,0)<1 or p_bundle_quantity>1000 then raise exception 'Ungültige Menge'; end if;
  select * into p from public.profiles where id=auth.uid();
  v_name:=coalesce(p.display_name,p.username,'DUELVANTA Member');
  insert into public.market_listings(
    seller_id,collection_item_id,listing_type,status,asking_price,tcg,card_name,set_name,language,condition,
    seller_note,seller_display_name,seller_founder_number,product_kind,sealed_category,sealed_condition,bundle_quantity,
    package_contents,units_per_container,weight_grams,length_mm,width_mm,height_mm,shipping_method,shipping_cost,shipping_note
  ) values(
    auth.uid(),null,p_listing_type,'draft',p_asking_price,p_tcg,left(trim(p_product_name),180),nullif(left(trim(coalesce(p_set_code,'')),120),''),nullif(left(trim(coalesce(p_language,'')),40),''),'sealed',
    nullif(left(trim(coalesce(p_seller_note,'')),800),''),v_name,p.founder_number,'sealed',p_sealed_category,p_sealed_condition,p_bundle_quantity,
    nullif(left(trim(coalesce(p_package_contents,'')),240),''),p_units_per_container,p_weight_grams,p_length_mm,p_width_mm,p_height_mm,p_shipping_method,coalesce(p_shipping_cost,0),nullif(left(trim(coalesce(p_shipping_note,'')),240),'')
  ) returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_sealed_market_listing_draft_v2(p_tcg text, p_product_name text, p_set_code text, p_language text, p_sealed_category text, p_sealed_condition text, p_stock_quantity integer, p_minimum_purchase_quantity integer, p_quantity_pricing jsonb, p_package_contents text, p_units_per_container integer, p_weight_grams integer, p_length_mm integer, p_width_mm integer, p_height_mm integer, p_listing_type text, p_asking_price numeric, p_seller_note text, p_shipping_method text, p_shipping_cost numeric, p_shipping_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; p public.profiles; t jsonb; v_last int:=0;
begin
 if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
