CREATE OR REPLACE FUNCTION public.create_sealed_market_listing_draft_v3(p_tcg text, p_product_name text, p_set_code text, p_language text, p_sealed_category text, p_sealed_condition text, p_stock_quantity integer, p_minimum_purchase_quantity integer, p_quantity_pricing jsonb, p_package_contents text, p_units_per_container integer, p_weight_grams integer, p_length_mm integer, p_width_mm integer, p_height_mm integer, p_listing_type text, p_pricing_mode text, p_asking_price numeric, p_seller_note text, p_shipping_method text, p_shipping_cost numeric, p_shipping_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; p public.profiles; t jsonb; v_last int:=0;
begin
  if p_asking_price::text in ('NaN','Infinity','-Infinity') or p_shipping_cost::text in ('NaN','Infinity','-Infinity') then raise exception 'Ungültiger Preis'; end if;
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  if p_tcg not in ('pokemon','one_piece','other') or p_sealed_category not in ('booster','display','promo_pack','etb_collection','deck','tin','box','case','other') or p_sealed_condition not in ('factory_sealed','sealed_minor_wear','sealed_damage','opened_case_sealed_units') then raise exception 'Ungültige Produktdaten'; end if;
  if nullif(trim(coalesce(p_product_name,'')),'') is null then raise exception 'Produktname fehlt'; end if;
  if p_listing_type not in ('sale','trade','sale_or_trade') or p_pricing_mode not in ('fixed','negotiable') or (p_listing_type in ('sale','sale_or_trade') and coalesce(p_asking_price,0)<=0) then raise exception 'Ungültige Preis- oder Angebotsdaten'; end if;
  if p_listing_type='trade' then p_pricing_mode:='negotiable'; end if;
  if coalesce(p_stock_quantity,0) not between 1 and 1000 or coalesce(p_minimum_purchase_quantity,0) not between 1 and p_stock_quantity then raise exception 'Ungültige Menge'; end if;
  if jsonb_typeof(coalesce(p_quantity_pricing,'[]'))<>'array' or jsonb_array_length(coalesce(p_quantity_pricing,'[]'))>5 then raise exception 'Ungültige Mengenpreise'; end if;
  for t in select value from jsonb_array_elements(coalesce(p_quantity_pricing,'[]')) loop
    if coalesce((t->>'min_quantity')::int,0)<=p_minimum_purchase_quantity or (t->>'min_quantity')::int>p_stock_quantity or coalesce((t->>'unit_price')::numeric,0)<=0 or (t->>'unit_price')::numeric>=p_asking_price or (t->>'min_quantity')::int<=v_last then raise exception 'Ungültige Mengenpreisstaffel'; end if;
    v_last:=(t->>'min_quantity')::int;
  end loop;
  select * into p from public.profiles where id=auth.uid();
  insert into public.market_listings(
    seller_id,collection_item_id,listing_type,pricing_mode,status,asking_price,tcg,card_name,set_name,language,condition,
    seller_note,seller_display_name,seller_founder_number,product_kind,sealed_category,sealed_condition,bundle_quantity,
    stock_quantity,quantity_available,minimum_purchase_quantity,quantity_pricing,package_contents,units_per_container,
    weight_grams,length_mm,width_mm,height_mm,shipping_method,shipping_cost,shipping_note
  ) values(
    auth.uid(),null,p_listing_type,p_pricing_mode,'draft',p_asking_price,p_tcg,left(trim(p_product_name),180),
    nullif(left(trim(coalesce(p_set_code,'')),120),''),nullif(left(trim(coalesce(p_language,'')),40),''),'sealed',
    nullif(left(trim(coalesce(p_seller_note,'')),800),''),coalesce(p.display_name,p.username,'DUELVANTA Member'),p.founder_number,
    'sealed',p_sealed_category,p_sealed_condition,p_stock_quantity,p_stock_quantity,p_stock_quantity,p_minimum_purchase_quantity,
    coalesce(p_quantity_pricing,'[]'),nullif(left(trim(coalesce(p_package_contents,'')),240),''),p_units_per_container,
    p_weight_grams,p_length_mm,p_width_mm,p_height_mm,p_shipping_method,coalesce(p_shipping_cost,0),
    nullif(left(trim(coalesce(p_shipping_note,'')),240),'')
  ) returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.decide_marketplace_listing_notice(p_notice_id uuid, p_action text, p_basis_kind text, p_reference text, p_reason text, p_scope text DEFAULT 'Deutschland'::text, p_duration text DEFAULT 'bis zur Korrektur'::text, p_automated_means_used boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_notice dv_market_private.listing_notices%rowtype; v_action text:=lower(trim(coalesce(p_action,''))); v_basis text:=lower(trim(coalesce(p_basis_kind,''))); v_reason text:=trim(coalesce(p_reason,'')); v_seller uuid;
begin perform public.require_duelvanta_privileged_session();
  if not dv_market_private.notice_owner_caller() then raise exception 'owner_access_required'; end if;
  if v_action not in ('no_action','restrict_visibility','remove_listing') then raise exception 'invalid_notice_action'; end if;
  if v_basis not in ('law','terms','law_and_terms','no_violation') then raise exception 'invalid_decision_basis'; end if;
  if (v_action='no_action') <> (v_basis='no_violation') then raise exception 'decision_basis_mismatch'; end if;
  if char_length(v_reason) not between 30 and 5000 then raise exception 'decision_reason_invalid'; end if;
  if v_action<>'no_action' and char_length(trim(coalesce(p_reference,'')))<3 then raise exception 'decision_reference_required'; end if;

  select * into v_notice from dv_market_private.listing_notices where id=p_notice_id for update;
  if not found then raise exception 'notice_not_found'; end if;
  if v_notice.status not in ('submitted','under_review') then raise exception 'notice_already_decided'; end if;
  v_seller:=nullif(v_notice.listing_snapshot->>'seller_id','')::uuid;

  if v_action in ('restrict_visibility','remove_listing') and v_notice.listing_id is not null then
    update public.market_listings set status='paused',updated_at=now() where id=v_notice.listing_id;
  end if;

  update dv_market_private.listing_notices set
    status=case v_action when 'no_action' then 'decided_no_action' when 'restrict_visibility' then 'decided_restricted' else 'decided_removed' end,
    assigned_to=auth.uid(),decision_action=v_action,decision_basis_kind=v_basis,
    decision_reference=nullif(trim(coalesce(p_reference,'')),''),decision_reason=v_reason,
    decision_scope=case when v_action='no_action' then null else nullif(trim(coalesce(p_scope,'')),'') end,
    decision_duration=case when v_action='no_action' then null else nullif(trim(coalesce(p_duration,'')),'') end,
    automated_means_used=coalesce(p_automated_means_used,false),
    original_listing_status=coalesce(original_listing_status,listing_snapshot->>'status'),
    review_started_at=coalesce(review_started_at,now()),decided_at=now(),updated_at=now()
  where id=v_notice.id returning * into v_notice;

  insert into dv_market_private.listing_notice_events(notice_id,actor_id,event_type,event_data)
  values(v_notice.id,auth.uid(),'notice_decided',jsonb_build_object('action',v_action,'basis_kind',v_basis,'reference',p_reference,'automated_means_used',coalesce(p_automated_means_used,false)));
  insert into dv_market_private.marketplace_message_outbox(notice_id,recipient_kind,recipient_email,message_kind,payload)
  values(v_notice.id,'reporter',v_notice.reporter_email,'notice_decided',jsonb_build_object('case_reference',v_notice.case_reference,'action',v_action,'reason',v_reason,'redress','Interner Einspruch innerhalb von sechs Monaten sowie weitere gesetzliche Rechtsbehelfe.'));
  insert into dv_market_private.marketplace_message_outbox(notice_id,recipient_kind,recipient_user_id,message_kind,payload)
  values(v_notice.id,'seller',v_seller,'seller_statement_of_reasons',jsonb_build_object(
    'case_reference',v_notice.case_reference,'action',v_action,'scope',v_notice.decision_scope,'duration',v_notice.decision_duration,
    'facts',v_reason,'basis_kind',v_basis,'reference',v_notice.decision_reference,'automated_means_used',coalesce(p_automated_means_used,false),
    'redress','Interner Einspruch innerhalb von sechs Monaten, zertifizierte außergerichtliche Streitbeilegung oder gerichtlicher Rechtsbehelf.'
  ));
  return jsonb_build_object('case_reference',v_notice.case_reference,'status',v_notice.status,'decided_at',v_notice.decided_at);
end
$function$

CREATE OR REPLACE FUNCTION public.delete_my_sealed_market_listing_draft(p_listing_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l public.market_listings; v_paths text[];
begin
  select * into l from public.market_listings where id=p_listing_id for update;
  if l.id is null or l.seller_id<>auth.uid() or l.status<>'draft' then raise exception 'Nicht erlaubt'; end if;
  select coalesce(array_agg(storage_path order by sort_order),array[]::text[]) into v_paths from public.market_listing_images where listing_id=l.id;
  delete from public.market_listings where id=l.id;
  return v_paths;
end $function$

CREATE OR REPLACE FUNCTION public.dv_collect_move_card(p_item_id uuid, p_folder_id uuid, p_page integer, p_slot smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_source public.collection_items%rowtype;
  v_target public.collection_items%rowtype;
begin
  if v_user is null or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) then
    raise exception 'authentication required';
  end if;
  if p_folder_id is null or p_page not between 1 and 9999 or p_slot not between 1 and 9 then
    raise exception 'invalid binder destination';
  end if;
  if not exists (
    select 1 from public.collection_folders
    where id = p_folder_id and user_id = v_user
  ) then
    raise exception 'binder not found';
  end if;

  select * into v_source
  from public.collection_items
  where id = p_item_id and user_id = v_user and folder_id = p_folder_id
  for update;
  if not found then raise exception 'card not found'; end if;

  select * into v_target
  from public.collection_items
  where user_id = v_user and folder_id = p_folder_id
    and binder_page = p_page and binder_slot = p_slot and id <> p_item_id
  for update;

  if v_source.binder_page = p_page and v_source.binder_slot = p_slot then
    return jsonb_build_object('moved', false, 'reason', 'same_slot');
  end if;

  update public.collection_items
  set binder_page = null, binder_slot = null
  where id in (v_source.id, v_target.id) and user_id = v_user;

  update public.collection_items
  set binder_page = p_page, binder_slot = p_slot
  where id = v_source.id and user_id = v_user;

  if v_target.id is not null and v_source.binder_page is not null and v_source.binder_slot is not null then
    update public.collection_items
    set binder_page = v_source.binder_page, binder_slot = v_source.binder_slot
    where id = v_target.id and user_id = v_user;
  end if;

  return jsonb_build_object(
    'moved', true,
    'itemId', v_source.id,
    'swappedItemId', v_target.id,
    'page', p_page,
    'slot', p_slot
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.edit_my_market_listing(p_listing_id uuid, p_listing_type text, p_asking_price numeric, p_seller_note text)
 RETURNS market_listings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.market_listings;
begin
  if p_listing_type not in ('sale','trade','sale_or_trade') then raise exception 'Invalid listing type'; end if;
  if p_listing_type='sale' and (p_asking_price is null or p_asking_price <= 0) then raise exception 'Sale listings need a positive price'; end if;
  update public.market_listings
  set listing_type=p_listing_type, asking_price=p_asking_price, seller_note=nullif(trim(p_seller_note),''), updated_at=now()
  where id=p_listing_id and seller_id=auth.uid() and status in ('active','paused')
  returning * into v_row;
  if v_row.id is null then raise exception 'Listing not found or not editable'; end if;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.edit_my_market_listing_v2(p_listing_id uuid, p_listing_type text, p_asking_price numeric, p_seller_note text, p_shipping_method text, p_shipping_cost numeric, p_shipping_note text DEFAULT NULL::text)
 RETURNS market_listings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.market_listings;
begin
  if p_listing_type not in ('sale','trade','sale_or_trade') then raise exception 'Ungültige Angebotsart'; end if;
  if p_listing_type='sale' and (p_asking_price is null or p_asking_price <= 0) then raise exception 'Verkaufsangebote benötigen einen positiven Preis'; end if;
  if p_shipping_method not in ('standard_letter','tracked_letter','parcel','pickup','custom') then raise exception 'Ungültige Versandart'; end if;
  if p_shipping_cost is null or p_shipping_cost < 0 or p_shipping_cost > 500 then raise exception 'Ungültige Versandkosten'; end if;
  if p_shipping_method='pickup' and p_shipping_cost<>0 then raise exception 'Abholung muss 0 € Versandkosten haben'; end if;
  if p_shipping_method='custom' and nullif(trim(coalesce(p_shipping_note,'')),'') is null then raise exception 'Bitte Versandhinweis für individuelle Versandart angeben'; end if;

  update public.market_listings
  set listing_type=p_listing_type,
      asking_price=p_asking_price,
      seller_note=nullif(trim(p_seller_note),''),
      shipping_method=p_shipping_method,
      shipping_cost=round(p_shipping_cost,2),
      shipping_note=nullif(left(trim(coalesce(p_shipping_note,'')),240),''),
      updated_at=now()
  where id=p_listing_id and seller_id=auth.uid() and status in ('active','paused')
  returning * into v_row;
  if v_row.id is null then raise exception 'Anzeige nicht gefunden oder nicht bearbeitbar'; end if;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.edit_my_market_listing_v3(p_listing_id uuid, p_listing_type text, p_pricing_mode text, p_asking_price numeric, p_seller_note text, p_shipping_method text, p_shipping_cost numeric, p_shipping_note text DEFAULT NULL::text)
 RETURNS market_listings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.market_listings;
begin
  if p_asking_price::text in ('NaN','Infinity','-Infinity') or p_shipping_cost::text in ('NaN','Infinity','-Infinity') then raise exception 'Ungültiger Preis'; end if;
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  if p_listing_type not in ('sale','trade','sale_or_trade') then raise exception 'Ungültige Angebotsart'; end if;
  if p_pricing_mode not in ('fixed','negotiable') then raise exception 'Ungültige Preisart'; end if;
  if p_listing_type in ('sale','sale_or_trade') and (p_asking_price is null or p_asking_price<=0) then raise exception 'Verkaufsangebote benötigen einen positiven Preis'; end if;
  if p_shipping_method not in ('standard_letter','tracked_letter','parcel','pickup','custom') then raise exception 'Ungültige Versandart'; end if;
  if p_shipping_cost is null or p_shipping_cost<0 or p_shipping_cost>500 then raise exception 'Ungültige Versandkosten'; end if;
  if p_shipping_method='pickup' and p_shipping_cost<>0 then raise exception 'Abholung muss 0 € Versandkosten haben'; end if;
  if p_shipping_method='custom' and nullif(trim(coalesce(p_shipping_note,'')),'') is null then raise exception 'Bitte Versandhinweis für individuelle Versandart angeben'; end if;
  if p_listing_type='trade' then p_pricing_mode:='negotiable'; end if;

  update public.market_listings set
    listing_type=p_listing_type,pricing_mode=p_pricing_mode,asking_price=p_asking_price,
    seller_note=nullif(trim(p_seller_note),''),shipping_method=p_shipping_method,
    shipping_cost=round(p_shipping_cost,2),shipping_note=nullif(left(trim(coalesce(p_shipping_note,'')),240),''),updated_at=now()
  where id=p_listing_id and seller_id=auth.uid() and product_kind in ('single','graded') and status in ('active','paused')
  returning * into v_row;
  if v_row.id is null then raise exception 'Anzeige nicht gefunden oder nicht bearbeitbar'; end if;
