CREATE OR REPLACE FUNCTION public.link_offer_notification_to_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.offer_id is null or new.order_id is null then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.order_id is not distinct from new.order_id then
    return new;
  end if;

  update public.market_notifications
  set order_id = new.order_id
  where dedupe_key = 'offer_accepted:' || new.offer_id::text
    and recipient_id = new.buyer_id
    and order_id is null;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.list_tcg_catalog_sets_v1(p_game_key text, p_query text, p_set_id uuid, p_limit integer, p_cursor jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare a jsonb;s uuid;query text;pattern text;qhash text;items jsonb:='[]';cur jsonb;last_name text;last_id uuid;t record;n integer:=0;
begin
 a:=public.get_tcg_catalog_release_v1(p_game_key);if a->>'state'<>'ready' then raise exception 'catalog_release_unavailable';end if;s:=(a->>'snapshot_id')::uuid;
 if p_limit is null or p_limit not between 1 and 100 or p_query is not null and (length(p_query)>160 or p_query ~ '[[:cntrl:]]' or p_set_id is not null) then raise exception 'catalog_input_invalid';end if;
 query:=translate(normalize(btrim(p_query),NFC),'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
 pattern:='%'||replace(replace(replace(query,E'\\',E'\\\\'),'%',E'\\%'),'_',E'\\_')||'%';
 qhash:=encode(extensions.digest(convert_to(jsonb_build_array('sets',p_game_key,query,p_set_id)::text,'UTF8'),'sha256'),'hex');
 if p_cursor is not null then
  if jsonb_typeof(p_cursor)<>'object' or octet_length(p_cursor::text)>2048 or not p_cursor ?& array['snapshot_id','last_name','last_id','query_sha256'] or (select count(*) from jsonb_object_keys(p_cursor))<>4
  or jsonb_typeof(p_cursor->'last_name')<>'string' or length(p_cursor->>'last_name')>500 or p_cursor->>'query_sha256' is distinct from qhash or (p_cursor->>'last_id')::uuid is null then raise exception 'catalog_cursor_invalid';end if;
  if (p_cursor->>'snapshot_id')::uuid is distinct from s then raise exception 'catalog_cursor_stale';end if;last_name:=p_cursor->>'last_name';last_id:=(p_cursor->>'last_id')::uuid;
 end if;
 for t in select cs.id,cs.name,p.id ref,e.raw_record raw,lower(normalize(cs.name,NFC) collate "C") sort_name
 from dv_collect_private.tcg_catalog_snapshot_members m join dv_collect_private.tcg_provider_refs p on p.id=m.provider_ref_id and p.entity_kind='set'
 join dv_collect_private.tcg_sets cs on cs.id=p.set_id join dv_collect_private.tcg_provider_evidence e on e.id=m.evidence_id
 where m.snapshot_id=s and cs.game_key=p_game_key and (p_set_id is null or cs.id=p_set_id)
 and (query is null or translate(normalize(cs.name,NFC),'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz') like pattern escape E'\\' or e.raw_record->>'code' like pattern escape E'\\')
 and (last_id is null or (lower(normalize(cs.name,NFC) collate "C"),cs.id)>(last_name collate "C",last_id))
 order by lower(normalize(cs.name,NFC) collate "C"),cs.id limit p_limit+1 loop
  n:=n+1;if n>p_limit then cur:=jsonb_build_object('snapshot_id',s,'last_name',last_name,'last_id',last_id,'query_sha256',qhash);exit;end if;
  items:=items||jsonb_build_array(jsonb_build_object('set_id',t.id,'code',t.raw->>'code','name',t.name,'set_type',t.raw->>'set_type','parent_set_code',t.raw->>'parent_set_code','released_at',t.raw->>'released_at','provider_ref_id',t.ref));last_name:=t.sort_name;last_id:=t.id;
 end loop;
 return jsonb_build_object('snapshot_id',s,'items',items,'next_cursor',cur);
end$function$

CREATE OR REPLACE FUNCTION public.list_tcg_catalog_variants_v1(p_game_key text, p_card_id uuid, p_language text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare a jsonb;s uuid;items jsonb;
begin
 a:=public.get_tcg_catalog_release_v1(p_game_key);
 if a->>'state'<>'ready' then raise exception 'catalog_release_unavailable';end if;
 s:=(a->>'snapshot_id')::uuid;
 if p_card_id is null or not coalesce(p_language in ('EN','DE','FR','IT','ES','JP','KR','CN'),false) then raise exception 'catalog_input_invalid';end if;
 select coalesce(jsonb_agg(jsonb_build_object('variant_id',v.id,'provider_ref_id',p.id,'finish',v.finish,'artwork',v.artwork,'treatment',v.treatment,'edition',v.edition) order by v.finish collate "C"),'[]'::jsonb) into items
 from dv_collect_private.tcg_card_variants v join dv_collect_private.tcg_provider_refs p on p.variant_id=v.id
 join dv_collect_private.tcg_catalog_snapshot_members m on m.provider_ref_id=p.id and m.snapshot_id=s and m.derivation_id is not null
 join dv_collect_private.tcg_catalog_derivations d on (d.id,d.provider_ref_id,d.evidence_id)=(m.derivation_id,m.provider_ref_id,m.evidence_id)
 where (v.card_id,v.game_key,v.language_code)=(p_card_id,p_game_key,p_language) and (p.provider_key,p.provider_version,p.namespace)=('scryfall','1','api/cards/finishes')
 and exists(select 1 from dv_collect_private.tcg_catalog_snapshot_members cm join dv_collect_private.tcg_provider_refs cp on cp.id=cm.provider_ref_id join dv_collect_private.tcg_cards c on c.id=cp.card_id
  where cm.snapshot_id=s and cp.entity_kind='card' and c.id=p_card_id and c.language_code=p_language and cp.game_key=p_game_key);
 if jsonb_array_length(items)>3 then raise exception 'catalog_variant_count_invalid';end if;
 return jsonb_build_object('snapshot_id',s,'card_id',p_card_id,'variants',items);
end$function$

CREATE OR REPLACE FUNCTION public.mark_market_deal_shipped(p_deal_id uuid, p_carrier text DEFAULT NULL::text, p_tracking_code text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.market_deals;
begin
  select * into d from public.market_deals where id=p_deal_id for update;
  if d.id is null or auth.uid()<>d.seller_id then raise exception 'Nur der Verkäufer kann den Versand bestätigen'; end if;
  if d.order_id is not null then raise exception 'Dieser Deal ist Teil einer DUELVANTA Order. Versand bitte über ORDERS verwalten.'; end if;
  if d.status<>'in_progress' then raise exception 'Deal ist nicht in Abwicklung'; end if;
  if d.payment_status not in ('paid','not_required') then raise exception 'Versand erst nach bestätigter Zahlung'; end if;
  if d.shipping_method<>'pickup' and not exists(select 1 from public.market_deal_shipping_addresses a where a.deal_id=d.id) then raise exception 'Lieferadresse fehlt'; end if;
  if d.fulfillment_status='received' then return; end if;
  update public.market_deals set fulfillment_status='shipped',carrier=case when d.shipping_method='pickup' then 'Abholung' else nullif(left(trim(coalesce(p_carrier,'')),80),'') end,tracking_code=case when d.shipping_method='pickup' then null else nullif(left(trim(coalesce(p_tracking_code,'')),160),'') end,shipped_at=coalesce(shipped_at,now()),updated_at=now() where id=d.id;
end $function$

CREATE OR REPLACE FUNCTION public.mark_market_order_shipped(p_order_id uuid, p_carrier text DEFAULT NULL::text, p_tracking_code text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.market_orders;v_track boolean;v_carrier text;v_code text;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if o.id is null or auth.uid()<>o.seller_id then raise exception 'Nur der Verkäufer kann den Versand bestätigen';end if;
  if o.fulfillment_group='pickup' then raise exception 'pickup_requires_handover_code';end if;
  if o.status not in ('open','in_progress') then raise exception 'Order kann nicht versendet werden';end if;
  if exists(select 1 from public.market_order_cases c where c.order_id=o.id and c.case_type='cancellation' and c.status in ('open','accepted_refund_pending')) then raise exception 'Stornoanfrage ist noch offen';end if;
  if o.shipping_quote_status='review_required' then raise exception 'Combined Shipping muss zuerst bestätigt werden';end if;
  if o.payment_status not in ('not_required','paid') or (o.payment_provider<>'manual_beta' and o.payment_status<>'paid') then raise exception 'Versand erst nach vollständiger Zahlung';end if;
  if not exists(select 1 from public.market_order_shipping_addresses a where a.order_id=o.id and a.country_code='DE') then raise exception 'Deutsche Lieferadresse fehlt';end if;
  v_track:=o.subtotal>25 or o.risk_tracking_required;v_carrier:=nullif(left(trim(coalesce(p_carrier,'')),80),'');v_code:=nullif(left(trim(coalesce(p_tracking_code,'')),160),'');
  if v_track and (o.shipping_method not in ('tracked_letter','parcel') or v_carrier is null or v_code is null) then raise exception 'tracking_required_for_order';end if;
  update public.market_orders set status='shipped',carrier=v_carrier,tracking_code=v_code,shipped_at=coalesce(shipped_at,now()),updated_at=now() where id=o.id;
  update public.market_deals d set status=case when d.status='accepted' then 'in_progress' else d.status end,fulfillment_status='shipped',carrier=v_carrier,tracking_code=v_code,shipped_at=coalesce(d.shipped_at,now()),updated_at=now() where d.order_id=o.id and d.status not in ('cancelled','completed','disputed');
end $function$

CREATE OR REPLACE FUNCTION public.mark_market_swap_shipped_v1(p_thread_id uuid, p_carrier text DEFAULT NULL::text, p_tracking_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_thread dv_market_private.market_swap_threads%rowtype;
  v_fulfillment dv_market_private.market_swap_fulfillments%rowtype;
  v_carrier text:=nullif(left(trim(coalesce(p_carrier,'')),80),'');
  v_code text:=nullif(left(trim(coalesce(p_tracking_code,'')),160),'');
  v_now timestamptz:=now();
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) or v_thread.status<>'bound' then raise exception 'swap_not_shippable';end if;
  select * into v_fulfillment
  from dv_market_private.market_swap_fulfillments
  where thread_id=v_thread.id and sender_id=v_uid for update;
  if not found then raise exception 'swap_fulfillment_not_found';end if;
  if v_fulfillment.shipped_at is not null then
    return jsonb_build_object('shipped_at',v_fulfillment.shipped_at,'replayed',true);
  end if;
  if (v_carrier is null)<>(v_code is null) then raise exception 'swap_tracking_pair_required';end if;
  if v_fulfillment.tracking_required and (v_carrier is null or v_code is null) then raise exception 'tracking_required_for_swap';end if;
  update dv_market_private.market_swap_fulfillments
  set carrier=v_carrier,tracking_code=v_code,shipped_at=v_now,updated_at=v_now
  where thread_id=v_thread.id and sender_id=v_uid;
  return jsonb_build_object('shipped_at',v_now,'shipping_due_at',v_fulfillment.shipping_due_at,
    'tracking_required',v_fulfillment.tracking_required);
end
$function$

CREATE OR REPLACE FUNCTION public.moderate_battle_report(p_report_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 select array[r.reported_user_id] into d3_targets from public.battle_reports r where r.id=p_report_id;
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((false),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();
 perform 1 from public.battle_reports r where r.id=p_report_id and array[r.reported_user_id] is not distinct from d3_targets for update; if not found then raise exception 'd3_case_changed_or_missing' using errcode='42501'; end if;
  declare v_uid uuid:=auth.uid(); v_r public.battle_reports%rowtype; v_b1 uuid; begin perform public.require_duelvanta_privileged_session(); if not public.has_staff_permission('reports_review',v_uid) then raise exception 'reports_review permission required'; end if; if p_action not in ('review','warn','restrict','resolve','dismiss') then raise exception 'Invalid moderation action'; end if; select * into v_r from public.battle_reports where id=p_report_id for update; if not found then raise exception 'Report not found'; end if; if public.is_duelvanta_owner(v_r.reported_user_id) then raise exception 'Owner cannot be targeted by moderation actions'; end if; if p_action='restrict' and not public.has_staff_permission('users_restrict',v_uid) then raise exception 'users_restrict permission required'; end if; update public.battle_reports set status=case when p_action in ('review','warn','restrict') then 'reviewing' when p_action='resolve' then 'resolved' else 'dismissed' end,resolved_at=case when p_action in ('resolve','dismiss') then now() else null end where id=p_report_id; if p_action='restrict' then v_b1:=dv_market_private.b1_restrict(p_report_id,v_r.reported_user_id,p_note); end if; insert into public.admin_audit_log(actor_id,target_user_id,action,details) values(v_uid,v_r.reported_user_id,'battle_report_'||p_action,jsonb_build_object('report_id',p_report_id,'match_id',v_r.match_id,'note',left(p_note,1000),'sanction_id',v_b1)); return p_action; end;
end
$function$

CREATE OR REPLACE FUNCTION public.normalize_market_listing_product_kind()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.product_kind='sealed' then
    new.collection_item_id:=null;
    new.condition:='sealed';
  elsif new.grading_company is not null or new.grade is not null then
    new.product_kind:='graded';
  else
    new.product_kind:='single';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.open_market_deal_dispute(p_deal_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.market_deals; reason_clean text;
begin
 if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
 reason_clean:=nullif(left(trim(coalesce(p_reason,'')),1000),''); if reason_clean is null then raise exception 'Bitte Grund angeben'; end if;
 select * into d from public.market_deals where id=p_deal_id for update;
 if d.id is null or auth.uid() not in (d.seller_id,d.buyer_id) then raise exception 'Nicht erlaubt'; end if;
 if d.order_id is not null then raise exception 'Dieser Kauf wird über ORDERS verwaltet'; end if;
 if d.status not in ('accepted','in_progress') then raise exception 'Dieser Deal kann nicht gemeldet werden'; end if;
 update public.market_deals set status='disputed',disputed_at=now(),disputed_by=auth.uid(),dispute_reason=reason_clean,updated_at=now() where id=d.id;
end $function$

CREATE OR REPLACE FUNCTION public.open_market_order_problem_v2(p_order_id uuid, p_category text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.market_orders;v_reason text;v_cat text;v_case uuid;v_other uuid;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet';end if;
  v_reason:=nullif(left(trim(coalesce(p_reason,'')),1200),'');v_cat:=lower(trim(coalesce(p_category,'other')));
  if v_reason is null or char_length(v_reason)<3 then raise exception 'Bitte Problem beschreiben';end if;
  if v_cat not in ('shipping','not_received','damaged','not_as_described','payment','other') then raise exception 'Ungültige Problemkategorie';end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if o.id is null or auth.uid() not in (o.seller_id,o.buyer_id) then raise exception 'Nicht erlaubt';end if;
  if o.shipped_at is null or o.status not in ('shipped','received') then raise exception 'Vor Versand bitte eine Stornoanfrage verwenden';end if;
  if v_cat='not_received' and auth.uid()<>o.buyer_id then raise exception 'Nur der Käufer kann Nicht erhalten melden';end if;
  if v_cat='not_received' and nullif(trim(coalesce(o.tracking_code,'')),'') is null and now()<o.shipped_at+interval '14 days' then raise exception 'untracked_not_received_available_after_14_days';end if;
  if exists(select 1 from public.market_order_cases where order_id=o.id and case_type='problem' and status='open') then raise exception 'Für diese Order ist bereits ein Problem offen';end if;
  v_other:=case when auth.uid()=o.seller_id then o.buyer_id else o.seller_id end;
  insert into public.market_order_cases(order_id,case_type,status,category,reason,opened_by,refund_state,refund_amount) values(o.id,'problem','open',v_cat,v_reason,auth.uid(),case when o.payment_provider<>'manual_beta' and o.paid_amount>0 then 'provider_required' else 'not_required' end,case when o.payment_provider<>'manual_beta' and o.paid_amount>0 then o.total_amount else null end) returning id into v_case;
  update public.market_orders set status='disputed',disputed_at=coalesce(disputed_at,now()),disputed_by=auth.uid(),dispute_reason=v_reason,refund_status=case when payment_provider<>'manual_beta' and paid_amount>0 then 'provider_required' else refund_status end,refund_amount=case when payment_provider<>'manual_beta' and paid_amount>0 then total_amount else refund_amount end,updated_at=now() where id=o.id;
  update public.market_deals set status='disputed',disputed_at=coalesce(disputed_at,now()),disputed_by=auth.uid(),dispute_reason=v_reason,payout_status=case when payment_provider='stripe_connect' then 'blocked' else payout_status end,updated_at=now() where order_id=o.id and status not in ('cancelled','completed');
  insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key) values(v_other,'problem_opened','PROBLEM GEMELDET',o.order_number||' · '||left(v_reason,220),o.id,'problem_opened:'||v_case::text) on conflict(dedupe_key) do nothing;
  return v_case;
end $function$

CREATE OR REPLACE FUNCTION public.open_market_swap_problem_v1(p_thread_id uuid, p_fulfillment_sender_id uuid, p_category text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_thread dv_market_private.market_swap_threads%rowtype;
  v_fulfillment dv_market_private.market_swap_fulfillments%rowtype;
  v_category text:=lower(trim(coalesce(p_category,'')));
  v_reason text:=nullif(left(trim(coalesce(p_reason,'')),1200),'');
  v_case_id uuid;
  v_now timestamptz:=now();
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  if v_category not in ('shipping','not_received','damaged','not_as_described','other') then raise exception 'swap_problem_category_invalid'; end if;
  if v_reason is null or char_length(v_reason)<3 then raise exception 'swap_problem_reason_required';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id for update;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) then raise exception 'swap_not_participant';end if;
  if v_thread.status not in ('bound','disputed') then raise exception 'swap_problem_not_available';end if;
  if exists(select 1 from dv_market_private.market_swap_cases c where c.thread_id=v_thread.id and c.status='open') then raise exception 'swap_problem_already_open';end if;
  select * into v_fulfillment from dv_market_private.market_swap_fulfillments where thread_id=v_thread.id and sender_id=p_fulfillment_sender_id for update;
  if not found or v_fulfillment.shipped_at is null then raise exception 'swap_shipment_not_problem_eligible';end if;
  if v_category='not_received' then
    if v_uid<>v_fulfillment.receiver_id then raise exception 'swap_not_received_receiver_only';end if;
    if v_fulfillment.tracking_code is null and v_now<v_fulfillment.shipped_at+interval '14 days' then raise exception 'c2c_untracked_not_received_wait_14_days';end if;
  end if;
  insert into dv_market_private.market_swap_cases(
    thread_id,fulfillment_sender_id,opened_by,category,reason,status,response_due_at,evidence_due_at,created_at,updated_at
  ) values(v_thread.id,v_fulfillment.sender_id,v_uid,v_category,v_reason,'open',v_now+interval '7 days',v_now+interval '7 days',v_now,v_now)
  returning id into v_case_id;
  update dv_market_private.market_swap_threads set status='disputed',updated_at=v_now where id=v_thread.id;
  return v_case_id;
end
$function$

CREATE OR REPLACE FUNCTION public.prepare_account_deletion_data(p_request_id uuid, p_lock_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_request dv_market_private.account_deletion_requests%rowtype;v_has_holds boolean;v_until timestamptz;
begin
 perform dv_market_private.c_assert_committed_prepare(p_request_id,p_lock_token);
  select * into v_request from dv_market_private.account_deletion_requests
  where id=p_request_id and status='processing' and lock_token=p_lock_token for update;
  if not found then raise exception 'deletion_request_lock_invalid'; end if;
  if jsonb_array_length(dv_market_private.account_deletion_blockers(v_request.user_id))>0 then raise exception 'deletion_blockers_changed'; end if;

  if exists(select 1 from dv_market_private.market_contract_snapshots where seller_id=v_request.user_id or buyer_id=v_request.user_id) then
    insert into dv_market_private.account_deletion_holds(request_id,user_id,category,reason,manual_review_required)
    values(v_request.id,v_request.user_id,'contract_evidence','Abgeschlossene Vertragsnachweise bleiben zugriffsbeschränkt.',true)
    on conflict(request_id,category) do nothing;
  end if;
  select make_timestamptz(max(reporting_year)+11,1,1,0,0,0,'UTC') into v_until
  from dv_market_private.market_tax_events where seller_id=v_request.user_id;
  if v_until is not null then
    insert into dv_market_private.account_deletion_holds(request_id,user_id,category,reason,retain_until)
    values(v_request.id,v_request.user_id,'psttg_record','PStTG-Aufzeichnungen: zehn Jahre nach Ende des Aufzeichnungsjahres.',v_until)
    on conflict(request_id,category) do nothing;
  end if;
  if exists(select 1 from dv_market_private.listing_notices where reporter_user_id=v_request.user_id)
     or exists(select 1 from dv_market_private.listing_notice_appeals where appellant_user_id=v_request.user_id) then
    insert into dv_market_private.account_deletion_holds(request_id,user_id,category,reason,manual_review_required)
    values(v_request.id,v_request.user_id,'notice_procedure','Abgeschlossene Meldungs- und Einspruchsnachweise bleiben zugriffsbeschränkt.',true)
    on conflict(request_id,category) do nothing;
  end if;
  if dv_market_private.user_has_pickup_messages(v_request.user_id) then
    insert into dv_market_private.account_deletion_holds(request_id,user_id,category,reason,manual_review_required)
    values(
      v_request.id,v_request.user_id,'pickup_messages',
      'Pickup-Nachrichten bleiben bis zur extern bestätigten Aufbewahrungsentscheidung zugriffsbeschränkt; keine automatische Frist.',true
    )
    on conflict(request_id,category) do nothing;
  end if;
  select exists(select 1 from dv_market_private.account_deletion_holds where request_id=v_request.id and released_at is null) into v_has_holds;

  delete from public.market_notifications where recipient_id=v_request.user_id;
  delete from public.market_default_shipping_addresses where user_id=v_request.user_id;
  delete from public.market_listing_images where seller_id=v_request.user_id;
  update public.market_listings set collection_item_id=null,image_path=null,seller_note=null,
    seller_display_name='Gelöschtes Mitglied',status=case when status in ('active','reserved') then 'paused' else status end,
    updated_at=now() where seller_id=v_request.user_id;
  delete from dv_collect_private.listing_catalog_links x using public.market_listings l
    where x.listing_id=l.id and l.seller_id=v_request.user_id;
  delete from public.collection_items where user_id=v_request.user_id;
  delete from public.collection_folders where user_id=v_request.user_id;
  update public.market_seller_accounts set onboarding_status='suspended',suspended_at=coalesce(suspended_at,now()),
    trader_display_name=null,updated_at=now() where seller_id=v_request.user_id;

  -- C already locked this profile/request and required a separately committed
  -- entry. Existing U037 blockers and hold decisions above remain unchanged.
  insert into dv_market_private.l1_profile_reductions
   (transaction_id,backend_pid,target_id,request_id,attempt_id,old_profile_hash,anonymous_email)
  select pg_current_xact_id(),pg_backend_pid(),p.id,v_request.id,
   dv_market_private.c_lock_attempt(v_request.id,p_lock_token),pg_catalog.sha256(pg_catalog.convert_to(to_jsonb(p)::text,'UTF8')),
   'deleted-'||gen_random_uuid()::text||'@invalid.local'
  from public.profiles p
  join dv_market_private.c_request_origins o on o.request_id=v_request.id and o.user_id=p.id
  join dv_market_private.c_marker_owner m on m.request_id=v_request.id and m.user_id=p.id
  where p.id=v_request.user_id and p.data_processing_restricted_at is not null
   and p.account_closure_requested_at is not null;
  if not found then raise exception 'l1_c_binding_invalid' using errcode='42501';end if;
  update public.profiles set email=(select anonymous_email from dv_market_private.l1_profile_reductions
     where transaction_id=pg_current_xact_id() and backend_pid=pg_backend_pid() and target_id=v_request.user_id),
    display_name='Gelöschtes Mitglied',username=null,avatar_path=null,collection_visibility='private',
    updated_at=now() where id=v_request.user_id;
  delete from dv_market_private.l1_profile_reductions
   where transaction_id=pg_current_xact_id() and backend_pid=pg_backend_pid() and target_id=v_request.user_id;

  if not v_has_holds then
    delete from dv_market_private.market_pickup_messages where sender_id=v_request.user_id;
    delete from dv_market_private.seller_tax_identifiers where seller_id=v_request.user_id;
    delete from dv_market_private.seller_legal_profiles where seller_id=v_request.user_id;
  end if;
  update dv_market_private.account_deletion_requests set auth_action=case when v_has_holds then 'disable_and_retain' else 'delete' end
  where id=v_request.id;
  insert into dv_market_private.account_data_rights_audit(user_id,request_id,event_type,event_data)
  values(v_request.user_id,v_request.id,'data_erasure_prepared',jsonb_build_object(
    'retention_holds',v_has_holds,
    'pickup_messages_retained',exists(
      select 1 from dv_market_private.account_deletion_holds h
      where h.request_id=v_request.id and h.category='pickup_messages' and h.released_at is null
    )
  ));
  return jsonb_build_object(
    'request_id',v_request.id,'user_id',v_request.user_id,
    'auth_action',case when v_has_holds then 'disable_and_retain' else 'delete' end,
    'has_retention_holds',v_has_holds
  );
end
$function$

CREATE OR REPLACE FUNCTION public.prepare_fixed_price_market_offer_v1(p_listing_id uuid, p_quantity integer, p_request_id uuid, p_expected_updated_at timestamp with time zone, p_checkout_hash text, p_live_mode boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_uid uuid:=auth.uid();v_existing public.market_offers%rowtype;v_listing public.market_listings%rowtype;
  v_review jsonb;v_config dv_market_private.market_payment_configuration%rowtype;v_account dv_market_private.market_stripe_accounts%rowtype;
  v_buyer_type text;v_qty integer;v_left integer;v_total_cents integer;v_fee_cents integer;v_attempt uuid:=gen_random_uuid();
  v_offer uuid;v_deal public.market_deals;v_attempt_row dv_market_private.market_payment_attempts%rowtype;v_hash text;
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if p_request_id is null or p_expected_updated_at is null or nullif(lower(trim(coalesce(p_checkout_hash,''))),'') is null then
    raise exception 'fixed_checkout_request_invalid';
  end if;
  v_buyer_type:=dv_market_private.require_market_buyer_type(v_uid);
  perform public.expire_market_offer_reservations_v1();
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text||':'||p_request_id::text,45));

  select * into v_existing from public.market_offers
  where buyer_id=v_uid and offer_type='fixed_price' and checkout_request_id=p_request_id;
  if found then
    if v_existing.listing_id<>p_listing_id or v_existing.requested_quantity<>p_quantity
       or lower(trim(p_checkout_hash)) is distinct from v_existing.checkout_hash_snapshot
       or (v_existing.contract_review_snapshot->>'listing_updated_at')::timestamptz is distinct from p_expected_updated_at then
      raise exception 'fixed_checkout_request_reused';
    end if;
    if v_existing.payment_live_mode_snapshot is distinct from p_live_mode
       or v_existing.stripe_account_id_snapshot is null
       or v_existing.amount_due_cents_snapshot is null or v_existing.amount_due_cents_snapshot<=0
       or v_existing.platform_fee_cents_snapshot is null
       or v_existing.platform_fee_cents_snapshot<0
       or v_existing.platform_fee_cents_snapshot>v_existing.amount_due_cents_snapshot
       or v_existing.contract_review_snapshot is null
       or v_existing.contract_review_snapshot->>'snapshot_version'<>'checkout-contract-v2'
       or v_existing.checkout_hash_snapshot is null then
      raise exception 'fixed_checkout_snapshot_invalid';
    end if;
    v_hash:=encode(digest(convert_to(v_existing.contract_review_snapshot::text,'UTF8'),'sha256'),'hex');
    if v_hash<>v_existing.checkout_hash_snapshot
       or (v_existing.contract_review_snapshot->>'listing_id')::uuid<>v_existing.listing_id
       or (v_existing.contract_review_snapshot->>'seller_id')::uuid<>v_existing.seller_id
       or (v_existing.contract_review_snapshot->>'quantity')::integer<>v_existing.requested_quantity
       or v_existing.contract_review_snapshot->>'buyer_type'<>'consumer'
       or v_existing.contract_review_snapshot->>'contract_classification' not in ('c2c','b2c')
       or jsonb_typeof(v_existing.contract_review_snapshot->'seller_party')<>'object'
       or jsonb_typeof(v_existing.contract_review_snapshot->'product')<>'object'
       or jsonb_typeof(v_existing.contract_review_snapshot->'fulfillment_snapshot')<>'object'
       or nullif(v_existing.contract_review_snapshot->'fulfillment_snapshot'->>'product_kind','') is null
       or v_existing.contract_review_snapshot->>'currency'<>'EUR'
       or v_existing.contract_review_snapshot->>'payment_provider'<>'stripe_connect'
       or round((v_existing.contract_review_snapshot->>'goods_total')::numeric,2)<>round(v_existing.amount,2)
       or round((v_existing.contract_review_snapshot->>'total_price')::numeric*100)::integer<>v_existing.amount_due_cents_snapshot then
      raise exception 'fixed_checkout_snapshot_invalid';
    end if;

    if v_existing.status='accepted' then
      select * into v_deal from public.market_deals where offer_id=v_existing.id;
      select * into v_attempt_row from dv_market_private.market_payment_attempts where id=v_existing.payment_attempt_id;
      if v_deal.id is null or v_attempt_row.id is null
         or v_attempt_row.stripe_account_id<>v_existing.stripe_account_id_snapshot
         or v_attempt_row.amount_due_cents<>v_existing.amount_due_cents_snapshot
         or v_attempt_row.platform_fee_cents<>v_existing.platform_fee_cents_snapshot
         or v_attempt_row.currency<>'EUR' then raise exception 'fixed_checkout_acceptance_incomplete'; end if;
      return jsonb_build_object(
        'replayed',true,'accepted',true,'offer_id',v_existing.id,'payment_attempt_id',v_existing.payment_attempt_id,
        'stripe_checkout_session_id',v_existing.stripe_checkout_session_id,'stripe_account_id',v_existing.stripe_account_id_snapshot,
        'amount_due_cents',v_existing.amount_due_cents_snapshot,'platform_fee_cents',v_existing.platform_fee_cents_snapshot,
        'currency','EUR','order_id',v_deal.order_id,'live_mode',v_existing.payment_live_mode_snapshot
      );
    end if;

    if v_existing.status='pending' and v_existing.reservation_expires_at>now() then
      select * into v_config from dv_market_private.market_payment_configuration where singleton;
      if not found then raise exception 'stripe_payment_configuration_missing'; end if;
      if p_live_mode then
        if not v_config.live_mode then raise exception 'stripe_live_database_disabled'; end if;
      else
        if v_config.live_mode or not v_config.sandbox_enabled then raise exception 'stripe_sandbox_disabled'; end if;
      end if;
      select * into v_account from dv_market_private.market_stripe_accounts where seller_id=v_existing.seller_id;
      if not found or v_account.stripe_account_id<>v_existing.stripe_account_id_snapshot
         or v_account.live_mode is distinct from p_live_mode
         or v_account.onboarding_status<>'ready' or not v_account.charges_enabled then
        raise exception 'stripe_seller_not_ready';
      end if;
      return jsonb_build_object(
        'replayed',true,'accepted',false,'offer_id',v_existing.id,'payment_attempt_id',v_existing.payment_attempt_id,
        'stripe_account_id',v_existing.stripe_account_id_snapshot,'amount_due_cents',v_existing.amount_due_cents_snapshot,
        'platform_fee_cents',v_existing.platform_fee_cents_snapshot,'currency','EUR','live_mode',v_existing.payment_live_mode_snapshot
      );
    end if;
    raise exception 'fixed_checkout_request_expired';
  end if;

  select * into v_config from dv_market_private.market_payment_configuration where singleton for update;
  if not found then raise exception 'stripe_payment_configuration_missing'; end if;
  if p_live_mode then
    if not v_config.live_mode then raise exception 'stripe_live_database_disabled'; end if;
  else
    if v_config.live_mode or not v_config.sandbox_enabled then raise exception 'stripe_sandbox_disabled'; end if;
  end if;

  v_review:=public.review_market_checkout(p_listing_id,p_quantity);
  if lower(trim(p_checkout_hash))<>(v_review->>'checkout_hash')
     or (v_review->>'listing_updated_at')::timestamptz is distinct from p_expected_updated_at then
    raise exception 'checkout_review_changed';
  end if;
  v_buyer_type:=v_review->>'buyer_type';

  select * into v_listing from public.market_listings where id=p_listing_id for update;
  if not found or v_listing.status<>'active' or v_listing.updated_at is distinct from p_expected_updated_at then
    raise exception 'listing_not_available';
  end if;
  v_qty:=case when v_listing.product_kind='sealed' then p_quantity else 1 end;
  if v_qty<1 or v_qty>v_listing.quantity_available then raise exception 'checkout_quantity_unavailable'; end if;

  select * into v_account from dv_market_private.market_stripe_accounts where seller_id=v_listing.seller_id;
  if not found or v_account.live_mode is distinct from p_live_mode
     or v_account.onboarding_status<>'ready' or not v_account.charges_enabled then
    raise exception 'stripe_seller_not_ready';
  end if;

  v_total_cents:=round((v_review->>'total_price')::numeric*100)::integer;
  v_fee_cents:=least(v_total_cents,round(v_total_cents*v_config.platform_fee_bps/10000.0)::integer+v_config.platform_fee_fixed_cents);
  if v_total_cents<=0 or v_fee_cents<0 or v_fee_cents>v_total_cents then raise exception 'fixed_checkout_amount_invalid'; end if;

  v_left:=v_listing.quantity_available-v_qty;
  update public.market_listings
  set quantity_available=v_left,status=case when v_left=0 then 'reserved' else 'active' end,updated_at=now()
  where id=v_listing.id;

  insert into public.market_offers(
    listing_id,buyer_id,seller_id,offer_type,amount,currency,status,requested_quantity,
    unit_price_snapshot,listed_unit_price_snapshot,listed_total_snapshot,listing_snapshot,contract_review_snapshot,
    reserved_quantity,reservation_expires_at,buyer_type_snapshot,checkout_request_id,checkout_hash_snapshot,payment_attempt_id,
    stripe_account_id_snapshot,payment_live_mode_snapshot,amount_due_cents_snapshot,platform_fee_cents_snapshot
  ) values(
    v_listing.id,v_uid,v_listing.seller_id,'fixed_price',(v_review->>'goods_total')::numeric,'EUR','pending',v_qty,
    (v_review->>'unit_price')::numeric,(v_review->>'unit_price')::numeric,(v_review->>'goods_total')::numeric,
    jsonb_build_object(
      'card_name',v_review->'product'->>'title','product_kind',v_listing.product_kind,'sealed_category',v_listing.sealed_category,
      'language',v_listing.language,'set_name',v_listing.set_name,'base_unit_price',(v_review->>'unit_price')::numeric,
      'shipping_method',v_review->>'shipping_method','shipping_cost',(v_review->>'shipping_cost')::numeric,
      'total_price',(v_review->>'total_price')::numeric
    ),
    v_review-'checkout_hash',v_qty,now()+interval '15 minutes',v_buyer_type,p_request_id,lower(p_checkout_hash),v_attempt,
    v_account.stripe_account_id,p_live_mode,v_total_cents,v_fee_cents
  ) returning id into v_offer;

  return jsonb_build_object(
    'replayed',false,'accepted',false,'offer_id',v_offer,'payment_attempt_id',v_attempt,
    'stripe_account_id',v_account.stripe_account_id,'amount_due_cents',v_total_cents,'platform_fee_cents',v_fee_cents,
    'currency','EUR','live_mode',p_live_mode
  );
end
$function$

CREATE OR REPLACE FUNCTION public.prepare_market_stripe_full_refund(p_order_id uuid, p_request_key uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare a dv_market_private.market_payment_attempts%rowtype;r dv_market_private.market_refund_requests%rowtype;
begin
  if p_request_key is null or char_length(trim(coalesce(p_reason,''))) not between 3 and 500 then raise exception 'stripe_refund_input_invalid'; end if;
  select * into r from dv_market_private.market_refund_requests where request_key=p_request_key;
  if found then return jsonb_build_object('request_id',r.id,'attempt_id',r.attempt_id,'stripe_account_id',
    (select stripe_account_id from dv_market_private.market_payment_attempts where id=r.attempt_id),'payment_intent_id',
    (select stripe_payment_intent_id from dv_market_private.market_payment_attempts where id=r.attempt_id),'amount_cents',r.amount_cents,'replayed',true); end if;
  select * into a from dv_market_private.market_payment_attempts where order_id=p_order_id and state='paid' for update;
  if not found then raise exception 'stripe_refund_not_available'; end if;
  if not exists(select 1 from public.market_orders where id=p_order_id and refund_status='provider_required') then raise exception 'stripe_refund_not_authorized'; end if;
  insert into dv_market_private.market_refund_requests(order_id,attempt_id,request_key,amount_cents,reason)
  values(p_order_id,a.id,p_request_key,a.paid_cents,left(trim(p_reason),500)) returning * into r;
  update dv_market_private.market_payment_attempts set state='refund_pending',updated_at=now() where id=a.id;
  return jsonb_build_object('request_id',r.id,'attempt_id',a.id,'stripe_account_id',a.stripe_account_id,
    'payment_intent_id',a.stripe_payment_intent_id,'amount_cents',r.amount_cents,'currency','EUR','live_mode',false);
end
$function$

CREATE OR REPLACE FUNCTION public.prepare_market_stripe_onboarding(p_seller_id uuid, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare c dv_market_private.market_payment_configuration%rowtype;r dv_market_private.market_stripe_onboarding_requests%rowtype;
  a dv_market_private.market_stripe_accounts%rowtype;s public.market_seller_accounts%rowtype;
begin
  if p_seller_id is null or p_request_key is null then raise exception 'stripe_onboarding_input_invalid'; end if;
  select * into c from dv_market_private.market_payment_configuration where singleton;
  if not found or not c.sandbox_enabled or c.live_mode then raise exception 'stripe_sandbox_disabled'; end if;
  select * into s from public.market_seller_accounts where seller_id=p_seller_id for update;
  if not found or s.onboarding_status<>'active' or s.seller_type not in ('private','trader') then raise exception 'seller_onboarding_not_approved'; end if;
  select * into r from dv_market_private.market_stripe_onboarding_requests where seller_id=p_seller_id and request_key=p_request_key;
  if r.id is null then
    select * into r from dv_market_private.market_stripe_onboarding_requests
      where seller_id=p_seller_id and state in ('prepared','account_created','link_created') for update;
  end if;
  select * into a from dv_market_private.market_stripe_accounts where seller_id=p_seller_id;
  if found and a.live_mode then raise exception 'stripe_live_account_forbidden'; end if;
  if r.id is not null then return jsonb_build_object('onboarding_request_id',r.id,'onboarding_state',r.state,
    'stripe_account_id',a.stripe_account_id,'seller_type',s.seller_type,'country_code',s.country_code,'replayed',true,'live_mode',false); end if;
  insert into dv_market_private.market_stripe_onboarding_requests(seller_id,request_key)
  values(p_seller_id,p_request_key) returning * into r;
  return jsonb_build_object('onboarding_request_id',r.id,'onboarding_state',r.state,'stripe_account_id',a.stripe_account_id,
    'seller_type',s.seller_type,'country_code',s.country_code,'replayed',false,'live_mode',false);
end
$function$

CREATE OR REPLACE FUNCTION public.prepare_market_stripe_payment(p_order_id uuid, p_buyer_id uuid, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare c dv_market_private.market_payment_configuration%rowtype;
  o public.market_orders%rowtype;a dv_market_private.market_payment_attempts%rowtype;
  s dv_market_private.market_stripe_accounts%rowtype;v_total integer;v_fee integer;v_sum integer:=0;
  r record;v_gross integer;v_alloc_fee integer;v_last uuid;
begin
  if p_order_id is null or p_buyer_id is null or p_idempotency_key is null then raise exception 'stripe_payment_input_invalid'; end if;
  select * into c from dv_market_private.market_payment_configuration where singleton for update;
  if not found or not c.sandbox_enabled or c.live_mode then raise exception 'stripe_sandbox_disabled'; end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if not found or o.buyer_id<>p_buyer_id then raise exception 'stripe_order_access_denied'; end if;
  if o.status not in ('open','in_progress') or o.shipped_at is not null then raise exception 'stripe_order_not_payable'; end if;
  if o.shipping_quote_status='review_required' then raise exception 'stripe_shipping_review_required'; end if;
  if o.payment_provider not in ('manual_beta','stripe_connect') or coalesce(o.paid_amount,0)>0 then raise exception 'stripe_order_payment_state_invalid'; end if;
  select * into a from dv_market_private.market_payment_attempts where buyer_id=p_buyer_id and idempotency_key=p_idempotency_key;
  if found then
    if a.order_id<>p_order_id then raise exception 'stripe_payment_idempotency_conflict'; end if;
    return jsonb_build_object('attempt_id',a.id,'stripe_account_id',a.stripe_account_id,
      'amount_due_cents',a.amount_due_cents,'platform_fee_cents',a.platform_fee_cents,'replayed',true);
  end if;
  select * into s from dv_market_private.market_stripe_accounts where seller_id=o.seller_id;
  if not found or s.live_mode or s.onboarding_status<>'ready' or not s.charges_enabled then raise exception 'stripe_seller_not_ready'; end if;
  v_total:=round(o.total_amount*100)::integer;
  if v_total<=0 then raise exception 'stripe_order_amount_invalid'; end if;
  v_fee:=least(v_total,round(v_total*c.platform_fee_bps/10000.0)::integer+c.platform_fee_fixed_cents);
  insert into dv_market_private.market_payment_attempts(
    order_id,buyer_id,seller_id,stripe_account_id,idempotency_key,amount_due_cents,platform_fee_cents
  ) values(p_order_id,p_buyer_id,o.seller_id,s.stripe_account_id,p_idempotency_key,v_total,v_fee) returning * into a;

  select s2.id into v_last from dv_market_private.market_contract_snapshots s2
  where s2.order_id=p_order_id order by s2.id desc limit 1;
  for r in select s2.id,round(s2.goods_total*100)::integer goods_cents
    from dv_market_private.market_contract_snapshots s2 where s2.order_id=p_order_id order by s2.id
  loop
    v_gross:=r.goods_cents;
    if r.id=v_last then v_gross:=v_total-v_sum; end if;
    if v_gross<=0 then raise exception 'stripe_payment_allocation_invalid'; end if;
    v_alloc_fee:=case when r.id=v_last then v_fee-coalesce((select sum(platform_fee_cents) from dv_market_private.market_payment_allocations where attempt_id=a.id),0)
      else floor(v_fee*v_gross::numeric/v_total)::integer end;
    insert into dv_market_private.market_payment_allocations(attempt_id,contract_snapshot_id,gross_cents,platform_fee_cents)
    values(a.id,r.id,v_gross,v_alloc_fee);
    v_sum:=v_sum+v_gross;
  end loop;
  if v_last is null or v_sum<>v_total then raise exception 'stripe_payment_allocation_invalid'; end if;
  update public.market_orders set payment_provider='stripe_connect',payment_status='pending',paid_amount=0,updated_at=now() where id=o.id;
  update public.market_deals set payment_provider='stripe_connect',payment_status='pending',updated_at=now() where order_id=o.id;
  return jsonb_build_object('attempt_id',a.id,'stripe_account_id',a.stripe_account_id,
    'amount_due_cents',v_total,'platform_fee_cents',v_fee,'currency','EUR','charge_model','direct_charge','live_mode',false);
end
$function$

CREATE OR REPLACE FUNCTION public.prepare_market_withdrawal_v1(p_contract_snapshot_id uuid, p_consumer_name text, p_confirmation_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_uid uuid:=auth.uid();s dv_market_private.market_contract_snapshots%rowtype;v_id uuid;v_expires timestamptz;
  v_name text:=trim(coalesce(p_consumer_name,''));v_email text:=lower(trim(coalesce(p_confirmation_email,'')));
begin
  if v_uid is null then raise exception 'authentication_required'; end if;
  if char_length(v_name) not between 2 and 160 then raise exception 'withdrawal_name_invalid'; end if;
  if v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'withdrawal_email_invalid'; end if;
  delete from dv_market_private.market_withdrawal_drafts where buyer_id=v_uid and expires_at<=now();
  select * into s from dv_market_private.market_contract_snapshots
  where id=p_contract_snapshot_id
    and buyer_id=v_uid
    and contract_classification='b2c'
    and withdrawal_eligible
    and seller_type='trader'
    and buyer_type='consumer'
    and nullif(trim(seller_party->>'public_email'),'') is not null;
  if not found then raise exception 'withdrawal_contract_not_eligible'; end if;
  perform pg_advisory_xact_lock(hashtextextended(s.id::text,0));
  if exists(select 1 from dv_market_private.market_withdrawals where contract_snapshot_id=s.id and buyer_id=v_uid) then
    raise exception 'withdrawal_already_submitted';
  end if;
  insert into dv_market_private.market_withdrawal_drafts(
    contract_snapshot_id,buyer_id,seller_id,consumer_name,confirmation_email
  ) values(s.id,v_uid,s.seller_id,v_name,v_email)
  on conflict (contract_snapshot_id,buyer_id) do update set
    seller_id=excluded.seller_id,
    consumer_name=excluded.consumer_name,
    confirmation_email=excluded.confirmation_email,
    created_at=now(),
    expires_at=now()+interval '15 minutes'
  returning id,expires_at into v_id,v_expires;
  return jsonb_build_object(
    'draft_id',v_id,'contract_snapshot_id',s.id,'order_id',s.order_id,'deal_id',s.deal_id,
    'consumer_name',v_name,'confirmation_email',v_email,
    'seller_name',coalesce(nullif(s.seller_party->>'business_name',''),s.seller_party->>'legal_name'),
    'product_title',s.product_snapshot->>'title','contract_formed_at',s.contract_formed_at,
    'total_price',s.total_price,'currency',s.currency,'expires_at',v_expires
  );
end
$function$

CREATE OR REPLACE FUNCTION public.process_ranked_battle_rating()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  h_before integer; g_before integer; h_after integer; g_after integer;
  h_games integer; g_games integer;
  expected_h double precision; actual_h double precision; k integer := 32; delta integer;
  result_text text;
begin
  if new.status<>'completed' or new.mode<>'ranked' or new.guest_id is null then return new; end if;
  if old.status='completed' then return new; end if;
  if exists(select 1 from public.battle_rating_events where match_id=new.id) then return new; end if;

  insert into public.battle_ratings(user_id,tcg) values(new.host_id,new.tcg) on conflict do nothing;
  insert into public.battle_ratings(user_id,tcg) values(new.guest_id,new.tcg) on conflict do nothing;

  if new.host_id::text < new.guest_id::text then
    perform 1 from public.battle_ratings where user_id=new.host_id and tcg=new.tcg for update;
    perform 1 from public.battle_ratings where user_id=new.guest_id and tcg=new.tcg for update;
  else
    perform 1 from public.battle_ratings where user_id=new.guest_id and tcg=new.tcg for update;
    perform 1 from public.battle_ratings where user_id=new.host_id and tcg=new.tcg for update;
  end if;

  select rating,games into h_before,h_games from public.battle_ratings where user_id=new.host_id and tcg=new.tcg;
  select rating,games into g_before,g_games from public.battle_ratings where user_id=new.guest_id and tcg=new.tcg;

  expected_h := 1.0 / (1.0 + power(10.0, (g_before-h_before)/400.0));
  if new.winner_id=new.host_id then actual_h:=1.0; result_text:='host';
  elsif new.winner_id=new.guest_id then actual_h:=0.0; result_text:='guest';
  else actual_h:=0.5; result_text:='draw'; end if;

  delta := round(k*(actual_h-expected_h));
  h_after := greatest(100,h_before+delta);
  g_after := greatest(100,g_before-delta);

  update public.battle_ratings set
    rating=h_after,
    games=games+1,
    wins=wins+case when result_text='host' then 1 else 0 end,
    losses=losses+case when result_text='guest' then 1 else 0 end,
    draws=draws+case when result_text='draw' then 1 else 0 end,
    updated_at=now()
  where user_id=new.host_id and tcg=new.tcg;

  update public.battle_ratings set
    rating=g_after,
    games=games+1,
    wins=wins+case when result_text='guest' then 1 else 0 end,
    losses=losses+case when result_text='host' then 1 else 0 end,
    draws=draws+case when result_text='draw' then 1 else 0 end,
    updated_at=now()
  where user_id=new.guest_id and tcg=new.tcg;

  insert into public.battle_rating_events(match_id,tcg,host_id,guest_id,host_before,host_after,guest_before,guest_after,host_delta,guest_delta,result)
  values(new.id,new.tcg,new.host_id,new.guest_id,h_before,h_after,g_before,g_after,h_after-h_before,g_after-g_before,result_text)
  on conflict (match_id) do nothing;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.propose_market_swap_revision_v1(p_thread_id uuid, p_party_a_listing_ids uuid[], p_party_b_listing_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_thread dv_market_private.market_swap_threads%rowtype;
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) then raise exception 'swap_not_participant';end if;
  if v_thread.status<>'negotiating' then raise exception 'swap_not_negotiable';end if;
  return dv_market_private.create_market_swap_revision(v_thread.id,v_uid,p_party_a_listing_ids,p_party_b_listing_ids);
end
$function$

CREATE OR REPLACE FUNCTION public.propose_market_swap_revision_v2(p_thread_id uuid, p_party_a_listing_ids uuid[], p_party_b_listing_ids uuid[], p_fulfillment_mode text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_thread dv_market_private.market_swap_threads%rowtype;v_mode text:=lower(trim(coalesce(p_fulfillment_mode,'')));
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  if v_mode not in ('shipping','pickup') then raise exception 'swap_fulfillment_mode_invalid';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id for update;
  if not found or v_uid not in (v_thread.party_a_id,v_thread.party_b_id) then raise exception 'swap_not_participant';end if;
  if v_thread.status<>'negotiating' then raise exception 'swap_not_negotiable';end if;
  update dv_market_private.market_swap_threads set fulfillment_mode=v_mode,updated_at=now() where id=v_thread.id;
  return dv_market_private.create_market_swap_revision(v_thread.id,v_uid,p_party_a_listing_ids,p_party_b_listing_ids);
end
$function$

CREATE OR REPLACE FUNCTION public.protect_duelvanta_owner_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare bound_uid uuid;
begin
  select user_id into bound_uid from dv_v16_private.operator_identity_v1 where singleton;
  if old.id=bound_uid then
    if new.id is distinct from old.id or new.role is distinct from 'owner'
       or lower(new.email) is distinct from 'info@duelvanta.de'
       or new.account_status not in ('active','beta') then
      raise exception 'DUELVANTA owner identity is protected';
    end if;
  end if;
  if new.role='owner' and new.id is distinct from bound_uid then
    raise exception 'Owner role is reserved';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.publish_my_sealed_market_listing(p_listing_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l public.market_listings; v_count int; v_min int;
begin
  select * into l from public.market_listings where id=p_listing_id for update;
  if l.id is null or l.seller_id<>auth.uid() or l.product_kind<>'sealed' then raise exception 'Nicht erlaubt'; end if;
  if l.status<>'draft' then raise exception 'Angebot ist kein Entwurf'; end if;
  select count(*) into v_count from public.market_listing_images where listing_id=l.id;
  v_min:=case when l.sealed_category='case' then 3 else 1 end;
  if v_count<v_min then raise exception 'Bitte mindestens % echte Produktfoto(s) hochladen',v_min; end if;
  update public.market_listings set status='active',published_at=now(),active_until=now()+interval '90 days',updated_at=now() where id=l.id;
end $function$

CREATE OR REPLACE FUNCTION public.recalc_market_order_after_address_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_order uuid;
begin
  if tg_op='DELETE' then v_order:=old.order_id; else v_order:=new.order_id; end if;
  if exists(select 1 from public.market_order_items where order_id=v_order) then perform public.recalculate_market_order(v_order); end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_market_order(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.market_orders;
  v_count integer:=0;
  v_units integer:=0;
  v_sub numeric:=0;
  v_sep numeric:=0;
  v_auto_cost numeric:=0;
  v_fallback_cost numeric:=0;
  v_weight integer:=0;
  v_method text:='custom';
  v_fallback_method text:='custom';
  v_review boolean:=false;
  v_custom boolean:=false;
  v_missing_weight boolean:=false;
  v_has_sealed boolean:=false;
  v_has_cards boolean:=false;
  v_missing_sealed_dims boolean:=false;
  v_max_l integer:=0;
  v_max_w integer:=0;
  v_max_h integer:=0;
  v_same_shape boolean:=false;
  v_keep_confirmed boolean:=false;
  v_combined boolean:=false;
  v_country text;
  v_profile uuid;
  v_rule uuid;
  v_candidate_method text;
  v_candidate_cost numeric;
  v_profile_name text;
  v_carrier text;
  v_note text;
begin
  select * into o from public.market_orders where id=p_order_id for update;
  if o.id is null or o.status not in ('open','in_progress') then return; end if;

  select count(*)::integer,
         coalesce(sum(i.quantity),0)::integer,
         coalesce(sum(i.item_amount),0),
         coalesce(sum(i.individual_shipping_cost),0),
         coalesce(max(i.individual_shipping_cost),0),
         coalesce(sum(coalesce(i.weight_grams,0)),0)::integer,
         coalesce(bool_or(i.shipping_method='custom'),false),
         coalesce(bool_or(i.weight_grams is null),false),
         coalesce(bool_or(d.product_kind='sealed'),false),
         coalesce(bool_or(d.product_kind in ('single','graded')),false),
         coalesce(bool_or(d.product_kind='sealed' and (d.length_mm is null or d.width_mm is null or d.height_mm is null)),false),
         coalesce(max(case when d.product_kind='sealed' then d.length_mm else 0 end),0),
         coalesce(max(case when d.product_kind='sealed' then d.width_mm else 0 end),0),
         coalesce(max(case when d.product_kind='sealed' then d.height_mm else 0 end),0)
  into v_count,v_units,v_sub,v_sep,v_auto_cost,v_weight,v_custom,v_missing_weight,
       v_has_sealed,v_has_cards,v_missing_sealed_dims,v_max_l,v_max_w,v_max_h
  from public.market_order_items i
  join public.market_deals d on d.id=i.deal_id
  where i.order_id=p_order_id and d.status<>'cancelled';

  if v_count=0 then
    update public.market_orders
    set status='cancelled',item_count=0,subtotal=0,separate_shipping_sum=0,
        shipping_cost=0,total_amount=0,shipping_savings=0,
        cancelled_at=coalesce(cancelled_at,now()),updated_at=now()
    where id=p_order_id;
    return;
  end if;

  v_fallback_cost:=coalesce(v_auto_cost,0);
  select a.country_code into v_country
  from public.market_order_shipping_addresses a where a.order_id=p_order_id;

  v_same_shape:=(o.item_count=v_count and o.subtotal=v_sub and o.separate_shipping_sum=v_sep and o.total_weight_grams=v_weight);
  v_keep_confirmed:=(o.shipping_quote_status='confirmed' and v_same_shape and (o.shipping_quote_country_code is null or o.shipping_quote_country_code is not distinct from v_country));

  if v_keep_confirmed then
    update public.market_orders
    set item_count=v_count,subtotal=round(v_sub,2),separate_shipping_sum=round(v_sep,2),
        total_weight_grams=v_weight,shipping_quote_country_code=coalesce(o.shipping_quote_country_code,v_country),
        total_amount=round(v_sub+coalesce(o.shipping_cost,0),2),
        shipping_savings=round(v_sep-coalesce(o.shipping_cost,0),2),updated_at=now()
    where id=p_order_id;
    return;
  end if;

  if o.fulfillment_group='pickup' then
    v_method:='pickup';
    v_auto_cost:=0;
    v_review:=false;
    v_country:=null;
  else
    select case max(case i.shipping_method when 'standard_letter' then 1 when 'tracked_letter' then 2 when 'parcel' then 3 when 'custom' then 4 else 0 end)
             when 1 then 'standard_letter' when 2 then 'tracked_letter' when 3 then 'parcel' else 'custom' end
    into v_method
    from public.market_order_items i
    join public.market_deals d on d.id=i.deal_id
    where i.order_id=p_order_id and d.status<>'cancelled';

    v_method:=coalesce(v_method,'custom');
    v_fallback_method:=v_method;
    v_auto_cost:=v_fallback_cost;
    v_combined:=(v_count>1 or v_units>1);

    if not v_combined then
      v_review:=v_custom;
      if v_review then v_note:='Versand nach Absprache muss vom Verkäufer bestätigt werden.'; end if;
    elsif v_custom or v_country is null then
      v_review:=true;
      v_note:='Combined Shipping muss vom Verkäufer geprüft werden.';
    else
      select p.id,r.id,p.shipping_method,r.shipping_cost,p.name,p.carrier_label
      into v_profile,v_rule,v_candidate_method,v_candidate_cost,v_profile_name,v_carrier
      from public.market_shipping_profiles p
      join public.market_shipping_profile_rules r on r.profile_id=p.id
      where p.seller_id=o.seller_id
        and p.is_active
        and p.destination_country_code=v_country
        and (p.product_scope='all' or (p.product_scope='cards' and not v_has_sealed) or (p.product_scope='sealed' and not v_has_cards))
        and (r.max_units is null or v_units<=r.max_units)
        and (r.max_weight_grams is null or (not v_missing_weight and v_weight<=r.max_weight_grams))
        and (not v_has_sealed or r.max_length_mm is null or (not v_missing_sealed_dims and v_max_l<=r.max_length_mm))
        and (not v_has_sealed or r.max_width_mm is null or (not v_missing_sealed_dims and v_max_w<=r.max_width_mm))
        and (not v_has_sealed or r.max_height_mm is null or (not v_missing_sealed_dims and v_max_h<=r.max_height_mm))
      order by r.shipping_cost asc,p.created_at asc,r.sort_order asc,p.id
      limit 1;

      if v_profile is null then
        v_review:=true;
        v_method:=v_fallback_method;
        v_auto_cost:=v_fallback_cost;
        v_note:='Keine sichere Versandprofil-Regel passt auf diese Order. Verkäufer prüft den Gesamtversand.';
      else
        v_review:=false;
        v_method:=coalesce(v_candidate_method,v_fallback_method);
        v_auto_cost:=coalesce(v_candidate_cost,v_fallback_cost);
        v_note:=left('Automatisch nach Versandprofil: '||v_profile_name||coalesce(' · '||nullif(v_carrier,''),''),240);
      end if;
    end if;
  end if;

  v_method:=coalesce(v_method,'custom');
  v_auto_cost:=coalesce(v_auto_cost,0);

  update public.market_orders
  set item_count=v_count,
      subtotal=round(v_sub,2),
      separate_shipping_sum=round(v_sep,2),
      total_weight_grams=v_weight,
      shipping_method=v_method,
      shipping_cost=round(v_auto_cost,2),
      shipping_quote_status=case when v_review then 'review_required' else 'auto' end,
      shipping_note=v_note,
      shipping_profile_id=case when v_review then null else v_profile end,
      shipping_profile_rule_id=case when v_review then null else v_rule end,
      shipping_quote_country_code=v_country,
      total_amount=round(v_sub+v_auto_cost,2),
      shipping_savings=round(v_sep-v_auto_cost,2),
      payment_status=case when payment_provider='stripe_connect' and paid_amount>0 and paid_amount<round(v_sub+v_auto_cost,2) then 'balance_due' else payment_status end,
      updated_at=now()
  where id=p_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_market_stripe_refund_evidence(p_event_id text, p_account_id text, p_charge_id text, p_refund_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare
  a dv_market_private.market_payment_attempts%rowtype;
  e dv_market_private.market_stripe_events%rowtype;
begin
  if p_event_id !~ '^evt_[A-Za-z0-9]+$'
     or p_account_id !~ '^acct_[A-Za-z0-9]+$'
     or p_charge_id !~ '^ch_[A-Za-z0-9]+$'
     or p_refund_id !~ '^re_[A-Za-z0-9]+$' then
    raise exception 'stripe_refund_evidence_invalid';
  end if;

  select * into e
  from dv_market_private.market_stripe_events
  where stripe_event_id=p_event_id
    and event_type='charge.refunded'
    and stripe_account_id=p_account_id
    and object_id=p_charge_id
    and not live_mode
    and processing_status='applied'
  for update;
  if not found then raise exception 'stripe_refund_event_not_reconcilable'; end if;

  if nullif(e.normalized_data->>'refund_id','') is not null
     and e.normalized_data->>'refund_id'<>p_refund_id then
    raise exception 'stripe_refund_event_reference_mismatch';
  end if;

  select * into a
  from dv_market_private.market_payment_attempts
  where stripe_account_id=p_account_id
    and stripe_charge_id=p_charge_id
    and state='refunded'
    and paid_cents>0
    and refunded_cents=paid_cents
  for update;
  if not found then raise exception 'stripe_refund_attempt_not_reconcilable'; end if;

  if exists(
    select 1 from public.market_orders
    where id=a.order_id and provider_refund_ref is not null and provider_refund_ref<>p_refund_id
  ) then raise exception 'stripe_order_refund_reference_mismatch'; end if;

  if exists(
    select 1 from dv_market_private.market_refund_requests
    where attempt_id=a.id and stripe_refund_id is not null and stripe_refund_id<>p_refund_id
  ) then raise exception 'stripe_refund_request_reference_mismatch'; end if;

  if exists(
    select 1 from dv_market_private.market_tax_events
    where event_key like 'stripe-refund:'||p_event_id||':%'
      and source_reference is not null and source_reference<>p_refund_id
  ) then raise exception 'stripe_tax_refund_reference_mismatch'; end if;

  update public.market_orders
  set provider_refund_ref=p_refund_id,updated_at=now()
  where id=a.order_id and payment_status='refunded' and refund_status='refunded';
  if not found then raise exception 'stripe_refunded_order_not_found'; end if;

  update dv_market_private.market_refund_requests
  set stripe_refund_id=p_refund_id,updated_at=now()
  where attempt_id=a.id and status='succeeded';
  if not found then raise exception 'stripe_refund_request_not_found'; end if;

  return jsonb_build_object('event_id',p_event_id,'status','reconciled','refund_id',p_refund_id);
end
$function$

CREATE OR REPLACE FUNCTION public.record_market_order_delivery_evidence_b07(p_order_id uuid, p_delivered_at timestamp with time zone, p_source text, p_reference text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.market_orders;
  v_at timestamptz:=coalesce(p_delivered_at,now());
begin
  select * into o
  from public.market_orders
  where id=p_order_id
  for update;

  if not found
     or o.fulfillment_group<>'shipping'
     or o.status not in ('shipped','received') then
    raise exception 'delivery_evidence_not_applicable';
  end if;
  if o.tracking_code is null then
    raise exception 'delivery_evidence_requires_tracking';
  end if;
  if v_at<o.shipped_at or v_at>now()+interval '5 minutes' then
    raise exception 'delivery_evidence_time_invalid';
  end if;
  if nullif(trim(coalesce(p_source,'')),'') is null then
    raise exception 'delivery_evidence_source_required';
  end if;

  update public.market_orders
  set status=case when status='shipped' then 'received' else status end,
      delivery_evidence_at=coalesce(delivery_evidence_at,v_at),
      delivery_evidence_source=coalesce(delivery_evidence_source,left(trim(p_source),80)),
      delivery_evidence_ref=coalesce(
        delivery_evidence_ref,
        nullif(left(trim(coalesce(p_reference,'')),160),'')
      ),
      closure_eligible_at=coalesce(closure_eligible_at,v_at+interval '72 hours'),
      received_at=coalesce(received_at,v_at),
      updated_at=now()
  where id=o.id;
end
$function$

CREATE OR REPLACE FUNCTION public.record_market_tax_remuneration(p_contract_snapshot_id uuid, p_event_key text, p_occurred_at timestamp with time zone, p_gross_consideration numeric, p_platform_fee numeric DEFAULT 0, p_commission numeric DEFAULT 0, p_withheld_tax numeric DEFAULT 0, p_source_type text DEFAULT 'payment_provider'::text, p_source_reference text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_snapshot dv_market_private.market_contract_snapshots%rowtype;
  v_event dv_market_private.market_tax_events%rowtype;
  v_local timestamp;
  v_gross numeric:=round(coalesce(p_gross_consideration,0),2);
  v_fee numeric:=round(coalesce(p_platform_fee,0),2);
  v_commission numeric:=round(coalesce(p_commission,0),2);
  v_tax numeric:=round(coalesce(p_withheld_tax,0),2);
  v_net numeric;
  v_evidence jsonb:=coalesce(p_evidence,'{}'::jsonb);
begin
  if p_contract_snapshot_id is null or p_occurred_at is null
     or char_length(trim(coalesce(p_event_key,''))) not between 8 and 200 then
    raise exception 'tax_event_input_invalid';
  end if;
  if p_source_type not in ('manual_verified','payment_provider') then
    raise exception 'tax_event_source_invalid';
  end if;
  if v_gross<=0 or v_fee<0 or v_commission<0 or v_tax<0
     or v_gross<v_fee+v_commission+v_tax then
    raise exception 'tax_event_amount_invalid';
  end if;
  select * into v_snapshot from dv_market_private.market_contract_snapshots
  where id=p_contract_snapshot_id;
  if not found then raise exception 'contract_snapshot_not_found'; end if;
  if v_snapshot.currency<>'EUR' then raise exception 'tax_event_currency_unsupported'; end if;
  v_net:=round(v_gross-v_fee-v_commission-v_tax,2);
  v_local:=p_occurred_at at time zone 'Europe/Berlin';
  v_evidence:=v_evidence||jsonb_build_object(
    'contract_snapshot_id',v_snapshot.id,'deal_id',v_snapshot.deal_id,
    'source_reference',nullif(trim(coalesce(p_source_reference,'')),''),
    'recorded_gross',v_gross,'recorded_remuneration',v_net
  );

  insert into dv_market_private.market_tax_events(
    event_key,event_type,seller_id,deal_id,contract_snapshot_id,occurred_at,
    reporting_year,reporting_quarter,currency,gross_consideration_delta,
    platform_fee_delta,commission_delta,withheld_tax_delta,remuneration_delta,
    activity_count_delta,source_type,source_reference,evidence,evidence_sha256,recorded_by
  ) values (
    trim(p_event_key),'remuneration_paid_or_credited',v_snapshot.seller_id,v_snapshot.deal_id,
    v_snapshot.id,p_occurred_at,extract(year from v_local)::integer,
    extract(quarter from v_local)::integer,'EUR',v_gross,v_fee,v_commission,v_tax,v_net,1,
    p_source_type,nullif(left(trim(coalesce(p_source_reference,'')),500),''),
    v_evidence,digest(v_evidence::text,'sha256'),auth.uid()
  ) returning * into v_event;

  return jsonb_build_object('event_id',v_event.id,'event_type',v_event.event_type,
    'reporting_year',v_event.reporting_year,'reporting_quarter',v_event.reporting_quarter,
    'remuneration',v_event.remuneration_delta,'activity_count_delta',1);
exception when unique_violation then
  select * into v_event from dv_market_private.market_tax_events where event_key=trim(p_event_key);
  if v_event.contract_snapshot_id=p_contract_snapshot_id
     and v_event.event_type='remuneration_paid_or_credited'
     and v_event.gross_consideration_delta=v_gross
     and v_event.platform_fee_delta=v_fee
     and v_event.commission_delta=v_commission
     and v_event.withheld_tax_delta=v_tax
     and v_event.occurred_at=p_occurred_at then
    return jsonb_build_object('event_id',v_event.id,'event_type',v_event.event_type,
      'reporting_year',v_event.reporting_year,'reporting_quarter',v_event.reporting_quarter,
      'remuneration',v_event.remuneration_delta,'activity_count_delta',1,'replayed',true);
  end if;
  raise exception 'tax_event_idempotency_conflict';
end
$function$

CREATE OR REPLACE FUNCTION public.register_my_market_listing_image(p_listing_id uuid, p_storage_path text, p_sort_order smallint DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l public.market_listings; v_id uuid; v_path text;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into l from public.market_listings where id=p_listing_id;
  if l.id is null or l.seller_id<>auth.uid() or l.product_kind<>'sealed' or l.status<>'draft' then raise exception 'Nicht erlaubt'; end if;
  v_path:=trim(coalesce(p_storage_path,''));
  if v_path='' or split_part(v_path,'/',1)<>auth.uid()::text or split_part(v_path,'/',2)<>p_listing_id::text then raise exception 'Ungültiger Bildpfad'; end if;
  insert into public.market_listing_images(listing_id,seller_id,storage_path,sort_order)
  values(p_listing_id,auth.uid(),v_path,greatest(0,least(coalesce(p_sort_order,0),20)))
  returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.release_account_deletion_hold(p_hold_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_hold dv_market_private.account_deletion_holds%rowtype;
begin
  if char_length(trim(coalesce(p_reason,'')))<10 then raise exception 'hold_release_reason_required'; end if;
  update dv_market_private.account_deletion_holds set released_at=now()
  where id=p_hold_id and released_at is null returning * into v_hold;
  if not found then raise exception 'retention_hold_not_found'; end if;
  insert into dv_market_private.account_data_rights_audit(user_id,request_id,event_type,event_data)
  values(v_hold.user_id,v_hold.request_id,'retention_hold_released',jsonb_build_object('category',v_hold.category,'reason',left(trim(p_reason),500)));
end
$function$

CREATE OR REPLACE FUNCTION public.release_fixed_price_market_offer_v1(p_offer_id uuid, p_reason text DEFAULT 'payment_request_failed'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare o public.market_offers;l public.market_listings;v_restore integer;v_listing_id uuid;
begin
  select listing_id into v_listing_id from public.market_offers where id=p_offer_id;
  if not found then return false; end if;
  select * into l from public.market_listings where id=v_listing_id for update;
  select * into o from public.market_offers where id=p_offer_id for update;
  if not found or o.offer_type<>'fixed_price' or o.status<>'pending'
     or exists(select 1 from public.market_deals where offer_id=o.id) then return false; end if;
  v_restore:=o.reserved_quantity;
  if l.id is null or o.listing_id is distinct from l.id or v_restore is null or v_restore<=0
     or l.quantity_available+v_restore>l.stock_quantity then
    raise exception 'market_reservation_inventory_inconsistent';
  end if;
  update public.market_offers
  set status='expired',message=left(coalesce(p_reason,'payment_request_failed'),500),
      reserved_quantity=0,reservation_expires_at=null,updated_at=now()
  where id=o.id;
  if l.id is not null then
    update public.market_listings
    set quantity_available=quantity_available+v_restore,
        status=case when status='reserved' then 'active' else status end,updated_at=now()
    where id=l.id;
  end if;
  return true;
end
$function$

CREATE OR REPLACE FUNCTION public.remove_my_market_listing_image(p_image_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.market_listing_images; l public.market_listings; v_count int; v_min int;
begin
 select * into i from public.market_listing_images where id=p_image_id for update;
 if i.id is null or i.seller_id<>auth.uid() then raise exception 'Nicht erlaubt'; end if;
 select * into l from public.market_listings where id=i.listing_id for update;
 if l.status not in ('draft','active','paused') then raise exception 'Produktfoto ist gesperrt'; end if;
 select count(*) into v_count from public.market_listing_images where listing_id=l.id;
 v_min:=case when l.sealed_category='case' then 3 else 1 end;
 if l.status<>'draft' and v_count<=v_min then raise exception 'Mindestens % Produktfoto(s) müssen erhalten bleiben',v_min; end if;
 delete from public.market_listing_images where id=i.id; return i.storage_path;
end $function$

