CREATE OR REPLACE FUNCTION public.respond_to_market_offer(p_offer_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare o public.market_offers;l public.market_listings;v_qty integer;v_left integer;v_deal_id uuid;v_review jsonb;v_f jsonb;v_at timestamptz:=clock_timestamp();
begin
 if auth.uid() is null or p_action not in ('accepted','declined') then raise exception 'Nicht erlaubt'; end if;
 perform public.expire_market_offer_reservations_v1();select * into o from public.market_offers where id=p_offer_id;
 if o.id is null or o.seller_id<>auth.uid() or o.offer_type<>'price' then raise exception 'Angebot nicht verfügbar'; end if;
 select * into l from public.market_listings where id=o.listing_id for update;select * into o from public.market_offers where id=p_offer_id for update;
 if o.status=p_action then return; end if;if o.status='accepted' and exists(select 1 from public.market_deals d where d.offer_id=o.id) then return; end if;
 if o.status<>'pending' then raise exception 'Angebot ist nicht verfügbar'; end if;
 if p_action='declined' then update public.market_offers set status='declined',responded_at=v_at,updated_at=v_at where id=o.id;return;end if;
 if l.status<>'active' or l.seller_id<>auth.uid() then raise exception 'Listing ist nicht aktiv'; end if;
 perform dv_market_private.require_market_buyer_type(o.buyer_id);if o.buyer_type_snapshot is distinct from 'consumer' then raise exception 'buyer_snapshot_invalid'; end if;
 v_review:=o.contract_review_snapshot;
 if v_review is null or jsonb_typeof(v_review)<>'object' or v_review->>'snapshot_version'<>'price-offer-contract-v1' or o.offer_review_hash is null
    or encode(digest(convert_to(v_review::text,'UTF8'),'sha256'),'hex')<>o.offer_review_hash then raise exception 'offer_contract_snapshot_invalid'; end if;
 if (v_review->>'listing_id')::uuid<>o.listing_id or (v_review->>'seller_id')::uuid<>o.seller_id or v_review->>'buyer_type'<>'consumer' or v_review->>'currency'<>'EUR'
    or round((v_review->>'offered_goods_total')::numeric,2)<>round(o.amount,2) or (v_review->>'quantity')::integer<>coalesce(o.requested_quantity,1) then raise exception 'offer_contract_snapshot_mismatch'; end if;
 v_qty:=(v_review->>'quantity')::integer;if v_qty<1 or v_qty>l.quantity_available then raise exception 'Menge nicht mehr verfügbar'; end if;v_left:=l.quantity_available-v_qty;v_f:=coalesce(v_review->'fulfillment_snapshot','{}'::jsonb);
 update public.market_offers set status='accepted',responded_at=v_at,reserved_quantity=null,reservation_expires_at=null,updated_at=v_at where id=o.id;
 update public.market_offers set status='declined',responded_at=v_at,updated_at=v_at where listing_id=o.listing_id and id<>o.id and offer_type='price' and status='pending' and requested_quantity>v_left;
 update public.market_listings set quantity_available=v_left,status=case when v_left=0 then 'reserved' else 'active' end,accepted_offer_id=o.id,deal_price=(v_review->>'offered_goods_total')::numeric,deal_buyer_id=o.buyer_id,updated_at=v_at where id=l.id;
 insert into public.market_deals(listing_id,offer_id,seller_id,buyer_id,amount,currency,status,accepted_at,shipping_method,shipping_cost,shipping_note,product_kind,sealed_category,item_quantity,package_contents,weight_grams,length_mm,width_mm,height_mm)
 values(l.id,o.id,o.seller_id,o.buyer_id,(v_review->>'offered_goods_total')::numeric,'EUR','accepted',v_at,v_review->>'shipping_method',(v_review->>'shipping_cost')::numeric,v_review->>'shipping_note',
   v_f->>'product_kind',v_f->>'sealed_category',v_qty,v_f->>'package_contents',case when nullif(v_f->>'unit_weight_grams','') is null then null else (v_f->>'unit_weight_grams')::integer*v_qty end,
   nullif(v_f->>'length_mm','')::integer,nullif(v_f->>'width_mm','')::integer,nullif(v_f->>'height_mm','')::integer)
 on conflict (offer_id) do nothing returning id into v_deal_id;
 if v_deal_id is null then select id into v_deal_id from public.market_deals where offer_id=o.id;end if;if v_deal_id is null then raise exception 'offer_contract_creation_failed'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.review_battle_report(p_report_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 select array[r.reported_user_id] into d3_targets from public.battle_reports r where r.id=p_report_id;
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((false),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();
 perform 1 from public.battle_reports r where r.id=p_report_id and array[r.reported_user_id] is not distinct from d3_targets for update; if not found then raise exception 'd3_case_changed_or_missing' using errcode='42501'; end if;
  declare v_uid uuid:=auth.uid(); v_role text; v_report public.battle_reports%rowtype; begin perform public.require_duelvanta_privileged_session(); if v_uid is null then raise exception 'Authentication required'; end if; select role into v_role from public.profiles where id=v_uid; if v_role not in ('owner','admin','moderator') and not exists(select 1 from public.staff_permissions where user_id=v_uid and permission='review_reports') then raise exception 'Report review permission required'; end if; select * into v_report from public.battle_reports where id=p_report_id for update; if not found then raise exception 'Report not found'; end if; if p_action='review' then update public.battle_reports set status='reviewing',reviewer_id=v_uid,reviewing_at=coalesce(reviewing_at,now()),reviewer_note=left(nullif(trim(p_note),''),1000) where id=p_report_id; elsif p_action in ('warning','restrict') then raise exception 'review_action_disabled' using errcode='42501'; elsif p_action in ('resolve','dismiss') then if not public.has_staff_permission('reports_review',v_uid) then raise exception 'reports_review permission required'; end if; if public.is_duelvanta_owner(v_report.reported_user_id) then raise exception 'Owner cannot be targeted by moderation actions'; end if; if v_report.status not in ('open','reviewing') then raise exception 'report_already_closed'; end if; update public.battle_reports set status=case when p_action='dismiss' then 'dismissed' else 'resolved' end,reviewer_id=v_uid,reviewing_at=coalesce(reviewing_at,now()),resolved_at=now(),reviewer_note=left(nullif(trim(p_note),''),1000),resolution_action='none' where id=p_report_id; else raise exception 'Invalid review action'; end if; insert into public.admin_audit_log(actor_id,target_user_id,action,details) values(v_uid,v_report.reported_user_id,'battle_report_'||p_action,jsonb_build_object('report_id',p_report_id,'category',v_report.category,'note',left(coalesce(p_note,''),1000))); return p_action; end;
end
$function$

CREATE OR REPLACE FUNCTION public.review_market_checkout(p_listing_id uuid, p_quantity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_uid uuid:=auth.uid();v_listing public.market_listings%rowtype;v_seller jsonb;v_product jsonb;
  v_buyer_type text;v_class text;v_unit numeric;v_goods numeric;v_shipping numeric;v_review jsonb;v_tier jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  v_buyer_type:=dv_market_private.require_market_buyer_type(v_uid);
  if p_quantity is null or p_quantity not between 1 and 1000 then raise exception 'checkout_quantity_invalid'; end if;
  select * into v_listing from public.market_listings where id=p_listing_id;
  if not found or v_listing.status<>'active' then raise exception 'listing_not_available'; end if;
  if v_listing.seller_id=v_uid then raise exception 'own_listing_checkout_forbidden'; end if;
  if v_listing.listing_type not in ('sale','sale_or_trade') or v_listing.pricing_mode<>'fixed' then raise exception 'fixed_price_checkout_required'; end if;
  if v_listing.active_until is not null and v_listing.active_until<=now() then raise exception 'listing_expired'; end if;
  if (v_listing.product_kind='sealed' and (p_quantity<v_listing.minimum_purchase_quantity or p_quantity>v_listing.quantity_available))
     or (v_listing.product_kind<>'sealed' and (p_quantity<>1 or v_listing.quantity_available<1)) then raise exception 'checkout_quantity_unavailable'; end if;
  if v_listing.asking_price is null or v_listing.asking_price<=0
     or v_listing.asking_price::text in ('NaN','Infinity','-Infinity') then raise exception 'checkout_price_invalid'; end if;
  if v_listing.shipping_cost is null or v_listing.shipping_cost<0 or v_listing.shipping_cost>500 or v_listing.shipping_method is null then
    raise exception 'checkout_shipping_incomplete';
  end if;
  v_unit:=v_listing.asking_price;
  if v_listing.product_kind='sealed' then
    for v_tier in select value from jsonb_array_elements(coalesce(v_listing.quantity_pricing,'[]'::jsonb))
      order by (value->>'min_quantity')::integer
    loop
      if p_quantity >= (v_tier->>'min_quantity')::integer then v_unit:=(v_tier->>'unit_price')::numeric; end if;
    end loop;
  end if;
  if v_unit is null or v_unit<=0 or v_unit::text in ('NaN','Infinity','-Infinity') then raise exception 'checkout_price_invalid'; end if;
  v_unit:=round(v_unit,2);v_goods:=round(v_unit*p_quantity,2);v_shipping:=round(v_listing.shipping_cost,2);
  v_seller:=dv_market_private.market_checkout_seller_party(v_listing.seller_id);
  v_product:=dv_market_private.market_checkout_product_snapshot(v_listing);
  v_class:=dv_market_private.market_contract_classification(v_seller->>'seller_type',v_buyer_type);
  if v_class is null then raise exception 'contract_classification_invalid'; end if;
  v_review:=jsonb_build_object(
    'snapshot_version','checkout-contract-v2','listing_id',v_listing.id,'listing_updated_at',v_listing.updated_at,
    'seller_id',v_listing.seller_id,'seller_type',v_seller->>'seller_type','buyer_type',v_buyer_type,
    'contract_classification',v_class,'seller_party',v_seller,
    'platform_operator',jsonb_build_object(
      'role','Marketplace-Vermittler','name','Benjamin Fritz – DUELVANTA',
      'street_line1','Landhausstraße 12','postal_code','75399','city','Unterreichenbach',
      'country_code','DE','email','info@duelvanta.de'),
    'product',v_product,'quantity',p_quantity,'unit_price',v_unit,'goods_total',v_goods,
    'shipping_method',v_listing.shipping_method,'shipping_cost',v_shipping,'shipping_note',v_listing.shipping_note,
    'fulfillment_snapshot',jsonb_strip_nulls(jsonb_build_object(
      'product_kind',v_listing.product_kind,'sealed_category',v_listing.sealed_category,'package_contents',v_listing.package_contents,
      'weight_grams',v_listing.weight_grams,'length_mm',v_listing.length_mm,'width_mm',v_listing.width_mm,'height_mm',v_listing.height_mm)),
    'total_price',round(v_goods+v_shipping,2),'currency','EUR','payment_provider','stripe_connect',
    'payment_notice','Dein Klick gibt ein verbindliches Kaufangebot ab. Der Vertrag entsteht erst, wenn DUELVANTA unmittelbar die Stripe-Zahlungsaufforderung für den Verkäufer erzeugt.'
  );
  return v_review||jsonb_build_object('checkout_hash',encode(digest(convert_to(v_review::text,'UTF8'),'sha256'),'hex'));
end
$function$

CREATE OR REPLACE FUNCTION public.review_market_offer_checkout_v1(p_offer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_uid uuid:=auth.uid();
  o public.market_offers;
  l public.market_listings;
  v_seller jsonb;
  v_product jsonb;
  v_qty integer;
  v_goods numeric;
  v_unit numeric;
  v_shipping numeric;
  v_review jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into o from public.market_offers where id=p_offer_id;
  if not found or o.buyer_id<>v_uid then raise exception 'offer_checkout_not_available'; end if;
  if o.status<>'accepted' or o.reservation_expires_at is null or o.reservation_expires_at<=now() then
    raise exception 'offer_reservation_expired';
  end if;
  if exists(select 1 from public.market_deals d where d.offer_id=o.id) then raise exception 'offer_already_checked_out'; end if;
  select * into l from public.market_listings where id=o.listing_id;
  if not found or l.seller_id<>o.seller_id or l.status not in ('active','reserved') then raise exception 'listing_not_available'; end if;

  v_qty:=greatest(coalesce(o.reserved_quantity,o.requested_quantity,1),1);
  v_goods:=round(o.amount,2);
  if v_goods<=0 or v_goods::text in ('NaN','Infinity','-Infinity') then raise exception 'checkout_price_invalid'; end if;
  v_unit:=round(v_goods/v_qty,2);
  if l.shipping_cost is null or l.shipping_cost<0 or l.shipping_cost>500 or l.shipping_method is null then
    raise exception 'checkout_shipping_incomplete';
  end if;
  v_shipping:=round(l.shipping_cost,2);
  v_seller:=dv_market_private.market_checkout_seller_party(l.seller_id);
  v_product:=dv_market_private.market_checkout_product_snapshot(l);

  v_review:=jsonb_build_object(
    'snapshot_version','checkout-contract-v1','offer_id',o.id,'listing_id',l.id,
    'reservation_expires_at',o.reservation_expires_at,'seller_id',l.seller_id,
    'seller_type',v_seller->>'seller_type',
    'contract_classification',case when v_seller->>'seller_type'='trader' then 'b2c' else 'c2c' end,
    'seller_party',v_seller,
    'platform_operator',jsonb_build_object(
      'role','Marketplace-Vermittler','name','Benjamin Fritz – DUELVANTA',
      'street_line1','Landhausstraße 12','postal_code','75399','city','Unterreichenbach',
      'country_code','DE','email','info@duelvanta.de'),
    'product',v_product,'quantity',v_qty,'unit_price',v_unit,'goods_total',v_goods,
    'shipping_method',l.shipping_method,'shipping_cost',v_shipping,
    'total_price',round(v_goods+v_shipping,2),'currency','EUR','payment_provider','manual_beta',
    'payment_notice','Keine integrierte Onlinezahlung. Die Bestellung begründet dennoch eine Zahlungspflicht gegenüber dem Verkäufer.'
  );
  return v_review || jsonb_build_object(
    'checkout_hash',encode(digest(convert_to(v_review::text,'UTF8'),'sha256'),'hex')
  );
end
$function$

CREATE OR REPLACE FUNCTION public.review_market_order_delivery_b07(p_order_id uuid, p_decision text, p_delivered_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare o public.market_orders;v_decision text:=lower(trim(coalesce(p_decision,'')));v_note text:=nullif(left(trim(coalesce(p_note,'')),1000),'');v_ref text:=nullif(left(trim(coalesce(p_reference,'')),160),'');v_at timestamptz:=coalesce(p_delivered_at,now());
begin perform public.require_duelvanta_privileged_session();
  if not dv_market_private.is_market_owner_caller() then raise exception 'Owner-Zugriff erforderlich';end if;
  if v_decision not in ('verify','reject') then raise exception 'Ungültige Entscheidung';end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if not found or o.delivery_review_status<>'pending' then raise exception 'Keine offene Zustellprüfung';end if;
  if o.tracking_code is null or o.shipped_at is null then raise exception 'Trackingdaten fehlen';end if;
  if v_decision='reject' then
    if v_note is null then raise exception 'Begründung bei Ablehnung erforderlich';end if;
    update public.market_orders set delivery_review_status='rejected',delivery_reviewed_at=now(),delivery_reviewed_by=auth.uid(),delivery_review_note=v_note,updated_at=now() where id=o.id;
    insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
    values(o.seller_id,'order_received','ZUSTELLPRÜFUNG NICHT BESTÄTIGT',o.order_number||' · '||v_note,o.id,'delivery_rejected_seller:'||o.id::text||':'||extract(epoch from now())::bigint::text)
    on conflict(dedupe_key) do nothing;
    return jsonb_build_object('status','rejected');
  end if;
  if p_delivered_at is null then raise exception 'Zustellzeitpunkt erforderlich';end if;
  if v_at<o.shipped_at or v_at>now()+interval '5 minutes' then raise exception 'delivery_evidence_time_invalid';end if;
  perform public.record_market_order_delivery_evidence_b07(o.id,v_at,'owner_carrier_verification',coalesce(v_ref,o.carrier||':'||o.tracking_code));
  update public.market_orders set delivery_review_status='verified',delivery_reviewed_at=now(),delivery_reviewed_by=auth.uid(),delivery_review_note=v_note,updated_at=now() where id=o.id;
  insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
  values(o.buyer_id,'order_received','ZUSTELLUNG VERIFIZIERT',o.order_number||' · Zustellung wurde anhand der Sendungsverfolgung geprüft. Ohne offenen Problemfall erfolgt der technische Abschluss nach 72 Stunden.',o.id,'delivery_verified_buyer:'||o.id::text)
  on conflict(dedupe_key) do nothing;
  insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
  values(o.seller_id,'order_received','ZUSTELLPRÜFUNG BESTÄTIGT',o.order_number||' · Die 72-Stunden-Frist läuft ab dem verifizierten Zustellzeitpunkt.',o.id,'delivery_verified_seller:'||o.id::text)
  on conflict(dedupe_key) do nothing;
  return jsonb_build_object('status','verified','delivered_at',v_at,'closure_eligible_at',v_at+interval '72 hours');
end $function$

CREATE OR REPLACE FUNCTION public.review_market_price_offer_v1(p_listing_id uuid, p_requested_quantity integer, p_amount numeric)
