CREATE OR REPLACE FUNCTION public.review_market_seller_onboarding(p_seller_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_decision text := lower(trim(coalesce(p_decision, '')));
  v_account public.market_seller_accounts%rowtype;
  v_legal dv_market_private.seller_legal_profiles%rowtype;
  v_tax_required boolean := true;
begin perform public.require_duelvanta_privileged_session();
  if not dv_market_private.is_market_owner_caller() then
    raise exception 'owner_access_required';
  end if;
  if p_seller_id is null or v_decision not in ('approve','reject','suspend') then
    raise exception 'invalid_review_decision';
  end if;
  if v_decision in ('reject','suspend') and nullif(trim(coalesce(p_reason,'')),'') is null then
    raise exception 'review_reason_required';
  end if;

  select * into v_account from public.market_seller_accounts
  where seller_id=p_seller_id for update;
  select * into v_legal from dv_market_private.seller_legal_profiles
  where seller_id=p_seller_id;
  select tax_identifier_required_for_activation into v_tax_required
  from dv_market_private.marketplace_compliance_policy where singleton=true;

  if v_account.seller_id is null then raise exception 'seller_account_not_found'; end if;
  if v_decision='approve' then
    if v_account.onboarding_status<>'pending_review' or v_legal.seller_id is null then
      raise exception 'seller_not_ready_for_approval';
    end if;
    if coalesce(v_tax_required,true) and not exists (
      select 1 from dv_market_private.seller_tax_identifiers
      where seller_id=p_seller_id and identifier_kind in ('tin','vat_id')
    ) then
      raise exception 'seller_tax_identifier_required';
    end if;
    update public.market_seller_accounts
    set onboarding_status='active',verified_at=now(),suspended_at=null,updated_at=now()
    where seller_id=p_seller_id;
  elsif v_decision='reject' then
    if v_account.onboarding_status<>'pending_review' then
      raise exception 'seller_not_pending_review';
    end if;
    update public.market_seller_accounts
    set onboarding_status='rejected',verified_at=null,updated_at=now()
    where seller_id=p_seller_id;
  else
    update public.market_seller_accounts
    set onboarding_status='suspended',verified_at=null,suspended_at=now(),updated_at=now()
    where seller_id=p_seller_id;
  end if;

  insert into dv_market_private.seller_review_actions(seller_id,actor_id,action,reason)
  values(p_seller_id,v_actor,v_decision,nullif(left(trim(coalesce(p_reason,'')),1000),''));

  return jsonb_build_object('seller_id',p_seller_id,'decision',v_decision,'status',
    case v_decision when 'approve' then 'active' when 'reject' then 'rejected' else 'suspended' end);
end
$function$

CREATE OR REPLACE FUNCTION public.review_marketplace_notice_appeal(p_appeal_id uuid, p_outcome text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_appeal dv_market_private.listing_notice_appeals%rowtype; v_notice dv_market_private.listing_notices%rowtype; v_outcome text:=lower(trim(coalesce(p_outcome,''))); v_reason text:=trim(coalesce(p_reason,''));
begin perform public.require_duelvanta_privileged_session();
  if not dv_market_private.notice_owner_caller() then raise exception 'owner_access_required'; end if;
  if v_outcome not in ('upheld','reversed') then raise exception 'invalid_appeal_outcome'; end if;
  if char_length(v_reason) not between 30 and 5000 then raise exception 'appeal_decision_reason_invalid'; end if;
  select * into v_appeal from dv_market_private.listing_notice_appeals where id=p_appeal_id for update;
  if not found then raise exception 'appeal_not_found'; end if;
  if v_appeal.status not in ('submitted','under_review') then raise exception 'appeal_already_decided'; end if;
  select * into v_notice from dv_market_private.listing_notices where id=v_appeal.notice_id for update;

  update dv_market_private.listing_notice_appeals set status=v_outcome,reviewer_id=auth.uid(),decision_reason=v_reason,decided_at=now() where id=v_appeal.id returning * into v_appeal;
  if v_outcome='reversed' then
    update dv_market_private.listing_notices set status='closed',decision_action='no_action',decision_basis_kind='no_violation',decision_reference=null,decision_reason=v_reason,decision_scope=null,decision_duration=null,decided_at=now(),updated_at=now() where id=v_notice.id returning * into v_notice;
    if v_notice.listing_id is not null and v_notice.original_listing_status='active' and not exists(
      select 1 from dv_market_private.listing_notices other where other.listing_id=v_notice.listing_id and other.id<>v_notice.id and other.status in ('decided_restricted','decided_removed')
    ) then
      update public.market_listings set status='active',updated_at=now() where id=v_notice.listing_id and status='paused';
    end if;
  else
    update dv_market_private.listing_notices set status='closed',updated_at=now() where id=v_notice.id returning * into v_notice;
  end if;
  insert into dv_market_private.listing_notice_events(notice_id,actor_id,event_type,event_data)
  values(v_notice.id,auth.uid(),'appeal_decided',jsonb_build_object('appeal_id',v_appeal.id,'outcome',v_outcome));
  insert into dv_market_private.marketplace_message_outbox(notice_id,recipient_kind,recipient_user_id,recipient_email,message_kind,payload)
  values(
    v_notice.id,v_appeal.appellant_kind,
    case when v_appeal.appellant_kind='seller' then v_appeal.appellant_user_id else null end,
    case when v_appeal.appellant_kind='reporter' then v_notice.reporter_email else null end,
    'appeal_decided',jsonb_build_object('case_reference',v_notice.case_reference,'outcome',v_outcome,'reason',v_reason)
  );
  return jsonb_build_object('appeal_id',v_appeal.id,'outcome',v_outcome,'notice_status',v_notice.status,'decided_at',v_appeal.decided_at);
end
$function$

CREATE OR REPLACE FUNCTION public.review_staff_application(p_application_id uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 select array[a.applicant_id] into d3_targets from public.staff_applications a where a.id=p_application_id;
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((false),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();
 perform 1 from public.staff_applications a where a.id=p_application_id and array[a.applicant_id] is not distinct from d3_targets for update; if not found then raise exception 'd3_case_changed_or_missing' using errcode='42501'; end if;
  declare v_uid uuid:=auth.uid(); v_app public.staff_applications%rowtype; v_actor_role text; begin perform public.require_duelvanta_privileged_session(); select role into v_actor_role from public.profiles where id=v_uid; if not public.is_duelvanta_owner(v_uid) then raise exception 'Owner approval required during beta'; end if; if p_decision not in ('question','approved','rejected') then raise exception 'Invalid decision'; end if; select * into v_app from public.staff_applications where id=p_application_id for update; if not found or v_app.status not in ('pending','question') then raise exception 'Application unavailable'; end if; update public.staff_applications set status=p_decision,reviewer_id=v_uid,reviewer_note=left(p_note,3000),reviewed_at=case when p_decision in ('approved','rejected') then now() else reviewed_at end,updated_at=now() where id=p_application_id; if p_decision='approved' then update public.profiles set role=v_app.requested_role,updated_at=now() where id=v_app.applicant_id and role='player'; end if; insert into public.admin_audit_log(actor_id,target_user_id,action,details) values(v_uid,v_app.applicant_id,'staff_application_'||p_decision,jsonb_build_object('application_id',p_application_id,'requested_role',v_app.requested_role,'note',left(p_note,1000))); return p_decision; end;
end
$function$

CREATE OR REPLACE FUNCTION public.save_my_tcg_collection_item_v1(p_item_id uuid, p_game_key text, p_item jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare u uuid:=auth.uid();result uuid;r record;x record;k text;v jsonb;num numeric;d date;keys text[]:=array['folder_id','card_name','set_name','card_number','language','variant','condition','quantity','grading_company','grade','cert_number','purchase_price','purchase_date','market_price','currency','notes','contract_version'];
begin
 if u is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'authentication_required' using errcode='42501';end if;
 select * into r from public.profiles where id=u for update;
 if not found or r.data_processing_restricted_at is not null or r.account_closure_requested_at is not null or r.account_status in ('suspended','deleted') then raise exception 'account_data_processing_restricted' using errcode='42501';end if;
 if p_game_key is distinct from 'magic' or not exists(select 1 from dv_collect_private.tcg_catalog_releases where game_key=p_game_key) then raise exception 'catalog_game_invalid';end if;
 -- One DB-owned beta row is locked through commit. No snapshot admission.
 perform 1 from dv_collect_private.tcg_magic_on_demand_beta where game_key='magic' for share;
 if not coalesce((public.get_security_schema_readiness_v1()->>'compatible')::boolean,false)
 or not coalesce((public.get_market_legal_schema_readiness_v1()->>'compatible')::boolean,false) then raise exception 'magic_beta_schema_unavailable';end if;
 if p_item_id is null and not exists(select 1 from dv_collect_private.tcg_magic_on_demand_beta where game_key='magic' and enabled) then raise exception 'magic_beta_unavailable';end if;
 if p_item_id is null and not dv_collect_private.magic_collect_admitted_v1(true) then raise exception 'magic_admission_required' using errcode='42501';end if;
 if jsonb_typeof(p_item) is distinct from 'object' or not p_item ?& keys or (select count(*) from jsonb_object_keys(p_item))<>17 or p_item->'contract_version' is distinct from '"1"'::jsonb then raise exception 'collection_item_input_invalid';end if;
 foreach k in array keys loop
  v:=p_item->k;
  if k not in ('quantity','grade','purchase_price','market_price') and jsonb_typeof(v) not in ('string','null') then raise exception 'collection_item_input_type';end if;
  if jsonb_typeof(v)='string' and v#>>'{}' ~ '[[:cntrl:]]' then raise exception 'collection_item_text_invalid';end if;
 end loop;
 if jsonb_typeof(p_item->'card_name') is distinct from 'string' or length(p_item->>'card_name') not between 1 and 500
 or not coalesce(p_item->>'language' in ('EN','DE','FR','IT','ES','JP','KR','CN'),false)
 or not coalesce(p_item->>'condition' in ('M','NM','EX','GD','LP','PL','POOR','SEALED'),false)
 or not coalesce(p_item->>'currency' in ('EUR','USD','GBP','JPY','CHF'),false)
 or p_item->>'grading_company' is not null and p_item->>'grading_company' not in ('PSA','BGS','CGC','ACE','OTHER') then raise exception 'collection_item_enum_invalid';end if;
 for k,num in select * from (values('set_name',500),('card_number',128),('variant',120),('notes',2000),('cert_number',120)) a(k,num) loop
  if p_item->>k is not null and (length(p_item->>k)>num or k in ('set_name','card_number') and length(p_item->>k)<1) then raise exception 'collection_item_text_limit';end if;
 end loop;
 if jsonb_typeof(p_item->'quantity') is distinct from 'number' or (p_item->>'quantity')::numeric not between 1 and 10000 or trunc((p_item->>'quantity')::numeric)<>(p_item->>'quantity')::numeric then raise exception 'collection_item_quantity';end if;
 foreach k in array array['grade','purchase_price','market_price'] loop
  if p_item->k<>'null'::jsonb then
   if jsonb_typeof(p_item->k)<>'number' then raise exception 'collection_item_numeric_type';end if;num:=(p_item->>k)::numeric;
   if k='grade' then if num not between 1 and 10 or num*10<>trunc(num*10) or p_item->>'grading_company' is null then raise exception 'collection_item_grade';end if;
   elsif num<0 or num>9999999999.99 or num*100<>trunc(num*100) then raise exception 'collection_item_price';end if;
  end if;
 end loop;
 if p_item->>'cert_number' is not null and p_item->>'grading_company' is null then raise exception 'collection_item_grading';end if;
 if p_item->>'purchase_date' is not null then
  if p_item->>'purchase_date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'collection_item_date';end if;d:=(p_item->>'purchase_date')::date;
  if to_char(d,'YYYY-MM-DD')<>p_item->>'purchase_date' then raise exception 'collection_item_date';end if;
 end if;
 if p_item->>'folder_id' is not null and not exists(select 1 from public.collection_folders where id=(p_item->>'folder_id')::uuid and user_id=u) then raise exception 'collection_folder_not_owned';end if;
 if p_item_id is not null and not exists(select 1 from dv_collect_private.tcg_magic_on_demand_beta where game_key='magic' and enabled) then
  select * into x from public.collection_items where id=p_item_id and user_id=u and tcg='magic' for update;
  if not found then raise exception 'tcg_parent_not_owned' using errcode='42501';end if;
  if (x.card_name,x.set_name,x.card_number,x.language,x.variant) is distinct from
  (p_item->>'card_name',p_item->>'set_name',p_item->>'card_number',p_item->>'language',p_item->>'variant') then raise exception 'magic_beta_identity_locked';end if;
 end if;
 if p_item_id is not null then select id into result from public.collection_items where id=p_item_id and user_id=u and tcg=p_game_key for update;if not found then raise exception 'tcg_parent_not_owned' using errcode='42501';end if;
 else result:=gen_random_uuid();end if;
 if p_item_id is null then
  insert into public.collection_items(id,user_id,tcg,folder_id,card_name,set_name,card_number,language,variant,condition,quantity,grading_company,grade,cert_number,purchase_price,purchase_date,market_price,currency,notes)
  values(result,u,p_game_key,(p_item->>'folder_id')::uuid,p_item->>'card_name',p_item->>'set_name',p_item->>'card_number',p_item->>'language',p_item->>'variant',p_item->>'condition',(p_item->>'quantity')::integer,p_item->>'grading_company',(p_item->>'grade')::numeric,p_item->>'cert_number',(p_item->>'purchase_price')::numeric,d,(p_item->>'market_price')::numeric,p_item->>'currency',p_item->>'notes');
 else
  update public.collection_items set folder_id=(p_item->>'folder_id')::uuid,card_name=p_item->>'card_name',set_name=p_item->>'set_name',card_number=p_item->>'card_number',language=p_item->>'language',variant=p_item->>'variant',condition=p_item->>'condition',quantity=(p_item->>'quantity')::integer,grading_company=p_item->>'grading_company',grade=(p_item->>'grade')::numeric,cert_number=p_item->>'cert_number',purchase_price=(p_item->>'purchase_price')::numeric,purchase_date=d,market_price=(p_item->>'market_price')::numeric,currency=p_item->>'currency',notes=p_item->>'notes',updated_at=clock_timestamp() where id=result;
 end if;
 return result;
end$function$

CREATE OR REPLACE FUNCTION public.search_tcg_catalog_cards_v1(p_game_key text, p_set_id uuid, p_collector_number text, p_name text, p_language text, p_finish text, p_limit integer, p_cursor jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare a jsonb;s uuid;query text;pattern text;qhash text;items jsonb:='[]';cur jsonb;last_name text;last_id uuid;t record;n integer:=0;
begin
 a:=public.get_tcg_catalog_release_v1(p_game_key);if a->>'state'<>'ready' then raise exception 'catalog_release_unavailable';end if;s:=(a->>'snapshot_id')::uuid;
 query:=translate(normalize(btrim(p_name),NFC),'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
 if p_limit is null or p_limit not between 1 and 100 or not coalesce(p_language in ('EN','DE','FR','IT','ES','JP','KR','CN'),false)
 or p_name is not null and (length(p_name)>160 or p_name ~ '[[:cntrl:]]')
 or p_collector_number is not null and (length(p_collector_number) not between 1 and 128 or p_collector_number ~ '[[:cntrl:]]')
 or p_set_id is null and p_collector_number is null and not coalesce(length(query)>=2,false)
 or p_finish is not null and p_finish not in ('nonfoil','foil','etched') then raise exception 'catalog_input_invalid';end if;
 pattern:='%'||replace(replace(replace(query,E'\\',E'\\\\'),'%',E'\\%'),'_',E'\\_')||'%';
 qhash:=encode(extensions.digest(convert_to(jsonb_build_array('cards',p_game_key,p_set_id,p_collector_number,query,p_language,p_finish)::text,'UTF8'),'sha256'),'hex');
 if p_cursor is not null then
  if jsonb_typeof(p_cursor)<>'object' or octet_length(p_cursor::text)>2048 or not p_cursor ?& array['snapshot_id','last_name','last_id','query_sha256'] or (select count(*) from jsonb_object_keys(p_cursor))<>4
  or jsonb_typeof(p_cursor->'last_name')<>'string' or length(p_cursor->>'last_name')>500 or p_cursor->>'query_sha256' is distinct from qhash or (p_cursor->>'last_id')::uuid is null then raise exception 'catalog_cursor_invalid';end if;
  if (p_cursor->>'snapshot_id')::uuid is distinct from s then raise exception 'catalog_cursor_stale';end if;last_name:=p_cursor->>'last_name';last_id:=(p_cursor->>'last_id')::uuid;
 end if;
 for t in select c.id,lower(normalize(c.name,NFC) collate "C") sort_name from dv_collect_private.tcg_cards c
 join dv_collect_private.tcg_provider_refs p on p.card_id=c.id and p.entity_kind='card'
 join dv_collect_private.tcg_catalog_snapshot_members m on m.provider_ref_id=p.id and m.snapshot_id=s
 join dv_collect_private.tcg_provider_evidence e on e.id=m.evidence_id
 where (c.game_key,c.language_code)=(p_game_key,p_language) and (p_set_id is null or c.set_id=p_set_id)
 and (p_collector_number is null or c.collector_number=p_collector_number)
 and (query is null or translate(normalize(c.name,NFC),'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz') like pattern escape E'\\')
 and (p_finish is null or e.raw_record->'finishes' ? p_finish)
 and (last_id is null or (lower(normalize(c.name,NFC) collate "C"),c.id)>(last_name collate "C",last_id))
 order by lower(normalize(c.name,NFC) collate "C"),c.id limit p_limit+1 loop
  n:=n+1;if n>p_limit then cur:=jsonb_build_object('snapshot_id',s,'last_name',last_name,'last_id',last_id,'query_sha256',qhash);exit;end if;
  items:=items||jsonb_build_array(public.get_tcg_catalog_card_v1(p_game_key,t.id,null,p_language)->'record');last_name:=t.sort_name;last_id:=t.id;
 end loop;
 return jsonb_build_object('snapshot_id',s,'items',items,'next_cursor',cur);
end$function$

CREATE OR REPLACE FUNCTION public.send_market_pickup_message_v1(p_context_type text, p_context_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_body text:=btrim(coalesce(p_body,''));
  v_id uuid;
begin
  perform dv_market_private.require_pickup_message_context(p_context_type,p_context_id,v_uid,true);
  if char_length(v_body) not between 1 and 1000 then raise exception 'pickup_message_body_invalid';end if;
  if (
    select count(*) from dv_market_private.market_pickup_messages
    where context_type=p_context_type and context_id=p_context_id and sender_id=v_uid
      and created_at>now()-interval '10 minutes'
  )>=20 then raise exception 'pickup_message_rate_limit';end if;

  insert into dv_market_private.market_pickup_messages(context_type,context_id,sender_id,body)
  values(p_context_type,p_context_id,v_uid,v_body)
  returning id into v_id;
  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.set_battle_moderation_pause(p_match_id uuid, p_paused boolean, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 select array[m.host_id,m.guest_id] into d3_targets from public.battle_matches m where m.id=p_match_id;
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((false),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();
 perform 1 from public.battle_matches m where m.id=p_match_id and array[m.host_id,m.guest_id] is not distinct from d3_targets for update; if not found then raise exception 'd3_case_changed_or_missing' using errcode='42501'; end if;
  declare v_uid uuid:=auth.uid(); v_match public.battle_matches%rowtype; begin perform public.require_duelvanta_privileged_session(); if not public.has_staff_permission('battle_moderate',v_uid) then raise exception 'battle_moderate permission required'; end if; select * into v_match from public.battle_matches where id=p_match_id for update; if not found then raise exception 'Match not found'; end if; if v_match.moderator_id is distinct from v_uid and not public.is_duelvanta_owner(v_uid) then raise exception 'Assigned moderator required'; end if; if p_paused then update public.battle_matches set moderation_state='paused',paused_at=now(),paused_by=v_uid,moderation_note=left(nullif(trim(p_note),''),1000),updated_at=now() where id=p_match_id; else update public.battle_matches set moderation_state='joined',paused_at=null,paused_by=null,moderation_note=coalesce(left(nullif(trim(p_note),''),1000),moderation_note),updated_at=now() where id=p_match_id; end if; insert into public.admin_audit_log(actor_id,action,details) values(v_uid,case when p_paused then 'battle_paused' else 'battle_resumed' end,jsonb_build_object('match_id',p_match_id,'note',left(p_note,1000))); return case when p_paused then 'paused' else 'resumed' end; end;
end
$function$

CREATE OR REPLACE FUNCTION public.set_battle_ready(p_match_id uuid, p_ready boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare v public.battle_matches; begin
 if auth.uid() is null then raise exception 'not_authenticated'; end if;
 -- Keep the existing actor/Safety boundary; serialize admission with Hold writes.
 perform 1 from public.profiles where id=auth.uid() for share;
 if not exists(select 1 from public.profiles where id=auth.uid() and account_status in ('beta','active') and not coalesce(safety_restricted,false)) then raise exception 'battle_account_unavailable'; end if;
 if exists(select 1 from public.profiles where id=auth.uid() and data_processing_restricted_at is not null) then
   raise exception 'account_data_processing_restricted' using errcode='42501';
 end if;
 select * into v from public.battle_matches where id=p_match_id for update; if v.id is null or auth.uid() not in (v.host_id,coalesce(v.guest_id,v.host_id)) then raise exception 'Nicht erlaubt'; end if; if v.moderation_state='paused' or v.paused_at is not null then raise exception 'Match ist durch die Moderation pausiert'; end if; if v.status not in ('waiting','ready') then raise exception 'Bereits gestartet'; end if; if auth.uid()=v.host_id then update public.battle_matches set host_ready=p_ready,updated_at=now() where id=v.id; else update public.battle_matches set guest_ready=p_ready,updated_at=now() where id=v.id; end if; end $function$

CREATE OR REPLACE FUNCTION public.set_battle_spectator_link(p_match_id uuid, p_enabled boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.battle_matches%rowtype; held boolean; changed boolean:=false; v_code text;
begin
  perform battle_spectator_private.actor_session(false);
  -- Serialize with marker/Closure writes. Recheck eligibility after any lock wait.
  select p.data_processing_restricted_at is not null into held from public.profiles p where p.id=auth.uid() for share;
  if p_enabled is distinct from false or not coalesce(held,false) then
    perform battle_spectator_private.actor_session();
  end if;
  select * into m from public.battle_matches where id=p_match_id for update;
  perform battle_spectator_private.actor_session(false);
  if m.id is null or m.host_id is distinct from auth.uid() or m.visibility<>'private'
     or m.status not in ('waiting','ready','live','dispute') or p_enabled is null then
    raise exception 'spectator_link_host_only' using errcode='42501'; end if;
  if p_enabled then
    v_code:='SP-'||upper(replace(gen_random_uuid()::text||gen_random_uuid()::text,'-',''));
    insert into battle_spectator_private.links(match_id,generation,secret_hash,enabled)
      values(p_match_id,gen_random_uuid(),encode(sha256(convert_to(v_code,'UTF8')),'hex'),true)
      on conflict(match_id) do update set generation=excluded.generation,secret_hash=excluded.secret_hash,
        enabled=true,updated_at=clock_timestamp();
  else
    -- No missing-state insertion, no generation churn on replay.
    update battle_spectator_private.links set enabled=false,secret_hash=null,generation=gen_random_uuid(),updated_at=clock_timestamp()
      where match_id=p_match_id and enabled;
    changed:=found;
    -- Includes a previously disabled legacy link whose old open epoch was not yet synced.
    if exists(select 1 from battle_spectator_private.links where match_id=p_match_id)
       and exists(select 1 from battle_spectator_media_private.epochs where match_id=p_match_id and media_open) then
      perform battle_spectator_media_private.close_epoch(p_match_id,'generation_changed');
    end if;
    if exists(select 1 from battle_spectator_private.links where match_id=p_match_id) then
      update battle_spectator_media_private.epochs set generation=null where match_id=p_match_id and generation is not null;
    end if;
  end if;
  -- Existing link cleanup. No Match/Auth/Signal deletion, no external media action.
  delete from battle_spectator_private.grants where match_id=p_match_id;
  delete from battle_spectator_private.presence where match_id=p_match_id;
  return jsonb_build_object('match_id',p_match_id,'enabled',p_enabled,'code',v_code)
    ||case when not p_enabled then jsonb_build_object('withdrawn',changed) else '{}'::jsonb end;
end $function$

CREATE OR REPLACE FUNCTION public.set_battle_spectator_media_consent(p_match_id uuid, p_granted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.battle_matches%rowtype; c battle_spectator_media_private.config%rowtype;
  e battle_spectator_media_private.epochs%rowtype; held boolean; changed boolean:=false; g uuid;
begin
  perform battle_spectator_private.actor_session(false);
  select p.data_processing_restricted_at is not null into held from public.profiles p where p.id=auth.uid() for share;
  if p_granted is distinct from false or not coalesce(held,false) then
    perform battle_spectator_private.actor_session();
  end if;
  if p_granted is null then raise exception 'spectator_media_invalid_consent';end if;
  -- Both setters use the same exclusive match lock, also serializing host/guest withdrawal.
  select * into m from public.battle_matches where id=p_match_id for update;
  perform battle_spectator_private.actor_session(false);
  if m.id is null or (auth.uid() is distinct from m.host_id and auth.uid() is distinct from m.guest_id)
     or m.status not in('waiting','ready','live') then
    raise exception 'spectator_media_player_only' using errcode='42501';end if;
  select * into c from battle_spectator_media_private.config where singleton;
  if p_granted then
    insert into battle_spectator_media_private.consents values(p_match_id,auth.uid(),c.consent_version,true,clock_timestamp())
      on conflict(match_id,user_id) do update set consent_version=excluded.consent_version,granted=true,updated_at=excluded.updated_at;
    return battle_spectator_media_private.sync_epoch(p_match_id);
  end if;
  update battle_spectator_media_private.consents set granted=false,consent_version=c.consent_version,updated_at=clock_timestamp()
    where match_id=p_match_id and user_id=auth.uid() and granted;
  changed:=found;
  select * into e from battle_spectator_media_private.epochs where match_id=p_match_id for update;
  if changed and e.media_open then
    perform battle_spectator_media_private.close_epoch(p_match_id,'player_withdrawal');
    -- close_epoch clears generation; retain the actual link generation before sync to avoid
    -- revoking a never-open intermediate epoch. The match lock protects the link generation.
    select generation into g from battle_spectator_private.links where match_id=p_match_id and enabled;
    update battle_spectator_media_private.epochs set generation=g where match_id=p_match_id;
    return battle_spectator_media_private.sync_epoch(p_match_id)||jsonb_build_object('withdrawn',true);
  end if;
  -- No sync for missing/closed/replayed state: it would create/rotate an unnecessary epoch.
  return jsonb_build_object('media_open',coalesce(e.media_open,false),'epoch',e.epoch,
    'max_viewers_per_match',c.max_viewers_per_match,'consent_version',c.consent_version,'withdrawn',changed);
end $function$

CREATE OR REPLACE FUNCTION public.set_marketplace_seller_onboarding_enforcement(p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_paused integer := 0;
begin perform public.require_duelvanta_privileged_session();
  if not dv_market_private.is_market_owner_caller() then
    raise exception 'owner_access_required';
  end if;

  update dv_market_private.marketplace_compliance_policy
  set seller_onboarding_enforced=coalesce(p_enabled,false),updated_by=v_actor,updated_at=now()
  where singleton=true;

  if coalesce(p_enabled,false) then
    update public.market_listings l
    set status='paused',updated_at=now()
    where l.status='active'
      and not exists (
        select 1 from public.market_seller_accounts a
        where a.seller_id=l.seller_id and a.onboarding_status='active'
          and a.seller_type in ('private','trader')
      );
    get diagnostics v_paused = row_count;
  end if;

  return jsonb_build_object('seller_onboarding_enforced',coalesce(p_enabled,false),'paused_listings',v_paused);
end
$function$

CREATE OR REPLACE FUNCTION public.set_my_public_profile(p_username text DEFAULT NULL::text, p_collection_visibility text DEFAULT NULL::text, p_avatar_path text DEFAULT NULL::text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_username text; v_old_username text; v_changed_at timestamptz; v_result public.profiles;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 select lower(username),username_changed_at into v_old_username,v_changed_at from public.profiles where id=v_uid for update;
 if not found then raise exception 'Profile not found'; end if;
 if p_username is not null then
  v_username:=lower(trim(p_username));
  if length(v_username)<3 or length(v_username)>30 or v_username !~ '^[a-z0-9][a-z0-9._-]*$' then raise exception 'Invalid username'; end if;
  if v_old_username is distinct from v_username then
   if v_old_username is not null and v_changed_at is not null and v_changed_at+interval '90 days'>now() then raise exception 'Username change locked until %',to_char(v_changed_at+interval '90 days','YYYY-MM-DD'); end if;
   if exists(select 1 from public.profiles p where p.username is not null and lower(p.username)=v_username and p.id<>v_uid) then raise exception 'Username already taken'; end if;
   if exists(select 1 from public.username_reservations r where r.username=v_username and r.reserved_until>now() and r.reserved_for<>v_uid) then raise exception 'Username temporarily reserved'; end if;
   if v_old_username is not null then insert into public.username_reservations(username,reserved_for,reserved_until) values(v_old_username,v_uid,now()+interval '90 days') on conflict(username) do update set reserved_for=excluded.reserved_for,reserved_until=excluded.reserved_until,created_at=now(); end if;
  end if;
 end if;
 perform set_config('duelvanta.username_rpc','allowed',true);
 update public.profiles p set username=case when p_username is null then p.username else v_username end,username_changed_at=case when p_username is not null and v_old_username is distinct from v_username then now() else p.username_changed_at end,collection_visibility=coalesce(p_collection_visibility,p.collection_visibility),avatar_path=case when p_avatar_path is null then p.avatar_path else p_avatar_path end,profile_updated_at=now() where p.id=v_uid returning p.* into v_result;
 perform set_config('duelvanta.username_rpc','',true);
 return v_result;
exception when unique_violation then raise exception 'Username already taken';
end;$function$

CREATE OR REPLACE FUNCTION public.set_staff_permission(p_user_id uuid, p_permission text, p_enabled boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 d3_targets:=array[p_user_id];
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((p_enabled is false and public.is_duelvanta_owner(auth.uid()) and d3_profile.role in ('admin','moderator','judge') and exists(select 1 from public.staff_permissions where user_id=p_user_id and permission=p_permission)),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();


declare v_uid uuid:=auth.uid(); v_target_role text;
begin perform public.require_duelvanta_privileged_session();
 if not public.is_duelvanta_owner(v_uid) then raise exception 'Owner required'; end if;
 if public.is_duelvanta_owner(p_user_id) then raise exception 'Owner permissions are immutable'; end if;
 select role into v_target_role from public.profiles where id=p_user_id;
 if v_target_role not in ('admin','moderator','judge') then raise exception 'Staff role required'; end if;
 if p_permission not in ('battle_moderate','reports_review','users_restrict','staff_review','tournaments_manage','broadcast_manage') then raise exception 'Invalid permission'; end if;
 if p_enabled then insert into public.staff_permissions(user_id,permission,granted_by) values(p_user_id,p_permission,v_uid) on conflict(user_id,permission) do update set granted_by=v_uid,granted_at=now(); else delete from public.staff_permissions where user_id=p_user_id and permission=p_permission; end if;
 insert into public.admin_audit_log(actor_id,target_user_id,action,details) values(v_uid,p_user_id,'permission_changed',jsonb_build_object('permission',p_permission,'enabled',p_enabled));
 return p_enabled;
end;
end
$function$

CREATE OR REPLACE FUNCTION public.set_staff_role(p_user_id uuid, p_role text, p_reason text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 d3_targets:=array[p_user_id];
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((p_role='player' and public.is_duelvanta_owner(auth.uid()) and d3_profile.role in ('admin','moderator','judge')),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();

  declare v_uid uuid:=auth.uid(); v_actor text; v_old text; begin perform public.require_duelvanta_privileged_session(); select role into v_actor from public.profiles where id=v_uid; select role into v_old from public.profiles where id=p_user_id for update; if v_old is null then raise exception 'User not found'; end if; if p_user_id=v_uid and v_old='owner' then raise exception 'Owner role cannot be self-modified'; end if; if p_role='owner' then raise exception 'Owner role cannot be assigned here'; end if; if p_role='admin' and not public.is_duelvanta_owner(v_uid) then raise exception 'Only owner can assign admins'; end if; if p_role in ('judge','moderator','player') and not public.is_duelvanta_owner(v_uid) then raise exception 'Owner approval required during beta'; end if; if p_role not in ('admin','moderator','judge','player') then raise exception 'Invalid role'; end if; if v_old='owner' then raise exception 'Owner role is protected'; end if; update public.profiles set role=p_role,updated_at=now() where id=p_user_id; insert into public.admin_audit_log(actor_id,target_user_id,action,details) values(v_uid,p_user_id,'role_changed',jsonb_build_object('from',v_old,'to',p_role,'reason',left(p_reason,1000))); return p_role; end;
end
$function$

CREATE OR REPLACE FUNCTION public.start_battle_match(p_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare v public.battle_matches; begin
 if auth.uid() is null then raise exception 'not_authenticated'; end if;
 -- Keep the existing actor/Safety boundary; serialize admission with Hold writes.
 perform 1 from public.profiles where id=auth.uid() for share;
 if not exists(select 1 from public.profiles where id=auth.uid() and account_status in ('beta','active') and not coalesce(safety_restricted,false)) then raise exception 'battle_account_unavailable'; end if;
 if exists(select 1 from public.profiles where id=auth.uid() and data_processing_restricted_at is not null) then
   raise exception 'account_data_processing_restricted' using errcode='42501';
 end if;
 select * into v from public.battle_matches where id=p_match_id for update; if v.id is null or v.host_id<>auth.uid() then raise exception 'Nur der Host kann starten'; end if; if v.moderation_state='paused' or v.paused_at is not null then raise exception 'Match ist durch die Moderation pausiert'; end if; if v.guest_id is null or not v.host_ready or not v.guest_ready then raise exception 'Beide Spieler müssen bereit sein'; end if; if v.status not in ('waiting','ready') then raise exception 'Match kann nicht gestartet werden'; end if; update public.battle_matches set status='live',started_at=now(),updated_at=now() where id=v.id; end $function$

CREATE OR REPLACE FUNCTION public.submit_market_review(p_deal_id uuid, p_rating text, p_comment text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.market_deals; reviewee uuid; rid uuid;
begin
 if p_rating not in ('positive','neutral','negative') then raise exception 'Ungültige Bewertung'; end if;
 select * into d from public.market_deals where id=p_deal_id;
 if d.id is null or d.status<>'completed' or auth.uid() not in (d.seller_id,d.buyer_id) then raise exception 'Bewertung nicht erlaubt'; end if;
 reviewee:=case when auth.uid()=d.seller_id then d.buyer_id else d.seller_id end;
 insert into public.market_reviews(deal_id,reviewer_id,reviewee_id,rating,comment)
 values(d.id,auth.uid(),reviewee,p_rating,nullif(left(trim(coalesce(p_comment,'')),500),'')) returning id into rid;
 return rid;
exception when unique_violation then raise exception 'Du hast diesen Deal bereits bewertet';
end $function$

CREATE OR REPLACE FUNCTION public.submit_marketplace_listing_notice(p_listing_id uuid, p_category text, p_explanation text, p_alleged_legal_basis text, p_reporter_name text, p_reporter_email text, p_exact_url text, p_good_faith_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_listing public.market_listings%rowtype;
  v_notice dv_market_private.listing_notices%rowtype;
  v_category text := lower(trim(coalesce(p_category,'')));
  v_name text := trim(coalesce(p_reporter_name,''));
  v_email text := lower(trim(coalesce(p_reporter_email,'')));
  v_explanation text := trim(coalesce(p_explanation,''));
  v_legal_basis text := nullif(trim(coalesce(p_alleged_legal_basis,'')), '');
  v_url text := trim(coalesce(p_exact_url,''));
  v_access_code text := upper(encode(gen_random_bytes(9),'hex'));
  v_reference text := 'DVN-' || to_char(current_date,'YYYYMMDD') || '-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
  v_recent integer;
begin
  if p_listing_id is null then raise exception 'listing_required'; end if;
  if v_category not in ('counterfeit','stolen_goods','consumer_deception','intellectual_property','prohibited_goods','privacy','harassment','other_illegal') then
    raise exception 'invalid_notice_category';
  end if;
  if char_length(v_name) not between 2 and 160 then raise exception 'reporter_name_invalid'; end if;
  if char_length(v_email) > 320 or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    raise exception 'reporter_email_invalid';
  end if;
  if char_length(v_explanation) not between 30 and 5000 then raise exception 'notice_explanation_invalid'; end if;
  if v_legal_basis is not null and char_length(v_legal_basis) > 1000 then raise exception 'notice_legal_basis_too_long'; end if;
  if char_length(v_url) > 1000 or v_url !~ '^https://([a-z0-9-]+[.])*duelvanta[.](de|com)/' then
    raise exception 'listing_url_invalid';
  end if;
  if coalesce(p_good_faith_confirmed,false) is not true then raise exception 'good_faith_confirmation_required'; end if;

  select * into v_listing from public.market_listings where id=p_listing_id;
  if not found then raise exception 'listing_not_found'; end if;

  select count(*) into v_recent
  from dv_market_private.listing_notices n
  where n.reporter_email_hash=digest(convert_to(v_email,'UTF8'),'sha256')
    and n.submitted_at > now()-interval '1 hour';
  if v_recent >= 5 then raise exception 'notice_rate_limit'; end if;

  insert into dv_market_private.listing_notices(
    case_reference,listing_id,listing_snapshot,reporter_user_id,reporter_name,reporter_email,
    reporter_email_hash,access_code_hash,category,explanation,alleged_legal_basis,exact_url,
    good_faith_confirmed,acknowledged_at
  ) values (
    v_reference,v_listing.id,to_jsonb(v_listing),auth.uid(),v_name,v_email,
    digest(convert_to(v_email,'UTF8'),'sha256'),digest(convert_to(v_access_code,'UTF8'),'sha256'),
    v_category,v_explanation,v_legal_basis,v_url,true,now()
  ) returning * into v_notice;

  insert into dv_market_private.listing_notice_events(notice_id,actor_id,event_type,event_data)
  values(v_notice.id,auth.uid(),'notice_submitted',jsonb_build_object('category',v_category,'listing_id',v_listing.id));

  insert into dv_market_private.marketplace_message_outbox(
    notice_id,recipient_kind,recipient_email,message_kind,payload
  ) values (
    v_notice.id,'reporter',v_email,'notice_received',
    jsonb_build_object('case_reference',v_reference,'received_at',v_notice.submitted_at)
  );

  return jsonb_build_object(
    'case_reference',v_reference,
    'access_code',v_access_code,
    'status','submitted',
    'received_at',v_notice.submitted_at
  );
end
$function$

CREATE OR REPLACE FUNCTION public.submit_marketplace_notice_appeal(p_case_reference text, p_access_code text, p_grounds text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare v_notice dv_market_private.listing_notices%rowtype; v_appeal dv_market_private.listing_notice_appeals%rowtype; v_grounds text:=trim(coalesce(p_grounds,''));
begin
  select * into v_notice from dv_market_private.listing_notices n
  where n.case_reference=upper(trim(coalesce(p_case_reference,'')))
    and n.access_code_hash=digest(convert_to(upper(trim(coalesce(p_access_code,''))),'UTF8'),'sha256')
  for update;
  if not found then raise exception 'notice_access_denied'; end if;
  if v_notice.decided_at is null then raise exception 'notice_not_decided'; end if;
  if v_notice.decided_at < now()-interval '6 months' then raise exception 'appeal_period_expired'; end if;
  if char_length(v_grounds) not between 30 and 5000 then raise exception 'appeal_grounds_invalid'; end if;
  if exists(select 1 from dv_market_private.listing_notice_appeals where notice_id=v_notice.id and appellant_kind='reporter' and status in ('submitted','under_review')) then
    raise exception 'appeal_already_open';
  end if;

  insert into dv_market_private.listing_notice_appeals(notice_id,appellant_kind,appellant_user_id,grounds)
  values(v_notice.id,'reporter',auth.uid(),v_grounds) returning * into v_appeal;
  update dv_market_private.listing_notices set status='appealed',updated_at=now() where id=v_notice.id;
  insert into dv_market_private.listing_notice_events(notice_id,actor_id,event_type,event_data)
  values(v_notice.id,auth.uid(),'reporter_appeal_submitted',jsonb_build_object('appeal_id',v_appeal.id));
  insert into dv_market_private.marketplace_message_outbox(notice_id,recipient_kind,recipient_email,message_kind,payload)
  values(v_notice.id,'reporter',v_notice.reporter_email,'appeal_received',jsonb_build_object('case_reference',v_notice.case_reference,'appeal_id',v_appeal.id));
  return jsonb_build_object('appeal_id',v_appeal.id,'status',v_appeal.status,'submitted_at',v_appeal.submitted_at);
end
$function$

CREATE OR REPLACE FUNCTION public.submit_my_market_seller_onboarding(p_accept_seller_terms boolean, p_confirm_data_accuracy boolean, p_confirm_lawful_goods boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_account public.market_seller_accounts%rowtype;
  v_legal dv_market_private.seller_legal_profiles%rowtype;
  v_terms_version text;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;
  if not coalesce(p_accept_seller_terms,false)
     or not coalesce(p_confirm_data_accuracy,false)
     or not coalesce(p_confirm_lawful_goods,false) then
    raise exception 'seller_declarations_required';
  end if;

  select * into v_account from public.market_seller_accounts where seller_id=v_uid;
  select * into v_legal from dv_market_private.seller_legal_profiles where seller_id=v_uid;
  select seller_terms_version into v_terms_version
  from dv_market_private.marketplace_compliance_policy where singleton=true;

  if v_account.seller_id is null or v_account.seller_type not in ('private','trader')
     or v_legal.seller_id is null then
    raise exception 'seller_onboarding_incomplete';
  end if;
  if v_account.onboarding_status = 'suspended' then
    raise exception 'seller_account_suspended';
  end if;
  if v_legal.legal_first_name is null or v_legal.legal_last_name is null
     or v_legal.date_of_birth is null or v_legal.street_line1 is null
     or v_legal.postal_code is null or v_legal.city is null
     or v_legal.country_code is null or v_legal.tax_residence_country_code is null then
    raise exception 'seller_onboarding_incomplete';
  end if;
  if v_account.seller_type='trader'
     and (v_legal.business_name is null or v_legal.legal_form is null
          or v_legal.public_email is null or v_legal.public_phone is null) then
    raise exception 'seller_onboarding_incomplete';
  end if;

  insert into dv_market_private.seller_declarations(seller_id,declaration_kind,document_version)
  values
    (v_uid,'seller_terms',v_terms_version),
    (v_uid,'data_accuracy',v_terms_version),
    (v_uid,'lawful_goods',v_terms_version)
  on conflict (seller_id,declaration_kind,document_version)
  do update set accepted_at=now(),withdrawn_at=null;

  update public.market_seller_accounts
  set onboarding_status='pending_review',
      terms_version=v_terms_version,
      terms_accepted_at=now(),
      submitted_at=now(),
      verified_at=null,
      updated_at=now()
  where seller_id=v_uid;

  return public.get_my_market_seller_onboarding();
end
$function$

CREATE OR REPLACE FUNCTION public.submit_my_marketplace_moderation_appeal(p_notice_id uuid, p_grounds text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_uid uuid:=auth.uid(); v_notice dv_market_private.listing_notices%rowtype; v_appeal dv_market_private.listing_notice_appeals%rowtype; v_grounds text:=trim(coalesce(p_grounds,''));
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_notice from dv_market_private.listing_notices n where n.id=p_notice_id and n.listing_snapshot->>'seller_id'=v_uid::text for update;
  if not found then raise exception 'moderation_case_access_denied'; end if;
  if v_notice.decided_at is null then raise exception 'notice_not_decided'; end if;
  if v_notice.decided_at < now()-interval '6 months' then raise exception 'appeal_period_expired'; end if;
  if char_length(v_grounds) not between 30 and 5000 then raise exception 'appeal_grounds_invalid'; end if;
  if exists(select 1 from dv_market_private.listing_notice_appeals where notice_id=v_notice.id and appellant_kind='seller' and status in ('submitted','under_review')) then raise exception 'appeal_already_open'; end if;
  insert into dv_market_private.listing_notice_appeals(notice_id,appellant_kind,appellant_user_id,grounds)
  values(v_notice.id,'seller',v_uid,v_grounds) returning * into v_appeal;
  update dv_market_private.listing_notices set status='appealed',updated_at=now() where id=v_notice.id;
  insert into dv_market_private.listing_notice_events(notice_id,actor_id,event_type,event_data)
  values(v_notice.id,v_uid,'seller_appeal_submitted',jsonb_build_object('appeal_id',v_appeal.id));
  insert into dv_market_private.marketplace_message_outbox(notice_id,recipient_kind,recipient_user_id,message_kind,payload)
  values(v_notice.id,'seller',v_uid,'appeal_received',jsonb_build_object('case_reference',v_notice.case_reference,'appeal_id',v_appeal.id));
  return jsonb_build_object('appeal_id',v_appeal.id,'status',v_appeal.status,'submitted_at',v_appeal.submitted_at);
end
$function$

