CREATE OR REPLACE FUNCTION public.upsert_my_default_shipping_address(p_recipient_name text, p_street_line1 text, p_postal_code text, p_city text, p_country_code text, p_street_line2 text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_country text:=upper(trim(coalesce(p_country_code,'')));
begin
  if v_uid is null then raise exception 'Nicht angemeldet'; end if;
  if nullif(trim(coalesce(p_recipient_name,'')),'') is null or nullif(trim(coalesce(p_street_line1,'')),'') is null or nullif(trim(coalesce(p_postal_code,'')),'') is null or nullif(trim(coalesce(p_city,'')),'') is null then raise exception 'Bitte vollständige Lieferadresse angeben'; end if;
  if v_country not in ('DE','AT','CH') then raise exception 'Lieferland derzeit nicht unterstützt'; end if;
  insert into public.market_default_shipping_addresses(user_id,recipient_name,street_line1,street_line2,postal_code,city,country_code)
  values(v_uid,left(trim(p_recipient_name),120),left(trim(p_street_line1),160),nullif(left(trim(coalesce(p_street_line2,'')),160),''),left(trim(p_postal_code),20),left(trim(p_city),120),v_country)
  on conflict(user_id) do update set recipient_name=excluded.recipient_name,street_line1=excluded.street_line1,street_line2=excluded.street_line2,postal_code=excluded.postal_code,city=excluded.city,country_code=excluded.country_code,updated_at=now();
end; $function$

CREATE OR REPLACE FUNCTION public.upsert_my_market_order_shipping_address(p_order_id uuid, p_recipient_name text, p_street_line1 text, p_postal_code text, p_city text, p_country_code text, p_street_line2 text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.market_orders; v_country text:=upper(trim(coalesce(p_country_code,'')));
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if; select * into o from public.market_orders where id=p_order_id for update;
  if o.id is null or auth.uid()<>o.buyer_id then raise exception 'Nur der Käufer kann die Lieferadresse speichern'; end if;
  if o.fulfillment_group='pickup' then raise exception 'Bei Abholung ist keine Lieferadresse nötig'; end if;
  if o.shipped_at is not null or o.status in ('completed','cancelled') then raise exception 'Lieferadresse ist gesperrt'; end if;
  if nullif(trim(coalesce(p_recipient_name,'')),'') is null or nullif(trim(coalesce(p_street_line1,'')),'') is null or nullif(trim(coalesce(p_postal_code,'')),'') is null or nullif(trim(coalesce(p_city,'')),'') is null then raise exception 'Bitte vollständige Lieferadresse angeben'; end if;
  if v_country not in ('DE','AT','CH') then raise exception 'Lieferland derzeit nicht unterstützt'; end if;
  insert into public.market_order_shipping_addresses(order_id,buyer_id,recipient_name,street_line1,street_line2,postal_code,city,country_code)
  values(o.id,o.buyer_id,left(trim(p_recipient_name),120),left(trim(p_street_line1),160),nullif(left(trim(coalesce(p_street_line2,'')),160),''),left(trim(p_postal_code),20),left(trim(p_city),120),v_country)
  on conflict(order_id) do update set recipient_name=excluded.recipient_name,street_line1=excluded.street_line1,street_line2=excluded.street_line2,postal_code=excluded.postal_code,city=excluded.city,country_code=excluded.country_code,updated_at=now();
end; $function$

CREATE OR REPLACE FUNCTION public.upsert_my_market_shipping_address(p_deal_id uuid, p_recipient_name text, p_street_line1 text, p_postal_code text, p_city text, p_country_code text DEFAULT 'DE'::text, p_street_line2 text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.market_deals; v_name text:=trim(coalesce(p_recipient_name,'')); v_street1 text:=trim(coalesce(p_street_line1,'')); v_street2 text:=nullif(trim(coalesce(p_street_line2,'')),''); v_postal text:=trim(coalesce(p_postal_code,'')); v_city text:=trim(coalesce(p_city,'')); v_country text:=upper(trim(coalesce(p_country_code,'DE')));
begin
 select * into d from public.market_deals where id=p_deal_id for update;
 if d.id is null then raise exception 'Deal nicht gefunden'; end if;
 if auth.uid() is null or auth.uid()<>d.buyer_id then raise exception 'Nur der Käufer kann die Lieferadresse hinterlegen'; end if;
 if d.order_id is not null then raise exception 'Dieser Deal ist Teil einer DUELVANTA Order. Lieferadresse bitte einmalig unter ORDERS hinterlegen.'; end if;
 if d.status not in ('accepted','in_progress') then raise exception 'Lieferadresse kann in diesem Deal-Status nicht geändert werden'; end if;
 if d.fulfillment_status in ('shipped','received') or d.shipped_at is not null then raise exception 'Adresse ist nach Versand gesperrt'; end if;
 if char_length(v_name) not between 2 and 120 then raise exception 'Empfängername ist ungültig'; end if;
 if char_length(v_street1) not between 2 and 160 then raise exception 'Straße / Hausnummer ist ungültig'; end if;
 if v_street2 is not null and char_length(v_street2)>160 then raise exception 'Adresszusatz ist zu lang'; end if;
 if char_length(v_postal) not between 2 and 20 then raise exception 'Postleitzahl ist ungültig'; end if;
 if char_length(v_city) not between 2 and 120 then raise exception 'Ort ist ungültig'; end if;
 if v_country !~ '^[A-Z]{2}$' then raise exception 'Ländercode ist ungültig'; end if;
 insert into public.market_deal_shipping_addresses(deal_id,buyer_id,recipient_name,street_line1,street_line2,postal_code,city,country_code,created_at,updated_at)
 values(d.id,d.buyer_id,v_name,v_street1,v_street2,v_postal,v_city,v_country,now(),now())
 on conflict(deal_id) do update set buyer_id=excluded.buyer_id,recipient_name=excluded.recipient_name,street_line1=excluded.street_line1,street_line2=excluded.street_line2,postal_code=excluded.postal_code,city=excluded.city,country_code=excluded.country_code,updated_at=now();
end $function$

CREATE OR REPLACE FUNCTION public.upsert_my_market_shipping_profile(p_profile_id uuid, p_name text, p_destination_country_code text, p_shipping_method text, p_carrier_label text, p_product_scope text, p_is_active boolean, p_rules jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_id uuid; v_country text:=upper(trim(coalesce(p_destination_country_code,''))); v_rule jsonb; v_pos integer:=0; v_units integer; v_weight integer; v_l integer; v_w integer; v_h integer; v_cost numeric;
begin
  if v_uid is null then raise exception 'Nicht angemeldet'; end if;
  if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Bitte Profilname angeben'; end if;
  if v_country not in ('DE','AT','CH') then raise exception 'Ungültiges Zielland'; end if;
  if p_shipping_method not in ('standard_letter','tracked_letter','parcel','custom') then raise exception 'Ungültige Versandart'; end if;
  if p_product_scope not in ('all','cards','sealed') then raise exception 'Ungültiger Produktbereich'; end if;
  if p_shipping_method='custom' and nullif(trim(coalesce(p_carrier_label,'')),'') is null then raise exception 'Individuelle Versandart bitte benennen'; end if;
  if p_rules is null or jsonb_typeof(p_rules)<>'array' or jsonb_array_length(p_rules) not between 1 and 10 then raise exception 'Bitte 1 bis 10 Tarifregeln anlegen'; end if;
  if p_profile_id is null then
    insert into public.market_shipping_profiles(seller_id,name,destination_country_code,shipping_method,carrier_label,product_scope,is_active)
    values(v_uid,left(trim(p_name),80),v_country,p_shipping_method,nullif(left(trim(coalesce(p_carrier_label,'')),80),''),p_product_scope,coalesce(p_is_active,true)) returning id into v_id;
  else
    select id into v_id from public.market_shipping_profiles where id=p_profile_id and seller_id=v_uid for update;
    if v_id is null then raise exception 'Versandprofil nicht gefunden'; end if;
    update public.market_shipping_profiles set name=left(trim(p_name),80),destination_country_code=v_country,shipping_method=p_shipping_method,carrier_label=nullif(left(trim(coalesce(p_carrier_label,'')),80),''),product_scope=p_product_scope,is_active=coalesce(p_is_active,true),updated_at=now() where id=v_id;
    delete from public.market_shipping_profile_rules where profile_id=v_id;
  end if;
  for v_rule in select value from jsonb_array_elements(p_rules) loop
    v_pos:=v_pos+1;
    begin v_units:=nullif(v_rule->>'max_units','')::integer; v_weight:=nullif(v_rule->>'max_weight_grams','')::integer; v_l:=nullif(v_rule->>'max_length_mm','')::integer; v_w:=nullif(v_rule->>'max_width_mm','')::integer; v_h:=nullif(v_rule->>'max_height_mm','')::integer; v_cost:=(v_rule->>'shipping_cost')::numeric; exception when others then raise exception 'Ungültige Tarifregel %',v_pos; end;
    if v_units is null and v_weight is null then raise exception 'Tarifregel % braucht Maximalmenge oder Maximalgewicht',v_pos; end if;
    if v_units is not null and v_units not between 1 and 1000 then raise exception 'Ungültige Maximalmenge in Regel %',v_pos; end if;
    if v_weight is not null and v_weight not between 1 and 100000 then raise exception 'Ungültiges Maximalgewicht in Regel %',v_pos; end if;
    if v_l is not null and v_l not between 1 and 2000 then raise exception 'Ungültige Länge in Regel %',v_pos; end if;
    if v_w is not null and v_w not between 1 and 2000 then raise exception 'Ungültige Breite in Regel %',v_pos; end if;
    if v_h is not null and v_h not between 1 and 2000 then raise exception 'Ungültige Höhe in Regel %',v_pos; end if;
    if v_cost is null or v_cost<0 or v_cost>500 then raise exception 'Ungültige Versandkosten in Regel %',v_pos; end if;
    insert into public.market_shipping_profile_rules(profile_id,sort_order,max_units,max_weight_grams,max_length_mm,max_width_mm,max_height_mm,shipping_cost) values(v_id,v_pos,v_units,v_weight,v_l,v_w,v_h,round(v_cost,2));
  end loop; return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.validate_market_shipping_profile_rule()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_scope text;
begin
  select p.product_scope into v_scope from public.market_shipping_profiles p where p.id=new.profile_id;
  if v_scope is null then raise exception 'Versandprofil nicht gefunden'; end if;
  if v_scope in ('all','sealed') and (new.max_units is null or new.max_weight_grams is null) then raise exception 'Für Sealed oder Alle Produkte braucht jede Tarifregel Max. Produkte und Max. Gewicht'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_market_order_cancellation(p_case_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.market_order_cases;o public.market_orders;v_other uuid;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into c from public.market_order_cases where id=p_case_id and case_type='cancellation' for update;
  if c.id is null or c.status<>'open' or c.opened_by<>auth.uid() then raise exception 'Stornoanfrage kann nicht zurückgezogen werden'; end if;
  select * into o from public.market_orders where id=c.order_id;
  v_other:=case when c.opened_by=o.seller_id then o.buyer_id else o.seller_id end;
  update public.market_order_cases set status='withdrawn',responded_by=auth.uid(),responded_at=now(),updated_at=now() where id=c.id;
  insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
  values(v_other,'cancellation_withdrawn','STORNOANFRAGE ZURÜCKGEZOGEN',o.order_number,o.id,'cancel_withdrawn:'||c.id::text)
  on conflict(dedupe_key) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_market_order_problem(p_case_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.market_order_cases;o public.market_orders;v_other uuid;v_note text:=nullif(left(trim(coalesce(p_note,'')),800),'');
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into c from public.market_order_cases where id=p_case_id and case_type='problem' for update;
  if c.id is null or c.status<>'open' or c.opened_by<>auth.uid() then raise exception 'Problem kann nicht zurückgezogen werden'; end if;
  select * into o from public.market_orders where id=c.order_id for update;
  if o.id is null or o.status<>'disputed' or o.shipped_at is null then raise exception 'Orderstatus hat sich geändert'; end if;
  v_other:=case when c.opened_by=o.seller_id then o.buyer_id else o.seller_id end;
  update public.market_order_cases set status='withdrawn',response_note=v_note,responded_by=auth.uid(),responded_at=now(),updated_at=now() where id=c.id;
  update public.market_orders set status='shipped',disputed_at=null,disputed_by=null,dispute_reason=null,
    refund_status=case when refund_status='provider_required' then 'not_required' else refund_status end,
    refund_amount=case when refund_status='provider_required' then null else refund_amount end,updated_at=now() where id=o.id;
  update public.market_deals set status='in_progress',disputed_at=null,disputed_by=null,dispute_reason=null,
    payout_status=case when payout_status='blocked' then 'pending' else payout_status end,updated_at=now()
    where order_id=o.id and status='disputed';
  insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
  values(v_other,'problem_withdrawn','PROBLEMFALL ZURÜCKGEZOGEN',o.order_number,o.id,'problem_withdrawn:'||c.id::text)
  on conflict(dedupe_key) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_market_swap_problem_v1(p_case_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_case dv_market_private.market_swap_cases%rowtype;
  v_thread dv_market_private.market_swap_threads%rowtype;
  v_note text:=nullif(left(trim(coalesce(p_note,'')),1200),'');
  v_now timestamptz:=now();
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
  select * into v_case from dv_market_private.market_swap_cases where id=p_case_id for update;
  if not found or v_case.status<>'open' or v_case.opened_by<>v_uid then raise exception 'swap_problem_withdraw_not_allowed';end if;
  select * into v_thread from dv_market_private.market_swap_threads where id=v_case.thread_id for update;
  update dv_market_private.market_swap_cases set status='withdrawn',resolution_note=v_note,resolved_at=v_now,updated_at=v_now where id=v_case.id;
  if v_thread.status='disputed' and not exists(select 1 from dv_market_private.market_swap_cases c where c.thread_id=v_thread.id and c.status='open') then
    update dv_market_private.market_swap_threads set status='bound',updated_at=v_now where id=v_thread.id;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.withdraw_my_account_deletion(p_request_id uuid, p_challenge_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s uuid;r dv_market_private.account_deletion_requests%rowtype;w dv_market_private.c_withdrawal_receipts%rowtype;begin
 s:=dv_market_private.c_session();
 if not exists(select 1 from dv_market_private.c_withdrawal_challenges c join auth.sessions a on a.id=s
 where c.id=p_challenge_id and c.request_id=p_request_id and c.user_id=auth.uid()
 and c.session_id<>a.id and a.created_at>c.issued_at) then raise exception 'c_renewed_auth_required' using errcode='42501';end if;
 -- All C/B1 writers lock/touch this row first. Old RR snapshots serialize/fail.
 perform 1 from public.profiles where id=auth.uid() for no key update;
 if not found then raise exception 'c_profile_missing';end if;
 select * into r from dv_market_private.account_deletion_requests where id=p_request_id and user_id=auth.uid() for update;
 if not found then raise exception 'c_request_not_owned' using errcode='42501';end if;
 select * into w from dv_market_private.c_withdrawal_receipts where request_id=r.id and user_id=auth.uid();
 if found then return jsonb_build_object('request_id',r.id,'receipt_id',w.id,'withdrawn',true,'replayed',true);end if;
 if r.status not in ('requested','processing','failed') or not exists(
 select 1 from dv_market_private.c_request_origins o join dv_market_private.c_marker_owner m on m.request_id=o.request_id and m.user_id=o.user_id
 where o.request_id=r.id and o.user_id=auth.uid() and o.marker_clearable) then raise exception 'c_provenance_unresolved';end if;
 if exists(select 1 from dv_market_private.account_deletion_requests x where x.user_id=auth.uid() and x.id<>r.id
 and not exists(select 1 from dv_market_private.c_withdrawal_receipts q where q.request_id=x.id and q.user_id=x.user_id and x.status='cancelled'))
 or exists(select 1 from dv_market_private.c_prepare_entries e join dv_market_private.c_attempts a on a.id=e.attempt_id
 join dv_market_private.account_deletion_requests x on x.id=a.request_id where x.user_id=auth.uid()) then
 raise exception 'c_prepare_or_history_unresolved';end if;
 insert into dv_market_private.c_withdrawal_receipts(request_id,user_id,challenge_id,session_id)
 values(r.id,auth.uid(),p_challenge_id,s) returning * into w;
 update dv_market_private.account_deletion_requests set status='cancelled',lock_token=null,locked_at=null where id=r.id;
 -- Exact C ownership proved above. No other column or external state reset.
 update public.profiles set data_processing_restricted_at=null,account_closure_requested_at=null,
 safety_restricted=dv_market_private.b1_has_cause(auth.uid()),updated_at=now() where id=auth.uid();
 insert into dv_market_private.account_data_rights_audit(user_id,request_id,event_type,event_data)
 values(auth.uid(),r.id,'deletion_withdrawn',jsonb_build_object('receipt_id',w.id,'challenge_id',p_challenge_id));
 return jsonb_build_object('request_id',r.id,'receipt_id',w.id,'withdrawn',true,'replayed',false);
end $function$

