CREATE OR REPLACE FUNCTION battle_spectator_media_private.close_epoch_for_processing_hold(p_match uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e battle_spectator_media_private.epochs%rowtype;
begin
  select * into e from battle_spectator_media_private.epochs where match_id=p_match for update;
  if found and e.media_open then
    insert into battle_spectator_media_private.revocations(match_id,epoch,reason)
      values(p_match,e.epoch,'processing_hold') on conflict do nothing;
    update battle_spectator_media_private.epochs set media_open=false,updated_at=clock_timestamp()
      where match_id=p_match;
  end if;
end $function$

CREATE OR REPLACE FUNCTION battle_spectator_media_private.sync_epoch(p_match uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.battle_matches%rowtype;c battle_spectator_media_private.config%rowtype;
  g uuid;o boolean;e battle_spectator_media_private.epochs%rowtype;
begin
  -- Consistent lock order with Hold and D1: match, then epoch. Never lock peer profiles here.
  select * into m from public.battle_matches where id=p_match for update;
  if not found then raise exception 'spectator_media_unavailable' using errcode='42501';end if;
  select * into c from battle_spectator_media_private.config where singleton;
  if exists(select 1 from public.profiles p where p.id in(m.host_id,m.guest_id) and p.data_processing_restricted_at is not null) then
    perform battle_spectator_media_private.close_epoch_for_processing_hold(p_match);
    select * into e from battle_spectator_media_private.epochs where match_id=p_match;
    return jsonb_build_object('media_open',false,'epoch',e.epoch,
      'max_viewers_per_match',c.max_viewers_per_match,'consent_version',c.consent_version);
  end if;
  select generation into g from battle_spectator_private.links where match_id=p_match and enabled;
  o:=c.media_enabled and m.guest_id is not null and m.status in('waiting','ready','live')
    and m.moderation_state is distinct from 'paused' and m.paused_at is null
    and exists(select 1 from battle_spectator_media_private.consents x where x.match_id=p_match and x.user_id=m.host_id and x.granted and x.consent_version=c.consent_version)
    and exists(select 1 from battle_spectator_media_private.consents x where x.match_id=p_match and x.user_id=m.guest_id and x.granted and x.consent_version=c.consent_version)
    and (m.visibility='public' or g is not null);
  select * into e from battle_spectator_media_private.epochs where match_id=p_match for update;
  if not found then
    insert into battle_spectator_media_private.epochs(match_id,generation,media_open) values(p_match,g,o) returning * into e;
  elsif exists(select 1 from battle_spectator_media_private.revocations r where r.match_id=p_match and r.epoch=e.epoch and r.reason='processing_hold') then
    -- Defensive reuse boundary only: no unhold endpoint is introduced. Normal eligibility above
    -- must already be restored by an existing trusted path before a new open epoch is possible.
    if o then
      update battle_spectator_media_private.epochs set epoch=gen_random_uuid(),generation=g,media_open=true,updated_at=clock_timestamp()
        where match_id=p_match returning * into e;
    end if;
  elsif e.generation is distinct from g or(e.media_open and not o) then
    perform battle_spectator_media_private.close_epoch(p_match,case when e.generation is distinct from g then 'generation_changed' else 'media_closed' end);
    update battle_spectator_media_private.epochs set generation=g,media_open=o where match_id=p_match returning * into e;
  elsif e.media_open is distinct from o then
    update battle_spectator_media_private.epochs set media_open=o where match_id=p_match returning * into e;
  end if;
  return jsonb_build_object('media_open',e.media_open,'epoch',e.epoch,
    'max_viewers_per_match',c.max_viewers_per_match,'consent_version',c.consent_version);
end $function$

CREATE OR REPLACE FUNCTION battle_spectator_private.actor_session(p_require_eligible boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_sid uuid;
begin
  if v_uid is null or coalesce(auth.jwt()->>'role','') <> 'authenticated'
     or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then
    raise exception 'spectator_not_authenticated' using errcode='42501';
  end if;
  begin v_sid := nullif(auth.jwt()->>'session_id','')::uuid;
  exception when invalid_text_representation then
    raise exception 'spectator_session_unavailable' using errcode='42501'; end;
  if not exists (select 1 from auth.sessions s where s.id=v_sid and s.user_id=v_uid
    and (s.not_after is null or s.not_after>clock_timestamp())) then
    raise exception 'spectator_session_unavailable' using errcode='42501';
  end if;
  if p_require_eligible and not battle_spectator_private.eligible(v_uid) then
    raise exception 'spectator_battle_access_required' using errcode='42501';
  end if;
  return v_sid;
end $function$

CREATE OR REPLACE FUNCTION dv_collect_private.delete_empty_binder(p_folder_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if exists (select 1 from public.profiles where id = v_user
             and data_processing_restricted_at is not null) then
    raise exception using errcode = '42501', message = 'account_data_processing_restricted';
  end if;

  -- FOR UPDATE conflicts with the FK KEY SHARE lock acquired by inserts and
  -- assignments. Separate statements give READ COMMITTED a fresh snapshot
  -- after a preceding writer commits. Never replace with FOR NO KEY UPDATE.
  perform 1 from public.collection_folders
    where id = p_folder_id and user_id = v_user for update;
  if not found then
    -- Identical response for a foreign, missing or already deleted binder.
    return pg_catalog.jsonb_build_object('status', 'unavailable');
  end if;
  -- Deliberately all references, not just rows visible to the caller via RLS.
  if exists (select 1 from public.collection_items where folder_id = p_folder_id) then
    raise exception using errcode = 'P0001', message = 'binder_not_empty';
  end if;
  delete from public.collection_folders where id = p_folder_id and user_id = v_user;
  -- Existing account-restriction trigger still runs on this DELETE.
  return pg_catalog.jsonb_build_object('status', 'deleted');
end;
$function$

CREATE OR REPLACE FUNCTION dv_collect_private.magic_admission_operator_v1(p_request_id uuid, p_user_id uuid, p_authorized_users uuid[], p_action text, p_starts_at timestamp with time zone, p_expires_at timestamp with time zone, p_contract text, p_operator_ref text, p_expected_state text DEFAULT NULL::text, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare old_state jsonb;state_hash text;request_hash text;receipt record;
begin
 if current_user<>'postgres' or p_request_id is null or p_user_id is null or p_dry_run is null
 or not coalesce(p_user_id=any(p_authorized_users),false) or p_action is null or p_action not in ('admit','revoke')
 or p_contract is distinct from 'magic-on-demand-collect-beta/1' or p_operator_ref is null
 or length(btrim(p_operator_ref)) not between 1 and 256 or p_starts_at is null or p_expires_at is null
 or not isfinite(p_starts_at) or not isfinite(p_expires_at) or p_expires_at<=p_starts_at
 then raise exception 'operator_request_invalid' using errcode='42501';end if;
 request_hash:=encode(sha256(convert_to(jsonb_build_array(p_user_id,p_action,p_starts_at,p_expires_at,p_contract,p_operator_ref)::text,'UTF8')),'hex');
 if not p_dry_run then perform 1 from public.profiles where id=p_user_id for update;end if;
 select * into receipt from dv_collect_private.magic_operator_receipts_v1 where request_id=p_request_id;
 if found then
  if receipt.request_sha256<>request_hash then raise exception 'operator_request_conflict';end if;
  return jsonb_build_object('status','already_committed','request_id',p_request_id,'mutation',false);
 end if;
 if not exists(select 1 from auth.users where id=p_user_id and email_confirmed_at is not null)
 or not exists(select 1 from public.profiles where id=p_user_id) then raise exception 'operator_subject_invalid';end if;
 select to_jsonb(m) into old_state from dv_collect_private.magic_collect_admission_v1 m where user_id=p_user_id;
 state_hash:=encode(sha256(convert_to(coalesce(old_state,'null'::jsonb)::text,'UTF8')),'hex');
 if p_action='admit' then
  if p_expires_at<=clock_timestamp() or not exists(select 1 from public.profiles where id=p_user_id and data_processing_restricted_at is null and account_closure_requested_at is null and account_status not in ('suspended','deleted')) then raise exception 'operator_subject_ineligible';end if;
  if old_state is not null and old_state->>'status'='active' then raise exception 'operator_admission_conflict';end if;
 elsif old_state is null then raise exception 'operator_admission_absent';end if;
 if p_dry_run then return jsonb_build_object('status','validated','expected_state',state_hash,'request_id',p_request_id,'mutation',false);end if;
 if p_expected_state is distinct from state_hash then raise exception 'operator_state_changed';end if;
 if p_action='admit' then
  insert into dv_collect_private.magic_collect_admission_v1(user_id,status,starts_at,expires_at,operator_authorization_ref)
  values(p_user_id,'active',p_starts_at,p_expires_at,p_operator_ref)
  on conflict(user_id) do update set status='active',starts_at=excluded.starts_at,expires_at=excluded.expires_at,revoked_at=null,operator_authorization_ref=excluded.operator_authorization_ref;
 else update dv_collect_private.magic_collect_admission_v1 set status='revoked',revoked_at=coalesce(revoked_at,clock_timestamp()),operator_authorization_ref=p_operator_ref where user_id=p_user_id;end if;
 insert into dv_collect_private.magic_operator_receipts_v1(request_id,request_sha256,operator_ref,subject_hash,action)
 values(p_request_id,request_hash,p_operator_ref,encode(sha256(convert_to(p_user_id::text,'UTF8')),'hex'),p_action);
 return jsonb_build_object('status','committed','request_id',p_request_id,'mutation',true);
end$function$

CREATE OR REPLACE FUNCTION dv_collect_private.magic_collect_admitted_v1(p_lock boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare u uuid:=auth.uid();m dv_collect_private.magic_collect_admission_v1%rowtype;
begin
 if u is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false)
 or not exists(select 1 from auth.users where id=u and email_confirmed_at is not null)
 then return false;end if;
 if p_lock then
  select * into m from dv_collect_private.magic_collect_admission_v1 where user_id=u for share;
 else select * into m from dv_collect_private.magic_collect_admission_v1 where user_id=u;end if;
 return coalesce(m.status='active' and m.revoked_at is null and m.game_key='magic' and m.scope='collect'
 and m.contract='magic-on-demand-collect-beta/1' and m.starts_at<=clock_timestamp() and m.expires_at>clock_timestamp(),false);
end$function$

CREATE OR REPLACE FUNCTION dv_collect_private.tcg_clear_stale_link_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
begin
 if tg_table_name='collection_items' then
  if (old.tcg,old.user_id,old.card_name,old.set_name,old.card_number,old.language,old.variant)
   is distinct from (new.tcg,new.user_id,new.card_name,new.set_name,new.card_number,new.language,new.variant) then
   delete from dv_collect_private.collection_item_catalog_links where collection_item_id=old.id;
  end if;
 else
  if (old.tcg,old.seller_id,old.card_name,old.set_name,old.card_number,old.language,old.variant)
   is distinct from (new.tcg,new.seller_id,new.card_name,new.set_name,new.card_number,new.language,new.variant) then
   delete from dv_collect_private.listing_catalog_links where listing_id=old.id;
  end if;
 end if;return new;
end $function$

CREATE OR REPLACE FUNCTION dv_collect_private.tcg_publish_catalog_snapshot_v1(p_snapshot_id uuid, p_expected_generation bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare h record;rel dv_collect_private.tcg_catalog_releases%rowtype;old_snapshot dv_collect_private.tcg_catalog_snapshots%rowtype;
 t record;q record;rr record;pr dv_collect_private.tcg_provider_refs%rowtype;prev uuid;target uuid;ref uuid;ev uuid;der uuid;refev uuid;
 lang text;loc text;display text;raw jsonb;expected jsonb;actual jsonb;tab text;parts text[];cols text[];types text[];
begin
 if p_snapshot_id is null or p_expected_generation is null or p_expected_generation<0 then raise exception 'catalog_publish_input';end if;
 -- Exact attributes, fixed owner and namespace; constraints are checked below.
 for tab,cols,types in select * from (values
 ('tcg_catalog_stage_header',array['id','game_key','provider_key','provider_version','bulk_id','bulk_type','bulk_updated_at','download_uri','format','compressed_size','compressed_sha256','jsonl_sha256','sets_response_sha256','manifest_sha256','raw_manifest','scope_contract','scope_sha256','retrieved_at','record_count','accepted_cards','accepted_variants','accepted_sets','sealed_at'],array['uuid','text','text','text','uuid','text','timestamp with time zone','text','text','bigint','text','text','text','text','jsonb','text','text','timestamp with time zone','bigint','bigint','bigint','bigint','timestamp with time zone']),
 ('tcg_catalog_stage_sets',array['external_id','name','record_version'],array['uuid','text','text']),
 ('tcg_catalog_stage_cards',array['external_id','set_external_id','provider_lang','language_code','locale','collector_number','name','rarity','record_version'],array['uuid','uuid','text','text','text','text','text','text','text']),
 ('tcg_catalog_stage_variants',array['card_external_id','locale','finish','artwork','treatment','edition','validated_evidence','evidence_sha256','reference_external_id','reference_record_version'],array['uuid','text','text','text','text','text','jsonb','text','uuid','text']),
 ('tcg_catalog_stage_records',array['entity_kind','external_id','locale','raw_record','canonical_utf8','content_sha256','record_version','source_path','retrieved_at'],array['text','uuid','text','jsonb','bytea','text','text','text','timestamp with time zone'])
 ) x(tab,cols,types) loop
  if not exists(select 1 from pg_class c where c.relnamespace=pg_my_temp_schema() and c.relname=tab and c.relkind='r' and c.relpersistence='t' and c.relowner=(select oid from pg_roles where rolname='postgres')
   and not exists(select 1 from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where a.grantee<>c.relowner)) then raise exception 'catalog_stage_owner_or_shape';end if;
  select array_agg(a.attname::text order by a.attnum),to_jsonb(array_agg(format_type(a.atttypid,a.atttypmod) order by a.attnum)) into parts,actual
  from pg_attribute a join pg_class c on c.oid=a.attrelid where c.relnamespace=pg_my_temp_schema() and c.relname=tab and a.attnum>0 and not a.attisdropped;
  -- Use separately typed arrays for the comparison.
  if parts is distinct from cols or actual is distinct from to_jsonb(types) then raise exception 'catalog_stage_columns';end if;
 end loop;
 if not exists(select 1 from pg_constraint where conrelid='pg_temp.tcg_catalog_stage_sets'::regclass and contype='p' and conkey=array[1]::smallint[])
 or not exists(select 1 from pg_constraint where conrelid='pg_temp.tcg_catalog_stage_cards'::regclass and contype='p' and conkey=array[1]::smallint[])
 or not exists(select 1 from pg_constraint where conrelid='pg_temp.tcg_catalog_stage_cards'::regclass and contype='f' and confrelid='pg_temp.tcg_catalog_stage_sets'::regclass and conkey=array[2]::smallint[])
 or not exists(select 1 from pg_constraint where conrelid='pg_temp.tcg_catalog_stage_variants'::regclass and contype='p' and conkey=array[1,2,3]::smallint[])
 or (select count(*) from pg_constraint where conrelid='pg_temp.tcg_catalog_stage_variants'::regclass and contype='f' and confrelid='pg_temp.tcg_catalog_stage_cards'::regclass and conkey in (array[1]::smallint[],array[9]::smallint[]))<>2
 or not exists(select 1 from pg_index where indrelid='pg_temp.tcg_catalog_stage_records'::regclass and indisunique and indnullsnotdistinct and indkey::text='0 1 2 3'::text) and not exists(select 1 from pg_index where indrelid='pg_temp.tcg_catalog_stage_records'::regclass and indisunique and indnullsnotdistinct and indkey::text='1 2 3') then raise exception 'catalog_stage_keys';end if;
 if (select count(*) from pg_temp.tcg_catalog_stage_header)<>1 then raise exception 'catalog_stage_header';end if;
 select * into strict h from pg_temp.tcg_catalog_stage_header;
 if h.id is distinct from p_snapshot_id or (h.game_key,h.provider_key,h.provider_version,h.bulk_type,h.format,h.scope_contract,h.scope_sha256)
 is distinct from ('magic','scryfall','1','all_cards','gzip_jsonl','magic-collect-catalog-v1','a53ed167751e6ac3bf288864f7991f2b70bc486ec53cb5b9d5e7f7f7440d5aaa') or h.sealed_at is not null then raise exception 'catalog_stage_binding';end if;
 perform pg_advisory_xact_lock(hashtextextended('magic/scryfall/1',0));
 select * into strict rel from dv_collect_private.tcg_catalog_releases where (game_key,provider_key,provider_version)=('magic','scryfall','1') for update;
 if rel.release_generation<>p_expected_generation then raise exception 'catalog_generation_stale';end if;
 if rel.snapshot_id is not null then
  select * into strict old_snapshot from dv_collect_private.tcg_catalog_snapshots where id=rel.snapshot_id;
  if h.bulk_updated_at<old_snapshot.bulk_updated_at then raise exception 'catalog_snapshot_older';end if;
  if h.bulk_updated_at=old_snapshot.bulk_updated_at then
   if (h.bulk_id,h.compressed_sha256,h.sets_response_sha256,h.scope_sha256) is not distinct from (old_snapshot.bulk_id,old_snapshot.compressed_sha256,old_snapshot.sets_response_sha256,old_snapshot.scope_sha256) then return old_snapshot.id;end if;
   raise exception 'catalog_snapshot_time_conflict';
  end if;
 end if;
 if h.accepted_sets is distinct from (select count(*) from pg_temp.tcg_catalog_stage_sets)
 or h.accepted_cards is distinct from (select count(*) from pg_temp.tcg_catalog_stage_cards)
 or h.accepted_variants is distinct from (select count(*) from pg_temp.tcg_catalog_stage_variants)
 or h.accepted_cards<1 or h.accepted_sets<1 or h.record_count<h.accepted_cards
 or (select count(*) from pg_temp.tcg_catalog_stage_records)<>h.accepted_cards+h.accepted_sets
 or h.raw_manifest->>'object' is distinct from 'bulk_data' or h.raw_manifest->>'type' is distinct from 'all_cards'
 or h.raw_manifest->>'id' is distinct from h.bulk_id::text or (h.raw_manifest->>'updated_at')::timestamptz is distinct from h.bulk_updated_at
 or (h.raw_manifest->>'compressed_size')::bigint is distinct from h.compressed_size
 or h.raw_manifest->>'uri' is distinct from 'https://api.scryfall.com/bulk-data/'||h.bulk_id::text
 or h.raw_manifest->>'jsonl_download_uri' is distinct from h.download_uri then raise exception 'catalog_stage_counts_or_manifest';end if;
 -- Stage raw is strictly bound to its projection. Identity is never guessed.
 for t in select * from pg_temp.tcg_catalog_stage_records order by entity_kind collate "C",external_id,locale collate "C" nulls first loop
  if t.entity_kind not in ('set','card') or t.external_id is null or t.record_version is distinct from 'sha256:'||t.content_sha256
  or t.content_sha256 !~ '^[0-9a-f]{64}$' or t.canonical_utf8 is null or octet_length(t.canonical_utf8)>1048576
  or encode(extensions.digest(t.canonical_utf8,'sha256'),'hex') is distinct from t.content_sha256
  or convert_from(t.canonical_utf8,'UTF8')::jsonb is distinct from t.raw_record
  or t.raw_record->>'id' is distinct from t.external_id::text or t.raw_record->>'object' is distinct from t.entity_kind
  or t.source_path is null or length(t.source_path) not between 1 and 500 or t.retrieved_at is null then raise exception 'catalog_stage_evidence_invalid';end if;
  raw:=t.raw_record;
  if jsonb_typeof(raw) is distinct from 'object' or jsonb_typeof(raw->'name') is distinct from 'string' or length(raw->>'name') not between 1 and 500
  or raw->'digital' is distinct from 'false'::jsonb then raise exception 'catalog_raw_shape';end if;
  if t.entity_kind='set' then
   if t.locale is not null or raw->>'code' !~ '^[a-z0-9_]{1,32}$'
   or not exists(select 1 from pg_temp.tcg_catalog_stage_sets s where s.external_id=t.external_id and s.name=raw->>'name' and s.record_version=t.record_version)
   or jsonb_typeof(raw->'code') is distinct from 'string' then raise exception 'catalog_set_projection';end if;
  else
   lang:=case raw->>'lang' when 'en' then 'EN' when 'de' then 'DE' when 'fr' then 'FR' when 'it' then 'IT' when 'es' then 'ES' when 'ja' then 'JP' when 'ko' then 'KR' when 'zhs' then 'CN' end;
   loc:=case raw->>'lang' when 'zhs' then 'zh-cn' else raw->>'lang' end;
   display:=case when raw->>'lang'='en' then raw->>'name' when jsonb_typeof(raw->'printed_name')='string' then raw->>'printed_name'
    else (select string_agg(f->>'printed_name',' // ' order by ord) from jsonb_array_elements(raw->'card_faces') with ordinality a(f,ord) having count(*)=2 and count(f->>'printed_name')=2) end;
   if lang is null or t.locale is distinct from loc or raw->'oversized' is distinct from 'false'::jsonb or jsonb_typeof(raw->'games') is distinct from 'array' or not (raw->'games') ? 'paper'
   or not coalesce(raw->>'layout' in ('normal','split','flip','adventure','transform','modal_dfc'),false)
   or coalesce(jsonb_array_length(raw->'card_faces'),0)<>(case when raw->>'layout'='normal' then 0 else 2 end)
   or jsonb_typeof(raw->'collector_number') is distinct from 'string' or length(raw->>'collector_number') not between 1 and 128
   or raw->>'rarity' not in ('common','uncommon','rare','mythic','special','bonus')
   or display is null or length(display) not between 1 and 500
   or jsonb_typeof(raw->'finishes') is distinct from 'array' or jsonb_array_length(raw->'finishes') not between 1 and 3
   or (select count(distinct f) from jsonb_array_elements_text(raw->'finishes') a(f))<>jsonb_array_length(raw->'finishes')
   or exists(select 1 from jsonb_array_elements(raw->'finishes') a(f) where jsonb_typeof(f)<>'string' or f#>>'{}' not in ('nonfoil','foil','etched'))
   or not exists(select 1 from pg_temp.tcg_catalog_stage_cards c join pg_temp.tcg_catalog_stage_records s on s.external_id=c.set_external_id and s.entity_kind='set'
    where c.external_id=t.external_id and c.set_external_id::text=raw->>'set_id' and c.provider_lang=raw->>'lang' and c.language_code=lang and c.locale=loc
    and c.collector_number=raw->>'collector_number' and c.name=display and c.rarity='magic:'||(raw->>'rarity') and c.record_version=t.record_version and raw->>'set'=s.raw_record->>'code' and raw->>'set_name'=s.raw_record->>'name') then raise exception 'catalog_card_projection';end if;
  end if;
 end loop;
 -- Deterministic lock order: binding -> release -> provider identity order.
 -- This publisher never locks profiles or private ownership rows.
 for t in select 'set'::text kind,s.external_id,null::text locale,s.record_version,s.name,null::uuid set_external_id,null::text language_code,null::text collector_number,null::text rarity from pg_temp.tcg_catalog_stage_sets s
  union all select 'card',c.external_id,c.locale,c.record_version,c.name,c.set_external_id,c.language_code,c.collector_number,c.rarity from pg_temp.tcg_catalog_stage_cards c order by kind desc,external_id,locale nulls first loop
  select * into pr from dv_collect_private.tcg_provider_refs p where (p.game_key,p.provider_key,p.provider_version,p.entity_kind,p.namespace,p.external_id)=('magic','scryfall','1',t.kind,'api/'||case t.kind when 'set' then 'sets' else 'cards' end,t.external_id::text) and p.locale is not distinct from t.locale and p.discriminator is null for update;
  if found then
   target:=case t.kind when 'set' then pr.set_id else pr.card_id end;ref:=pr.id;
   if t.kind='set' then update dv_collect_private.tcg_sets set name=t.name where id=target;
   else
    select p.set_id into strict prev from dv_collect_private.tcg_provider_refs p where (p.game_key,p.provider_key,p.provider_version,p.entity_kind,p.namespace,p.external_id)=('magic','scryfall','1','set','api/sets',t.set_external_id::text) and p.locale is null and p.discriminator is null;
    if not exists(select 1 from dv_collect_private.tcg_cards c where c.id=target and (c.game_key,c.set_id,c.language_code,c.collector_number)=('magic',prev,t.language_code,t.collector_number)) then raise exception 'catalog_identity_conflict';end if;
    update dv_collect_private.tcg_cards set name=t.name,rarity=t.rarity where id=target;
   end if;
   update dv_collect_private.tcg_provider_refs set record_version=t.record_version where id=ref;
  else
   target:=gen_random_uuid();ref:=gen_random_uuid();
   if t.kind='set' then insert into dv_collect_private.tcg_sets values(target,'magic',t.name);
   else
    select p.set_id into strict prev from dv_collect_private.tcg_provider_refs p where (p.game_key,p.provider_key,p.provider_version,p.entity_kind,p.namespace,p.external_id)=('magic','scryfall','1','set','api/sets',t.set_external_id::text) and p.locale is null and p.discriminator is null;
    insert into dv_collect_private.tcg_cards values(target,'magic',prev,t.language_code,t.collector_number,t.name,t.rarity);
   end if;
   insert into dv_collect_private.tcg_provider_refs(id,game_key,provider_key,provider_version,entity_kind,namespace,external_id,locale,record_version,set_id,card_id)
   values(ref,'magic','scryfall','1',t.kind,'api/'||case t.kind when 'set' then 'sets' else 'cards' end,t.external_id::text,t.locale,t.record_version,case t.kind when 'set' then target end,case t.kind when 'card' then target end);
  end if;
  select * into strict rr from pg_temp.tcg_catalog_stage_records s where s.entity_kind=t.kind and s.external_id=t.external_id and s.locale is not distinct from t.locale;
  if not exists(select 1 from dv_collect_private.tcg_provider_evidence e where e.provider_ref_id=ref and e.record_version=t.record_version) then
   select id into prev from dv_collect_private.tcg_provider_evidence where provider_ref_id=ref order by retrieved_at desc,id desc limit 1;
   insert into dv_collect_private.tcg_provider_evidence(provider_ref_id,provider_version,record_version,raw_record,canonical_utf8,content_sha256,source_path,retrieved_at,supersedes_id)
   values(ref,'1',rr.record_version,rr.raw_record,rr.canonical_utf8,rr.content_sha256,rr.source_path,rr.retrieved_at,prev);
  end if;
 end loop;
 -- All card/reference evidence now exists. Variant targets are immutable axes.
 for t in select * from pg_temp.tcg_catalog_stage_variants order by card_external_id,locale collate "C",finish collate "C" loop
  select * into strict rr from pg_temp.tcg_catalog_stage_records s where s.entity_kind='card' and s.external_id=t.card_external_id and s.locale=t.locale;
  select p.card_id into strict target from dv_collect_private.tcg_provider_refs p where (p.game_key,p.provider_key,p.provider_version,p.entity_kind,p.namespace,p.external_id,p.locale)=('magic','scryfall','1','card','api/cards',t.card_external_id::text,t.locale) and p.discriminator is null;
  select e.id into strict refev from dv_collect_private.tcg_provider_evidence e join dv_collect_private.tcg_provider_refs p on p.id=e.provider_ref_id
   where (p.game_key,p.provider_key,p.provider_version,p.entity_kind,p.namespace,p.external_id,p.locale)=('magic','scryfall','1','card','api/cards',t.reference_external_id::text,t.locale) and p.discriminator is null and e.record_version=t.reference_record_version
   and exists(select 1 from pg_temp.tcg_catalog_stage_records s where s.entity_kind='card' and s.external_id=t.reference_external_id and s.locale=t.locale and s.record_version=t.reference_record_version);
  select * into pr from dv_collect_private.tcg_provider_refs p where (p.game_key,p.provider_key,p.provider_version,p.entity_kind,p.namespace,p.external_id,p.locale,p.discriminator)=('magic','scryfall','1','variant','api/cards/finishes',t.card_external_id::text,t.locale,'finish:'||t.finish) for update;
  if found then
   ref:=pr.id;
   if not exists(select 1 from dv_collect_private.tcg_card_variants v where v.id=pr.variant_id and (v.card_id,v.finish,v.artwork,v.treatment)=(target,t.finish,t.artwork,t.treatment) and v.edition is null and t.edition is null) then raise exception 'catalog_variant_identity_conflict';end if;
   update dv_collect_private.tcg_provider_refs set record_version=rr.record_version where id=ref;
  else
   prev:=gen_random_uuid();ref:=gen_random_uuid();
   insert into dv_collect_private.tcg_card_variants(id,card_id,game_key,language_code,rarity,finish,artwork,treatment,edition)
   select prev,target,'magic',c.language_code,c.rarity,t.finish,t.artwork,t.treatment,t.edition from dv_collect_private.tcg_cards c where c.id=target;
   insert into dv_collect_private.tcg_provider_refs(id,game_key,provider_key,provider_version,entity_kind,namespace,external_id,locale,discriminator,record_version,variant_id)
   values(ref,'magic','scryfall','1','variant','api/cards/finishes',t.card_external_id::text,t.locale,'finish:'||t.finish,rr.record_version,prev);
  end if;
  select id into ev from dv_collect_private.tcg_provider_evidence where provider_ref_id=ref and record_version=rr.record_version;
  if ev is null then
   select id into prev from dv_collect_private.tcg_provider_evidence where provider_ref_id=ref order by retrieved_at desc,id desc limit 1;
   insert into dv_collect_private.tcg_provider_evidence(provider_ref_id,provider_version,record_version,raw_record,canonical_utf8,content_sha256,source_path,retrieved_at,supersedes_id)
   values(ref,'1',rr.record_version,rr.raw_record,rr.canonical_utf8,rr.content_sha256,rr.source_path,rr.retrieved_at,prev) returning id into ev;
  end if;
  insert into dv_collect_private.tcg_catalog_derivations(provider_ref_id,evidence_id,contract_name,contract_version,validated_evidence,evidence_sha256,reference_evidence_id)
  values(ref,ev,'MagicVariantEvidence','1',t.validated_evidence,t.evidence_sha256,refev) on conflict do nothing;
 end loop;
 insert into dv_collect_private.tcg_catalog_snapshots select id,game_key,provider_key,provider_version,bulk_id,bulk_type,bulk_updated_at,download_uri,format,compressed_size,compressed_sha256,jsonl_sha256,sets_response_sha256,manifest_sha256,raw_manifest,scope_contract,scope_sha256,retrieved_at,record_count,accepted_cards,accepted_variants,accepted_sets,clock_timestamp() from pg_temp.tcg_catalog_stage_header;
 insert into dv_collect_private.tcg_catalog_snapshot_members(snapshot_id,provider_ref_id,evidence_id,derivation_id,source_path,retrieved_at)
 select p_snapshot_id,p.id,e.id,null,s.source_path,s.retrieved_at from pg_temp.tcg_catalog_stage_records s
 join dv_collect_private.tcg_provider_refs p on (p.game_key,p.provider_key,p.provider_version,p.entity_kind,p.namespace,p.external_id)=('magic','scryfall','1',s.entity_kind,'api/'||case s.entity_kind when 'set' then 'sets' else 'cards' end,s.external_id::text) and p.locale is not distinct from s.locale and p.discriminator is null
 join dv_collect_private.tcg_provider_evidence e on e.provider_ref_id=p.id and e.record_version=s.record_version;
 insert into dv_collect_private.tcg_catalog_snapshot_members(snapshot_id,provider_ref_id,evidence_id,derivation_id,source_path,retrieved_at)
 select p_snapshot_id,p.id,e.id,d.id,s.source_path,s.retrieved_at from pg_temp.tcg_catalog_stage_variants v
 join pg_temp.tcg_catalog_stage_records s on s.entity_kind='card' and s.external_id=v.card_external_id and s.locale=v.locale
 join dv_collect_private.tcg_provider_refs p on (p.game_key,p.provider_key,p.provider_version,p.entity_kind,p.namespace,p.external_id,p.locale,p.discriminator)=('magic','scryfall','1','variant','api/cards/finishes',v.card_external_id::text,v.locale,'finish:'||v.finish)
 join dv_collect_private.tcg_provider_evidence e on e.provider_ref_id=p.id and e.record_version=s.record_version
 join dv_collect_private.tcg_catalog_derivations d on d.provider_ref_id=p.id and d.evidence_id=e.id and d.evidence_sha256=v.evidence_sha256;
 if (select count(*) from dv_collect_private.tcg_catalog_snapshot_members where snapshot_id=p_snapshot_id)<>h.accepted_sets+h.accepted_cards+h.accepted_variants then raise exception 'catalog_member_count';end if;
 update dv_collect_private.tcg_catalog_releases set snapshot_id=p_snapshot_id,release_generation=release_generation+1,updated_at=clock_timestamp() where (game_key,provider_key,provider_version)=('magic','scryfall','1');
 return p_snapshot_id;
end$function$

CREATE OR REPLACE FUNCTION dv_collect_private.tcg_require_collection_release_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare r dv_collect_private.tcg_catalog_releases%rowtype;u uuid:=auth.uid();b boolean;
begin
 if tg_op='UPDATE' and old.tcg='magic' and new.tcg<>'magic' then raise exception 'magic_game_conversion_forbidden';end if;
 if new.tcg='magic' then
  if u is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) or new.user_id is distinct from u
  or tg_op='UPDATE' and old.user_id is distinct from u then raise exception 'tcg_parent_not_owned' using errcode='42501';end if;
  perform 1 from public.profiles where id=u and data_processing_restricted_at is null and account_closure_requested_at is null and account_status not in ('suspended','deleted') for update;
  if not found then raise exception 'account_data_processing_restricted' using errcode='42501';end if;
  select enabled into b from dv_collect_private.tcg_magic_on_demand_beta where game_key='magic' for share;
  if not found or not coalesce((public.get_security_schema_readiness_v1()->>'compatible')::boolean,false)
  or not coalesce((public.get_market_legal_schema_readiness_v1()->>'compatible')::boolean,false) then raise exception 'magic_beta_schema_unavailable';end if;
  if not b and (tg_op='INSERT' or
   (old.tcg,old.user_id,old.card_name,old.set_name,old.card_number,old.language,old.variant) is distinct from
   (new.tcg,new.user_id,new.card_name,new.set_name,new.card_number,new.language,new.variant)) then raise exception 'magic_beta_identity_locked';end if;
  if (tg_op='INSERT' or
   (old.tcg,old.user_id,old.card_name,old.set_name,old.card_number,old.language,old.variant) is distinct from
   (new.tcg,new.user_id,new.card_name,new.set_name,new.card_number,new.language,new.variant))
   and not dv_collect_private.magic_collect_admitted_v1(true) then
   raise exception 'magic_admission_required' using errcode='42501';end if;
  if new.language is null or new.language not in ('EN','DE','FR','IT','ES','JP','KR','CN') then raise exception 'magic_language_required';end if;
  return new;
 end if;
 if tg_op='UPDATE' and (old.tcg,old.user_id,old.card_name,old.set_name,old.card_number,old.language,old.variant)
 is not distinct from (new.tcg,new.user_id,new.card_name,new.set_name,new.card_number,new.language,new.variant) then return new;end if;
 select * into r from dv_collect_private.tcg_catalog_releases where game_key=new.tcg for share;
 if not found then return new;end if;
 if r.state<>'active' or r.schema_phase<>'collect' or r.snapshot_id is null
 or new.language not in ('EN','DE','FR','IT','ES','JP','KR','CN') or new.language is null
 or not exists(select 1 from dv_collect_private.tcg_games where game_key=new.tcg and available and collection_ready and not marketplace_ready)
 or not coalesce((public.get_security_schema_readiness_v1()->>'compatible')::boolean,false) then raise exception 'tcg_collection_release_unavailable';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION dv_collect_private.tcg_require_current_catalog_ref_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare r dv_collect_private.tcg_catalog_releases%rowtype;c dv_collect_private.tcg_cards%rowtype;
 i public.collection_items%rowtype;v dv_collect_private.tcg_card_variants%rowtype;name text;variant_label text;
begin
 select * into r from dv_collect_private.tcg_catalog_releases where game_key=new.game_key for share;
 if not found then return new;end if;
 if r.state<>'active' or r.schema_phase<>'collect' or r.snapshot_id is null
 or not coalesce((public.get_security_schema_readiness_v1()->>'compatible')::boolean,false)
 or not exists(select 1 from dv_collect_private.tcg_catalog_snapshot_members m join dv_collect_private.tcg_provider_refs p on p.id=m.provider_ref_id where m.snapshot_id=r.snapshot_id and m.provider_ref_id=new.provider_ref_id and (p.game_key,p.provider_key,p.provider_version)=(r.game_key,r.provider_key,r.provider_version) and (p.entity_kind='card' and p.card_id=new.card_id and new.variant_id is null or p.entity_kind='variant' and p.variant_id=new.variant_id and m.derivation_id is not null)) then raise exception 'tcg_catalog_ref_unavailable';end if;
 select * into strict c from dv_collect_private.tcg_cards where id=new.card_id and game_key=new.game_key;
 select * into strict i from public.collection_items where id=new.collection_item_id;
 select s.name into strict name from dv_collect_private.tcg_sets s where s.id=c.set_id;
 if (i.tcg,i.language,i.card_number,i.card_name,i.set_name) is distinct from (c.game_key,c.language_code,c.collector_number,c.name,name) then raise exception 'tcg_catalog_parent_mismatch';end if;
 if new.variant_id is not null then
  select * into strict v from dv_collect_private.tcg_card_variants where id=new.variant_id and card_id=c.id and game_key=c.game_key and language_code=c.language_code;
  variant_label:=case v.finish when 'nonfoil' then 'Nonfoil' when 'foil' then 'Foil' when 'etched' then 'Etched' end||' · '||case v.artwork when 'normal' then 'Normal' when 'alternate_art' then 'Alternate Art' end||' · '||case v.treatment when 'normal' then 'Normal' when 'borderless' then 'Borderless' when 'extended_art' then 'Extended Art' when 'showcase' then 'Showcase' when 'retro_frame' then 'Retro Frame' when 'prerelease_stamp' then 'Prerelease Stamp' end;
  if variant_label is null or i.variant is distinct from variant_label then raise exception 'tcg_catalog_parent_mismatch';end if;
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION dv_collect_private.tcg_set_own_link_v1(p_parent_id uuid, p_provider_ref_id uuid, p_listing boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare u uuid:=auth.uid();g text;r dv_collect_private.tcg_provider_refs%rowtype;c uuid;v uuid;restricted timestamptz;
begin
 if u is null then raise exception 'authentication_required' using errcode='42501';end if;
 if not coalesce((public.get_security_schema_readiness_v1()->>'compatible')::boolean,false)
 or p_listing and not coalesce((public.get_market_legal_schema_readiness_v1()->>'compatible')::boolean,false) then raise exception 'tcg_schema_not_ready';end if;
 select data_processing_restricted_at into restricted from public.profiles where id=u for update;
 if not found or restricted is not null then raise exception 'account_data_processing_restricted' using errcode='42501';end if;
 if p_listing then
  select tcg into g from public.market_listings where id=p_parent_id and seller_id=u and product_kind<>'sealed' for update;
 else select tcg into g from public.collection_items where id=p_parent_id and user_id=u for update;end if;
 if not found then raise exception 'tcg_parent_not_owned' using errcode='42501';end if;
 if p_provider_ref_id is null then
  if p_listing then delete from dv_collect_private.listing_catalog_links where listing_id=p_parent_id;
  else delete from dv_collect_private.collection_item_catalog_links where collection_item_id=p_parent_id;end if;return;
 end if;
 select * into r from dv_collect_private.tcg_provider_refs where id=p_provider_ref_id and game_key=g;
 if not found or r.entity_kind not in ('card','variant') then raise exception 'tcg_ref_invalid' using errcode='23514';end if;
 if r.entity_kind='variant' then select card_id,id into c,v from dv_collect_private.tcg_card_variants where id=r.variant_id;else c:=r.card_id;end if;
 if p_listing then
  insert into dv_collect_private.listing_catalog_links(listing_id,game_key,card_id,variant_id,provider_ref_id)
   values(p_parent_id,g,c,v,r.id) on conflict(listing_id) do update set game_key=excluded.game_key,card_id=excluded.card_id,
   variant_id=excluded.variant_id,provider_ref_id=excluded.provider_ref_id,verified_at=now();
 else
  insert into dv_collect_private.collection_item_catalog_links(collection_item_id,game_key,card_id,variant_id,provider_ref_id)
   values(p_parent_id,g,c,v,r.id) on conflict(collection_item_id) do update set game_key=excluded.game_key,card_id=excluded.card_id,
   variant_id=excluded.variant_id,provider_ref_id=excluded.provider_ref_id,verified_at=now();
 end if;
end $function$

CREATE OR REPLACE FUNCTION dv_collect_private.tcg_validate_catalog_member_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare r dv_collect_private.tcg_provider_refs%rowtype;e dv_collect_private.tcg_provider_evidence%rowtype;
 s dv_collect_private.tcg_catalog_snapshots%rowtype;v dv_collect_private.tcg_card_variants%rowtype;
 a jsonb;b jsonb;x jsonb;raws jsonb[];projections jsonb[];parts jsonb[];keys text[];k text;i integer;j integer;n integer;
 canonical text:='';tokens text[];objects jsonb[];obj jsonb;typ text;finish text;art text;treatment text;
 ff text[];pt text[];special text[];promos text[];reference_raw jsonb;reference_ref dv_collect_private.tcg_provider_refs%rowtype;
begin
 select * into strict r from dv_collect_private.tcg_provider_refs where id=new.provider_ref_id;
 select * into strict e from dv_collect_private.tcg_provider_evidence where id=new.evidence_id and provider_ref_id=r.id;
 if tg_table_name='tcg_catalog_snapshot_members' then
  select * into strict s from dv_collect_private.tcg_catalog_snapshots where id=new.snapshot_id;
  if (s.game_key,s.provider_key,s.provider_version) is distinct from (r.game_key,r.provider_key,r.provider_version)
  or r.entity_kind not in ('set','card','variant') or (r.entity_kind='variant') is distinct from (new.derivation_id is not null) then raise exception 'tcg_catalog_member_invalid';end if;
  return new;
 end if;
 if r.entity_kind is distinct from 'variant' or (r.game_key,r.provider_key,r.provider_version,r.namespace) is distinct from ('magic','scryfall','1','api/cards/finishes') then raise exception 'tcg_derivation_binding_invalid';end if;
 select * into strict v from dv_collect_private.tcg_card_variants where id=r.variant_id;
 x:=new.validated_evidence;
 if jsonb_typeof(x) is distinct from 'object' or not x ?& array['contract','version','game_key','provider_key','provider_version','printing_context','chosen_finish','available_finishes','frame','border_color','full_art','frame_effects','promo_types','illustration_ids','variation_of','reference_kind','reference_printing']
 or (select count(*) from jsonb_object_keys(x))<>17
 or (x->>'contract',x->>'version',x->>'game_key',x->>'provider_key',x->>'provider_version') is distinct from ('MagicVariantEvidence','1','magic','scryfall','1')
 or new.contract_name<>'MagicVariantEvidence' or new.contract_version<>'1' or new.reference_evidence_id is null then raise exception 'tcg_derivation_shape_invalid';end if;
 select re.raw_record into strict reference_raw from dv_collect_private.tcg_provider_evidence re where re.id=new.reference_evidence_id;
 select rr.* into strict reference_ref from dv_collect_private.tcg_provider_refs rr join dv_collect_private.tcg_provider_evidence re on re.provider_ref_id=rr.id where re.id=new.reference_evidence_id;
 if (reference_ref.game_key,reference_ref.provider_key,reference_ref.provider_version,reference_ref.entity_kind,reference_ref.locale) is distinct from (r.game_key,r.provider_key,r.provider_version,'card',r.locale) then raise exception 'tcg_derivation_reference_invalid';end if;
 raws:=array[e.raw_record,reference_raw];projections:=array[]::jsonb[];
 for i in 1..2 loop
  obj:=raws[i];
  a:=jsonb_build_object('printing_context',jsonb_build_object('id',obj->'id','set_id',obj->'set_id','oracle_id',coalesce(obj->'oracle_id','null'::jsonb),'lang',obj->'lang','layout',obj->'layout','collector_number',obj->'collector_number','released_at',coalesce(obj->'released_at','null'::jsonb),'variation',coalesce(obj->'variation','null'::jsonb),'reprint',coalesce(obj->'reprint','null'::jsonb)),
   'frame',coalesce(obj->'frame','null'::jsonb),'border_color',coalesce(obj->'border_color','null'::jsonb),'full_art',coalesce(obj->'full_art','null'::jsonb),'frame_effects',coalesce(obj->'frame_effects','[]'::jsonb),'promo_types',coalesce(obj->'promo_types','[]'::jsonb),'variation_of',coalesce(obj->'variation_of','null'::jsonb),'illustration_ids',
   case when coalesce(jsonb_array_length(obj->'card_faces'),0)>0 then (select jsonb_agg(coalesce(f->'illustration_id','null'::jsonb) order by ord) from jsonb_array_elements(obj->'card_faces') with ordinality q(f,ord)) else jsonb_build_array(coalesce(obj->'illustration_id','null'::jsonb)) end);
  projections:=array_append(projections,a);
 end loop;
 if x - array['contract','version','game_key','provider_key','provider_version','chosen_finish','available_finishes','reference_kind','reference_printing'] is distinct from projections[1]
 or x->'available_finishes' is distinct from e.raw_record->'finishes' or x->'reference_printing' is distinct from projections[2] then raise exception 'tcg_derivation_raw_mismatch';end if;
 -- Canonical derivation has closed ASCII keys and no numeric values; unlike raw
 -- records its exact ECMAScript canonical bytes can be reconstructed in SQL.
 objects:=array[x];tokens:=array[null::text];
 while cardinality(objects)>0 loop
  n:=cardinality(objects);obj:=objects[n];k:=tokens[n];objects:=objects[1:n-1];tokens:=tokens[1:n-1];
  if k is not null then canonical:=canonical||k;continue;end if;
  typ:=jsonb_typeof(obj);
  if typ in ('string','boolean','null') then canonical:=canonical||obj::text;
  elsif typ='object' then
   canonical:=canonical||'{';objects:=array_append(objects,'null'::jsonb);tokens:=array_append(tokens,'}');
   keys:=array(select key from jsonb_object_keys(obj) q(key) order by key collate "C");
   for j in reverse cardinality(keys)..1 loop
    k:=keys[j];if k in ('__proto__','prototype','constructor') then raise exception 'tcg_derivation_unsafe_key';end if;
    objects:=array_append(objects,obj->k);tokens:=array_append(tokens,null);
    objects:=array_append(objects,'null'::jsonb);tokens:=array_append(tokens,to_jsonb(k)::text||':');
    if j>1 then objects:=array_append(objects,'null'::jsonb);tokens:=array_append(tokens,',');end if;
   end loop;
  elsif typ='array' then
   canonical:=canonical||'[';objects:=array_append(objects,'null'::jsonb);tokens:=array_append(tokens,']');
   for j in reverse jsonb_array_length(obj)-1..0 loop
    objects:=array_append(objects,obj->j);tokens:=array_append(tokens,null);
    if j>0 then objects:=array_append(objects,'null'::jsonb);tokens:=array_append(tokens,',');end if;
   end loop;
  else raise exception 'tcg_derivation_scalar_invalid';end if;
 end loop;
 if octet_length(canonical)>16384 or encode(extensions.digest(convert_to(canonical,'UTF8'),'sha256'),'hex') is distinct from new.evidence_sha256 then raise exception 'tcg_derivation_digest_invalid';end if;
 a:=projections[1];b:=projections[2];finish:=x->>'chosen_finish';
 if finish is null or finish not in ('nonfoil','foil','etched') or not (x->'available_finishes') ? finish or r.discriminator is distinct from 'finish:'||finish then raise exception 'tcg_derivation_finish_invalid';end if;
 if jsonb_typeof(a->'frame_effects') is distinct from 'array' or jsonb_typeof(a->'promo_types') is distinct from 'array' then raise exception 'tcg_derivation_flags_invalid';end if;
 for obj in select unnest(array[a,b]) loop
  foreach k in array array['frame_effects','promo_types'] loop
   if jsonb_array_length(obj->k)>32 or (select count(*) from jsonb_array_elements(obj->k))<>(select count(distinct value) from jsonb_array_elements(obj->k))
   or exists(select 1 from jsonb_array_elements(obj->k) q(f) where jsonb_typeof(f)<>'string' or length(f#>>'{}')>32 or (f#>>'{}') !~ '^[a-z0-9_]+$') then raise exception 'tcg_derivation_flags_invalid';end if;
  end loop;
 end loop;
 if not coalesce(b->>'frame' in ('2003','2015'),false) or not coalesce(b->>'border_color' in ('black','white'),false) or b->'full_art' is distinct from 'false'::jsonb
 or b#>'{printing_context,variation}' is distinct from 'false'::jsonb or b->'variation_of' is distinct from 'null'::jsonb
 or exists(select 1 from jsonb_array_elements_text(b->'frame_effects') q(f) where f<>'legendary')
 or exists(select 1 from jsonb_array_elements_text(b->'promo_types') q(f) where f<>'boosterfun') then raise exception 'tcg_derivation_reference_not_standard';end if;
 if a#>>'{printing_context,oracle_id}' is null or a#>>'{printing_context,oracle_id}' is distinct from b#>>'{printing_context,oracle_id}'
 or a#>>'{printing_context,lang}' is distinct from b#>>'{printing_context,lang}' or a#>>'{printing_context,layout}' is distinct from b#>>'{printing_context,layout}' then raise exception 'tcg_derivation_concept_invalid';end if;
 n:=case a#>>'{printing_context,layout}' when 'normal' then 1 when 'split' then 2 when 'adventure' then 2 when 'transform' then 2 when 'modal_dfc' then 2 else 0 end;
 if n=0 or jsonb_array_length(a->'illustration_ids')<>n or jsonb_array_length(b->'illustration_ids')<>n
 or exists(select 1 from jsonb_array_elements((a->'illustration_ids')||(b->'illustration_ids')) q(f) where jsonb_typeof(f)<>'string' or (f#>>'{}') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then raise exception 'tcg_derivation_art_invalid';end if;
 if x->>'reference_kind'='same_set_standard' then
  if a#>>'{printing_context,set_id}' is distinct from b#>>'{printing_context,set_id}' or a->>'variation_of' is not null and a->>'variation_of' is distinct from b#>>'{printing_context,id}' then raise exception 'tcg_derivation_reference_invalid';end if;
  if a#>>'{printing_context,id}'=b#>>'{printing_context,id}' and a is distinct from b then raise exception 'tcg_derivation_reference_invalid';end if;
 elsif x->>'reference_kind'='earlier_modern_standard' then
  if a#>'{printing_context,reprint}' is distinct from 'true'::jsonb or a->'variation_of' is distinct from 'null'::jsonb
  or a#>>'{printing_context,id}'=b#>>'{printing_context,id}'
  or a#>>'{printing_context,released_at}' is null or b#>>'{printing_context,released_at}' is null
  or (b#>>'{printing_context,released_at}')::date >= (a#>>'{printing_context,released_at}')::date then raise exception 'tcg_derivation_reference_invalid';end if;
 else raise exception 'tcg_derivation_reference_invalid';end if;
 art:=case when a->'illustration_ids'=b->'illustration_ids' then 'normal' else 'alternate_art' end;
 ff:=array(select jsonb_array_elements_text(a->'frame_effects'));pt:=array(select jsonb_array_elements_text(a->'promo_types'));
 special:=array(select f from unnest(ff) q(f) where f<>'legendary' and not (f='etched' and finish='etched'));
 promos:=array(select f from unnest(pt) q(f) where f<>'boosterfun');
 if a->>'frame' in ('2003','2015') then
  if a->>'border_color' in ('black','white') and a->'full_art'='false'::jsonb and cardinality(special)=0 and cardinality(promos)=0 then treatment:='normal';
  elsif a->>'border_color'='borderless' and jsonb_typeof(a->'full_art')='boolean' and cardinality(special)=0 and cardinality(promos)=0 then treatment:='borderless';
  elsif a->>'border_color' in ('black','white') and jsonb_typeof(a->'full_art')='boolean' and cardinality(special)=1 and cardinality(promos)=0 and special[1] in ('extendedart','showcase') then treatment:=case special[1] when 'extendedart' then 'extended_art' else 'showcase' end;
  elsif a->>'border_color' in ('black','white') and a->'full_art'='false'::jsonb and cardinality(special)=0 and cardinality(promos)=2 and promos @> array['prerelease','datestamped'] and finish='foil' then treatment:='prerelease_stamp';end if;
 elsif a->>'frame' in ('1993','1997') and a->>'border_color' in ('black','white') and a->'full_art'='false'::jsonb and cardinality(special)=0 and cardinality(promos)=0 and x->>'reference_kind'='earlier_modern_standard' then treatment:='retro_frame';end if;
 if treatment is null or (v.finish,v.artwork,v.treatment,v.edition) is distinct from (finish,art,treatment,null::text) then raise exception 'tcg_derivation_variant_invalid';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION dv_collect_private.tcg_validate_link_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare r dv_collect_private.tcg_provider_refs%rowtype;c uuid;v uuid;g text;
begin
 select * into r from dv_collect_private.tcg_provider_refs where id=new.provider_ref_id;
 if r.entity_kind='card' then c:=r.card_id;
 elsif r.entity_kind='variant' then
  select card_id,id into c,v from dv_collect_private.tcg_card_variants where id=r.variant_id;
 else raise exception 'tcg_link_kind_invalid' using errcode='23514';end if;
 if (r.game_key,c,v) is distinct from (new.game_key,new.card_id,new.variant_id) then
  raise exception 'tcg_link_target_mismatch' using errcode='23514';end if;
 if tg_table_name='collection_item_catalog_links' then
  select tcg into g from public.collection_items where id=new.collection_item_id;
 else select tcg into g from public.market_listings where id=new.listing_id;end if;
 if g is distinct from new.game_key or not exists(select 1 from dv_collect_private.tcg_games
 where game_key=g and available and case when tg_table_name='collection_item_catalog_links' then collection_ready else marketplace_ready end) then
  raise exception 'tcg_link_game_mismatch' using errcode='23514';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION dv_collect_private.tcg_validate_provider_evidence_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare r dv_collect_private.tcg_provider_refs%rowtype;x jsonb;entry record;stack jsonb[];depths integer[];d integer;k integer;n double precision;
begin
 select * into strict r from dv_collect_private.tcg_provider_refs where id=new.provider_ref_id;
 if new.provider_version is distinct from r.provider_version
 or new.record_version is distinct from 'sha256:'||new.content_sha256
 or encode(extensions.digest(new.canonical_utf8,'sha256'),'hex') is distinct from new.content_sha256
 or convert_from(new.canonical_utf8,'UTF8')::jsonb is distinct from new.raw_record
 or jsonb_typeof(new.raw_record) is distinct from 'object' then raise exception 'tcg_provider_evidence_invalid';end if;
 if new.supersedes_id is not null then
  if new.supersedes_id=new.id or not exists(select 1 from dv_collect_private.tcg_provider_evidence e where e.id=new.supersedes_id and e.provider_ref_id=new.provider_ref_id) then raise exception 'tcg_supersession_invalid';end if;
 end if;
 stack:=array[new.raw_record];depths:=array[0];
 while cardinality(stack)>0 loop
  k:=cardinality(stack);x:=stack[k];d:=depths[k];stack:=stack[1:k-1];depths:=depths[1:k-1];
  if d>20 then raise exception 'tcg_evidence_depth_limit';end if;
  if jsonb_typeof(x)='object' then
   for entry in select key,value from jsonb_each(x) loop
    if entry.key in ('__proto__','prototype','constructor') then raise exception 'tcg_evidence_unsafe_key';end if;
    stack:=array_append(stack,entry.value);depths:=array_append(depths,d+1);
   end loop;
  elsif jsonb_typeof(x)='array' then
   if jsonb_array_length(x)>1000 then raise exception 'tcg_evidence_array_limit';end if;
   for entry in select value from jsonb_array_elements(x) loop stack:=array_append(stack,entry.value);depths:=array_append(depths,d+1);end loop;
  elsif jsonb_typeof(x)='number' then
   n:=(x#>>'{}')::double precision;
   if n in ('Infinity'::float8,'-Infinity'::float8,'NaN'::float8) or trunc(n)=n and abs(n)>9007199254740991 then raise exception 'tcg_evidence_number_invalid';end if;
  end if;
 end loop;
 if (r.game_key,r.provider_key,r.provider_version) is distinct from ('magic','scryfall','1') then raise exception 'tcg_evidence_binding_invalid';end if;
 if new.raw_record->>'id' is distinct from r.external_id
 or new.raw_record->>'object' is distinct from (case when r.entity_kind='set' then 'set' else 'card' end)
 or r.entity_kind='sealed' then raise exception 'tcg_evidence_identity_invalid';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION dv_market_private.b07_add_workdays_de(p_start timestamp with time zone, p_days integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_local timestamp without time zone := p_start at time zone 'Europe/Berlin';
  v_count integer := 0;
begin
  if p_start is null or p_days is null or p_days<0 then return null; end if;
  while v_count<p_days loop
    v_local:=v_local+interval '1 day';
    if extract(isodow from v_local)<7 then v_count:=v_count+1; end if;
  end loop;
  return v_local at time zone 'Europe/Berlin';
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.b07_release1_shipping_windows()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
begin
  if new.fulfillment_group='shipping' and new.shipped_at is not null then
    if nullif(trim(coalesce(new.tracking_code,'')),'') is null then
      new.untracked_auto_close_at:=new.shipped_at+interval '40 days';new.closure_eligible_at:=new.untracked_auto_close_at;new.delivery_review_status:='not_requested';
    elsif new.delivery_evidence_at is null then
      new.untracked_auto_close_at:=null;
      if old.shipped_at is null or old.tracking_code is distinct from new.tracking_code then new.closure_eligible_at:=null;end if;
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION dv_market_private.b07_set_shipping_due()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare
  v_should_set boolean:=false;
  v_start timestamptz;
begin
  if tg_op='INSERT' then
    v_should_set:=new.fulfillment_group='shipping'
      and new.payment_status='paid'
      and new.shipping_due_at is null;
  else
    v_should_set:=new.fulfillment_group='shipping'
      and new.payment_status='paid'
      and new.shipping_due_at is null
      and (
        old.payment_status is distinct from 'paid'
        or old.fulfillment_group is distinct from 'shipping'
      );
  end if;

  if v_should_set then
    v_start:=coalesce(new.paid_at,now());
    new.shipping_due_at:=dv_market_private.b07_add_workdays_de(v_start,3);
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.b1_lock_target(p_target uuid, p_owner_only boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p record; found_target boolean:=false; found_actor boolean:=false;
begin
 perform public.require_duelvanta_privileged_session();
 if p_owner_only and not public.is_duelvanta_owner(auth.uid()) then raise exception 'owner_access_required' using errcode='42501'; end if;
 if not public.has_staff_permission('reports_review',auth.uid()) or not public.has_staff_permission('users_restrict',auth.uid()) then
  raise exception 'safety_permissions_required' using errcode='42501';
 end if;
 for p in select id,data_processing_restricted_at,account_closure_requested_at from public.profiles
 where id=auth.uid() or id=p_target order by id for no key update loop
  if p.id=auth.uid() then
   found_actor:=true;
   if p.data_processing_restricted_at is not null or p.account_closure_requested_at is not null then raise exception 'staff_actor_processing_hold' using errcode='42501'; end if;
  end if;
  if p.id=p_target then found_target:=true; end if;
 end loop;
 if not found_actor or not found_target then raise exception 'safety_profile_missing' using errcode='42501'; end if;
 perform public.require_duelvanta_privileged_session();
 if public.is_duelvanta_owner(p_target) then raise exception 'Owner cannot be targeted by moderation actions' using errcode='42501'; end if;
 if dv_market_private.b1_data_rights_blocked(p_target) then raise exception 'safety_target_data_rights_hold' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION dv_market_private.b1_project_safety()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare required boolean;
begin
 -- A processing-only marker is not itself a new Safety sanction. Preserve
 -- D3's existing read rights; markers still independently block any release.
 required:=dv_market_private.c_unresolved(new.id)
   or dv_market_private.b1_has_cause(new.id);
 -- An unexplained true write is retained conservatively, never relabelled B1.
 if new.safety_restricted and not required then
  insert into dv_market_private.battle_safety_causes(target_id,kind,reason)
  values(new.id,'legacy_unknown','Unattributed safety write');
  required:=true;
 end if;
 new.safety_restricted:=required;
 return new;
end $function$

CREATE OR REPLACE FUNCTION dv_market_private.b1_release(p_cause uuid, p_reason text, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c dv_market_private.battle_safety_causes%rowtype; replay boolean; remaining boolean;
begin
 perform public.require_duelvanta_privileged_session();
 if not public.is_duelvanta_owner(auth.uid()) then raise exception 'owner_access_required' using errcode='42501'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'correction_reason_required'; end if;
 select * into c from dv_market_private.battle_safety_causes where id=p_cause and kind=p_kind;
 if not found then raise exception 'safety_cause_not_found'; end if;
 perform dv_market_private.b1_lock_target(c.target_id,true);
 replay:=exists(select 1 from dv_market_private.battle_safety_releases where cause_id=c.id);
 if not replay then
  if p_kind='legacy_unknown' and exists(select 1 from dv_market_private.battle_safety_causes x
   where x.target_id=c.target_id and x.id<>c.id and not exists(select 1 from dv_market_private.battle_safety_releases r where r.cause_id=x.id)) then
   raise exception 'other_safety_cause_active' using errcode='42501';
  end if;
  insert into dv_market_private.battle_safety_releases(cause_id,actor_id,reason) values(c.id,auth.uid(),trim(p_reason));
  insert into public.admin_audit_log(actor_id,target_user_id,action,details)
  values(auth.uid(),c.target_id,case when p_kind='b1' then 'battle_sanction_released' else 'battle_legacy_safety_reviewed' end,
   jsonb_build_object('sanction_id',c.id,'report_id',c.report_id,'reason',trim(p_reason)));
  remaining:=dv_market_private.b1_has_cause(c.target_id);
  -- Always touch the shared profile row, even when another cause remains:
  -- this also forces stale REPEATABLE READ contenders to serialize/fail.
  update public.profiles set safety_restricted=remaining,updated_at=now() where id=c.target_id;
 end if;
 select safety_restricted into remaining from public.profiles where id=c.target_id;
 return jsonb_build_object('sanction_id',c.id,'replayed',replay,'safety_restricted',remaining);
end $function$

CREATE OR REPLACE FUNCTION dv_market_private.b1_restrict(p_report uuid, p_target uuid, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cause uuid;
begin
 perform dv_market_private.b1_lock_target(p_target,false);
 if not exists(select 1 from public.battle_reports where id=p_report and reported_user_id=p_target) then raise exception 'd3_case_changed_or_missing'; end if;
 insert into dv_market_private.battle_safety_causes(target_id,kind,report_id,actor_id,reason)
 values(p_target,'b1',p_report,auth.uid(),left(p_note,1000)) returning id into cause;
 update public.profiles set safety_restricted=true,updated_at=now() where id=p_target;
 return cause;
end $function$

CREATE OR REPLACE FUNCTION dv_market_private.block_restricted_account_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if current_user<>'service_role' and auth.uid() is not null and exists(
    select 1 from public.profiles p where p.id=auth.uid() and p.data_processing_restricted_at is not null
  ) then raise exception 'account_data_processing_restricted'; end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.c_lock_attempt(p_request uuid, p_token uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid;a uuid;begin
 select user_id into u from dv_market_private.account_deletion_requests where id=p_request;
 perform 1 from public.profiles where id=u for no key update;
 if not found then raise exception 'c_worker_profile_missing';end if;
 perform 1 from dv_market_private.account_deletion_requests where id=p_request and status='processing' and lock_token=p_token for update;
 if not found or exists(select 1 from dv_market_private.c_withdrawal_receipts where request_id=p_request) then raise exception 'deletion_request_lock_invalid';end if;
 select id into a from dv_market_private.c_attempts where request_id=p_request and token=p_token;
 if not found then raise exception 'c_worker_attempt_invalid';end if;
 return a;
end $function$

CREATE OR REPLACE FUNCTION dv_market_private.c_session()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s auth.sessions%rowtype;need_mfa boolean;begin
 if auth.uid() is null or auth.jwt()->>'role' is distinct from 'authenticated'
 or current_setting('role',true) is distinct from 'authenticated' then
 raise exception 'c_self_authenticated_required' using errcode='42501';end if;
 select * into s from auth.sessions where id=(auth.jwt()->>'session_id')::uuid and user_id=auth.uid() for share;
 if not found or (s.not_after is not null and s.not_after<=clock_timestamp()) then raise exception 'c_session_invalid' using errcode='42501';end if;
 select exists(select 1 from auth.mfa_factors where user_id=auth.uid() and status='verified')
 or exists(select 1 from public.profiles where id=auth.uid() and role in ('owner','admin','moderator','judge')) into need_mfa;
 if need_mfa and (auth.jwt()->>'aal' is distinct from 'aal2' or s.aal is distinct from 'aal2'
 or not exists(select 1 from auth.mfa_factors where id=s.factor_id and user_id=auth.uid() and status='verified')) then
 raise exception 'c_mfa_required' using errcode='42501';end if;
 return s.id;
end $function$

CREATE OR REPLACE FUNCTION dv_market_private.capture_market_contract_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_listing public.market_listings%rowtype;v_order public.market_orders%rowtype;v_offer public.market_offers%rowtype;
  v_seller jsonb;v_product jsonb;v_buyer_type text;v_type text;
  v_qty integer:=greatest(coalesce(new.item_quantity,1),1);v_unit numeric;v_goods numeric:=round(new.amount,2);
  v_shipping numeric;v_total numeric;v_shipping_label text;v_payment_text text;v_text text;v_snapshot uuid;
begin
  if new.order_id is null or exists(select 1 from dv_market_private.market_contract_snapshots where deal_id=new.id) then return new; end if;
  select * into v_listing from public.market_listings where id=new.listing_id;
  select * into v_order from public.market_orders where id=new.order_id;
  if not found then raise exception 'checkout_order_missing'; end if;
  if new.currency<>'EUR' or v_goods<=0 then raise exception 'checkout_amount_invalid'; end if;
  if new.shipping_cost is null or new.shipping_cost<0 or new.shipping_cost>500 or new.shipping_method is null then raise exception 'checkout_shipping_incomplete'; end if;
  if new.offer_id is not null then select * into v_offer from public.market_offers where id=new.offer_id; end if;
  v_buyer_type:=dv_market_private.require_market_buyer_type(new.buyer_id);
  if new.offer_id is not null and v_offer.buyer_type_snapshot is distinct from v_buyer_type then raise exception 'buyer_snapshot_invalid'; end if;
  if v_offer.offer_type='price' then
    if v_offer.contract_review_snapshot is null or v_offer.contract_review_snapshot->>'snapshot_version'<>'price-offer-contract-v1' or v_offer.offer_review_hash is null
       or encode(digest(convert_to(v_offer.contract_review_snapshot::text,'UTF8'),'sha256'),'hex')<>v_offer.offer_review_hash then raise exception 'offer_contract_snapshot_invalid'; end if;
    v_seller:=v_offer.contract_review_snapshot->'seller_party';v_product:=v_offer.contract_review_snapshot->'product';v_type:=v_offer.contract_review_snapshot->>'contract_classification';
    if v_type not in ('c2c','b2c') or (v_offer.contract_review_snapshot->>'quantity')::integer<>v_qty or round((v_offer.contract_review_snapshot->>'offered_goods_total')::numeric,2)<>v_goods
       or v_offer.contract_review_snapshot->>'shipping_method' is distinct from new.shipping_method or round((v_offer.contract_review_snapshot->>'shipping_cost')::numeric,2)<>round(new.shipping_cost,2)
       or v_offer.contract_review_snapshot->>'currency' is distinct from new.currency then raise exception 'offer_contract_snapshot_mismatch'; end if;
  elsif v_offer.offer_type='fixed_price' then
    if v_offer.contract_review_snapshot is null or v_offer.contract_review_snapshot->>'snapshot_version'<>'checkout-contract-v2' or v_offer.checkout_hash_snapshot is null
       or encode(digest(convert_to(v_offer.contract_review_snapshot::text,'UTF8'),'sha256'),'hex')<>v_offer.checkout_hash_snapshot then raise exception 'fixed_checkout_snapshot_invalid'; end if;
    v_seller:=v_offer.contract_review_snapshot->'seller_party';v_product:=v_offer.contract_review_snapshot->'product';v_type:=v_offer.contract_review_snapshot->>'contract_classification';
    if v_type not in ('c2c','b2c') or (v_offer.contract_review_snapshot->>'quantity')::integer<>v_qty
       or round((v_offer.contract_review_snapshot->>'goods_total')::numeric,2)<>v_goods
       or v_offer.contract_review_snapshot->>'shipping_method' is distinct from new.shipping_method
       or round((v_offer.contract_review_snapshot->>'shipping_cost')::numeric,2)<>round(new.shipping_cost,2)
       or v_offer.contract_review_snapshot->>'currency' is distinct from new.currency
       or v_offer.contract_review_snapshot->>'payment_provider'<>'stripe_connect' then raise exception 'fixed_contract_snapshot_mismatch'; end if;
  else
    v_seller:=dv_market_private.market_checkout_seller_party(new.seller_id);v_type:=dv_market_private.market_contract_classification(v_seller->>'seller_type',v_buyer_type);
    if v_type is null then raise exception 'contract_classification_invalid'; end if;v_product:=dv_market_private.market_checkout_product_snapshot(v_listing);
  end if;
  v_shipping_label:=case new.shipping_method
    when 'standard_letter' then 'Standardbrief' when 'tracked_letter' then 'Brief mit Tracking'
    when 'parcel' then 'Paket mit Tracking' when 'pickup' then 'Abholung' else 'Individuell / nach Absprache' end;
  v_unit:=round(v_goods/v_qty,2);v_shipping:=round(new.shipping_cost,2);v_total:=round(v_goods+v_shipping,2);
  v_payment_text:=case when new.payment_provider='stripe_connect'
    then 'Stripe Connect – Vertragsschluss mit Erstellung der automatischen Zahlungsaufforderung.'
    else 'Zahlung nach Vertragsschluss; in der Beta keine integrierte Onlinezahlung oder Auszahlung.' end;
  v_text:=format(
    E'DUELVANTA BESTELLBESTÄTIGUNG\\nDokumentversion: checkout-contract-v2\\nOrder: %s\\nVertragsschluss: %s\\nVertragstyp: %s\\nKäuferstatus: %s\\nVerkäuferrolle: %s\\nVertragspartner: %s\\nAnschrift: %s, %s %s, %s\\nProdukt: %s\\nMenge: %s\\nStückpreis: %s EUR\\nWarenwert: %s EUR\\nVersand (%s): %s EUR\\nGesamtpreis: %s EUR\\nZahlungsabwicklung: %s\\nPlattformrolle: Benjamin Fritz – DUELVANTA vermittelt den Vertrag; DUELVANTA ist nicht Verkäufer der Ware.',
    v_order.order_number,to_char(coalesce(new.accepted_at,now()) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    upper(v_type),v_buyer_type,v_seller->>'role_label',coalesce(v_seller->>'business_name',v_seller->>'legal_name'),
    v_seller->>'street_line1',v_seller->>'postal_code',v_seller->>'city',v_seller->>'country_code',
    v_product->>'title',v_qty,to_char(v_unit,'FM999999990.00'),to_char(v_goods,'FM999999990.00'),
    v_shipping_label,to_char(v_shipping,'FM999999990.00'),to_char(v_total,'FM999999990.00'),v_payment_text
  );
  insert into dv_market_private.market_contract_snapshots(
    deal_id,order_id,listing_id,offer_id,seller_id,buyer_id,seller_type,buyer_type,contract_classification,
    seller_party,platform_operator,product_snapshot,quantity,unit_price,goods_total,
    shipping_method,shipping_cost,total_price,currency,payment_provider,contract_formed_at,
    snapshot_version,withdrawal_eligible,confirmation_text,content_sha256
  ) values(
    new.id,new.order_id,new.listing_id,new.offer_id,new.seller_id,new.buyer_id,v_seller->>'seller_type',v_buyer_type,v_type,
    v_seller,jsonb_build_object('role','Marketplace-Vermittler','name','Benjamin Fritz – DUELVANTA',
      'street_line1','Landhausstraße 12','postal_code','75399','city','Unterreichenbach','country_code','DE','email','info@duelvanta.de'),
    v_product,v_qty,v_unit,v_goods,new.shipping_method,v_shipping,v_total,'EUR',new.payment_provider,coalesce(new.accepted_at,now()),
    'checkout-contract-v2',v_type='b2c',v_text,digest(convert_to(v_text,'UTF8'),'sha256')
  ) returning id into v_snapshot;
  insert into dv_market_private.marketplace_message_outbox(
    contract_snapshot_id,recipient_kind,recipient_user_id,message_kind,payload,dedupe_key
  ) values(
    v_snapshot,'buyer',new.buyer_id,'order_confirmation',
    jsonb_build_object('snapshot_id',v_snapshot,'order_id',new.order_id,'order_number',v_order.order_number,
      'document_sha256',(select encode(content_sha256,'hex') from dv_market_private.market_contract_snapshots where id=v_snapshot)),
    'order_confirmation:'||v_snapshot::text
  ) on conflict(dedupe_key) do nothing;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.create_market_swap_revision(p_thread_id uuid, p_proposed_by uuid, p_party_a_listing_ids uuid[], p_party_b_listing_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_thread dv_market_private.market_swap_threads%rowtype;
  v_revision_id uuid:=gen_random_uuid();
  v_revision_no integer;
  v_a_count integer;
  v_b_count integer;
  v_a_items jsonb;
  v_b_items jsonb;
  v_content jsonb;
  v_hash bytea;
  v_item jsonb;
begin
  select * into v_thread from dv_market_private.market_swap_threads where id=p_thread_id for update;
  if not found or v_thread.status<>'negotiating' then raise exception 'swap_not_negotiable';end if;
  if p_proposed_by not in (v_thread.party_a_id,v_thread.party_b_id) then raise exception 'swap_not_participant';end if;
  if v_thread.fulfillment_mode not in ('shipping','pickup') then raise exception 'swap_fulfillment_mode_invalid';end if;
  if p_party_a_listing_ids is null or cardinality(p_party_a_listing_ids) not between 1 and 20
     or p_party_b_listing_ids is null or cardinality(p_party_b_listing_ids) not between 1 and 20 then raise exception 'swap_item_count_invalid';end if;
  if (select count(*) from unnest(p_party_a_listing_ids) x)<>(select count(distinct x) from unnest(p_party_a_listing_ids) x)
     or (select count(*) from unnest(p_party_b_listing_ids) x)<>(select count(distinct x) from unnest(p_party_b_listing_ids) x)
     or p_party_a_listing_ids && p_party_b_listing_ids then raise exception 'swap_duplicate_listing';end if;

  perform dv_market_private.require_private_c2c_user(v_thread.party_a_id);
  perform dv_market_private.require_private_c2c_user(v_thread.party_b_id);

  select count(*),coalesce(jsonb_agg(jsonb_build_object(
    'listing_id',l.id,'owner_id',l.seller_id,'quantity',1,'listing_type',l.listing_type,
    'tcg',l.tcg,'card_name',l.card_name,'set_name',l.set_name,'card_number',l.card_number,
    'language',l.language,'variant',l.variant,'condition',l.condition,
    'grading_company',l.grading_company,'grade',l.grade,'asking_price',l.asking_price,
    'market_price_snapshot',l.market_price_snapshot,'published_at',l.published_at,'listing_updated_at',l.updated_at
  ) order by l.id),'[]'::jsonb)
  into v_a_count,v_a_items
  from public.market_listings l
  where l.id=any(p_party_a_listing_ids) and l.seller_id=v_thread.party_a_id
    and l.listing_type in ('trade','sale_or_trade') and l.status='active' and coalesce(l.quantity_available,0)>=1;

  select count(*),coalesce(jsonb_agg(jsonb_build_object(
    'listing_id',l.id,'owner_id',l.seller_id,'quantity',1,'listing_type',l.listing_type,
    'tcg',l.tcg,'card_name',l.card_name,'set_name',l.set_name,'card_number',l.card_number,
    'language',l.language,'variant',l.variant,'condition',l.condition,
    'grading_company',l.grading_company,'grade',l.grade,'asking_price',l.asking_price,
    'market_price_snapshot',l.market_price_snapshot,'published_at',l.published_at,'listing_updated_at',l.updated_at
  ) order by l.id),'[]'::jsonb)
  into v_b_count,v_b_items
  from public.market_listings l
  where l.id=any(p_party_b_listing_ids) and l.seller_id=v_thread.party_b_id
    and l.listing_type in ('trade','sale_or_trade') and l.status='active' and coalesce(l.quantity_available,0)>=1;

  if v_a_count<>cardinality(p_party_a_listing_ids) or v_b_count<>cardinality(p_party_b_listing_ids) then
    raise exception 'swap_listing_unavailable_or_not_owned';
  end if;

  select coalesce(max(revision_no),0)+1 into v_revision_no from dv_market_private.market_swap_revisions where thread_id=v_thread.id;
  v_content:=jsonb_build_object(
    'schema_version','c2c-swap-revision-v2','thread_id',v_thread.id,
    'party_a_id',v_thread.party_a_id,'party_b_id',v_thread.party_b_id,
    'fulfillment_mode',v_thread.fulfillment_mode,
    'revision_no',v_revision_no,'party_a_items',v_a_items,'party_b_items',v_b_items
  );
  v_hash:=extensions.digest(pg_catalog.convert_to(v_content::text,'UTF8'),'sha256');

  insert into dv_market_private.market_swap_revisions(id,thread_id,revision_no,proposed_by,content_sha256,fulfillment_mode)
  values(v_revision_id,v_thread.id,v_revision_no,p_proposed_by,v_hash,v_thread.fulfillment_mode);

  for v_item in select value from jsonb_array_elements(v_a_items) loop
    insert into dv_market_private.market_swap_revision_items(
      thread_id,revision_id,party_side,owner_id,listing_id,quantity,item_snapshot,reference_value_eur,reference_value_source,item_sha256
    ) values(
      v_thread.id,v_revision_id,'a',v_thread.party_a_id,(v_item->>'listing_id')::uuid,1,v_item,
      case when nullif(v_item->>'market_price_snapshot','') is null then null else round((v_item->>'market_price_snapshot')::numeric,2) end,
      case when nullif(v_item->>'market_price_snapshot','') is null then 'unavailable' else 'listing_market_price_snapshot' end,
      extensions.digest(pg_catalog.convert_to(v_item::text,'UTF8'),'sha256')
    );
  end loop;
  for v_item in select value from jsonb_array_elements(v_b_items) loop
    insert into dv_market_private.market_swap_revision_items(
      thread_id,revision_id,party_side,owner_id,listing_id,quantity,item_snapshot,reference_value_eur,reference_value_source,item_sha256
    ) values(
      v_thread.id,v_revision_id,'b',v_thread.party_b_id,(v_item->>'listing_id')::uuid,1,v_item,
      case when nullif(v_item->>'market_price_snapshot','') is null then null else round((v_item->>'market_price_snapshot')::numeric,2) end,
      case when nullif(v_item->>'market_price_snapshot','') is null then 'unavailable' else 'listing_market_price_snapshot' end,
      extensions.digest(pg_catalog.convert_to(v_item::text,'UTF8'),'sha256')
    );
  end loop;
  update dv_market_private.market_swap_threads set current_revision_id=v_revision_id,updated_at=now() where id=v_thread.id;
  return v_revision_id;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.d4_image_write_allowed(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h timestamptz;
begin
 if p_bucket not in ('profile-avatars','collection-cards') then return true; end if;
 if auth.uid() is null or split_part(p_name,'/',1)<>auth.uid()::text then return false; end if;
 select data_processing_restricted_at into h from public.profiles where id=auth.uid() for no key update;
 return found and h is null;
end$function$

CREATE OR REPLACE FUNCTION dv_market_private.d4_protect_collection_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid; held timestamptz; owners uuid[];
begin
 owners:=array[new.user_id];
 if tg_op='UPDATE' then owners:=owners||old.user_id; end if;
 for u in select p.id from public.profiles p where p.id=any(owners) order by p.id loop
  select p.data_processing_restricted_at into held from public.profiles p where p.id=u for no key update;
  if held is not null then raise exception 'account_publication_processing_restricted' using errcode='42501'; end if;
 end loop;
 return new;
end$function$

CREATE OR REPLACE FUNCTION dv_market_private.d4_protect_public_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if pg_catalog.has_schema_privilege('dv_market_private','USAGE') then
  if dv_market_private.l1_profile_reduction_allowed(old,new) then return new;end if;
 end if;
 if old.data_processing_restricted_at is not null or new.data_processing_restricted_at is not null then
  if row(new.username,new.display_name,new.avatar_path,new.founder_number,new.founder_generation,new.founder_since,new.created_at)
     is distinct from row(old.username,old.display_name,old.avatar_path,old.founder_number,old.founder_generation,old.founder_since,old.created_at)
     or (new.collection_visibility is distinct from old.collection_visibility
         and not (new.collection_visibility='private' or
                  (old.collection_visibility='public' and new.collection_visibility='custom')))
     or (old.account_status in ('suspended','deleted') and
         new.account_status is distinct from old.account_status and new.account_status not in ('suspended','deleted')) then
   raise exception 'account_publication_processing_restricted' using errcode='42501';
  end if;
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION dv_market_private.enforce_sale_only_listing()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.listing_type is distinct from 'sale' then
    if tg_op='INSERT' then
      raise exception 'market_sale_only' using errcode='23514';
    elsif new.listing_type is distinct from old.listing_type then
      raise exception 'market_sale_only' using errcode='23514';
    elsif new.listing_type='trade' and new.status in ('active','reserved') and new.status is distinct from old.status then
      raise exception 'market_swaps_retired' using errcode='23514';
    end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.enforce_sale_only_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.offer_type not in ('price','fixed_price') or exists(
    select 1 from public.market_listings where id=new.listing_id and listing_type='trade'
  ) then
    if tg_op='UPDATE' and new.status in ('withdrawn','declined','expired','cancelled') then return new;end if;
    raise exception 'market_swaps_retired' using errcode='23514';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.guard_market_listing_seller_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare
  v_enforced boolean;
begin
  if new.status <> 'active' then
    return new;
  end if;

  select seller_onboarding_enforced into v_enforced
  from dv_market_private.marketplace_compliance_policy
  where singleton = true;

  if not coalesce(v_enforced, false) then
    return new;
  end if;

  if not exists (
    select 1
    from public.market_seller_accounts a
    where a.seller_id = new.seller_id
      and a.onboarding_status = 'active'
      and a.seller_type in ('private','trader')
  ) then
    if tg_op='INSERT' then
      raise exception 'seller_onboarding_required';
    end if;
    new.status := 'paused';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.keep_moderated_listing_paused()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
begin
  if new.status='active' and exists(
    select 1 from dv_market_private.listing_notices n
    where n.listing_id=new.id and n.status in ('decided_restricted','decided_removed','appealed')
  ) then
    new.status:='paused';
    new.updated_at:=now();
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.require_pickup_message_context(p_context_type text, p_context_id uuid, p_user_id uuid, p_for_write boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_swap dv_market_private.market_swap_threads%rowtype;
  v_order record;
  v_other uuid;
  v_can_send boolean:=false;
begin
  if p_user_id is null then raise exception 'not_authenticated';end if;
  if p_context_type not in ('swap','order') or p_context_id is null then
    raise exception 'pickup_message_context_invalid';
  end if;

  if p_context_type='swap' then
    select * into v_swap from dv_market_private.market_swap_threads where id=p_context_id;
    if not found or p_user_id not in (v_swap.party_a_id,v_swap.party_b_id) then
      raise exception 'pickup_message_not_participant';
    end if;
    if v_swap.fulfillment_mode<>'pickup' then raise exception 'pickup_message_not_pickup';end if;
    v_other:=case when p_user_id=v_swap.party_a_id then v_swap.party_b_id else v_swap.party_a_id end;
    v_can_send:=v_swap.status='bound';
  else
    select o.seller_id,o.buyer_id,o.fulfillment_group,o.status
    into v_order
    from public.market_orders o
    where o.id=p_context_id;
    if not found or p_user_id not in (v_order.seller_id,v_order.buyer_id) then
      raise exception 'pickup_message_not_participant';
    end if;
    if v_order.fulfillment_group<>'pickup' then raise exception 'pickup_message_not_pickup';end if;
    v_other:=case when p_user_id=v_order.seller_id then v_order.buyer_id else v_order.seller_id end;
    v_can_send:=v_order.status not in ('completed','cancelled','disputed');
  end if;

  if p_for_write and not v_can_send then raise exception 'pickup_message_context_read_only';end if;
  return jsonb_build_object('other_user_id',v_other,'can_send',v_can_send);
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.require_private_c2c_user(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_account public.market_seller_accounts%rowtype;
begin
  perform dv_market_private.require_trade_eligibility(p_user_id,false);
  select * into v_account from public.market_seller_accounts where seller_id=p_user_id;
  if not found or v_account.seller_type<>'private' or v_account.onboarding_status<>'active' or v_account.country_code<>'DE' then
    raise exception 'c2c_private_seller_required';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION dv_market_private.require_trade_eligibility(p_user_id uuid, p_require_private_buyer boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_row dv_market_private.trade_user_eligibility%rowtype;
begin
  if p_user_id is null then raise exception 'trade_user_missing'; end if;
  select * into v_row from dv_market_private.trade_user_eligibility where user_id=p_user_id;
  if v_row.user_id is null
     or v_row.residence_country_code <> 'DE'
     or v_row.date_of_birth > current_date - interval '18 years'
     or v_row.date_of_birth < current_date - interval '120 years' then
    raise exception 'trade_eligibility_required';
  end if;
  if p_require_private_buyer and not v_row.private_buyer_confirmed then
    raise exception 'buyer_private_consumer_required';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION dv_v16_private.openai_scan_budget_for_caller()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p dv_v16_private.openai_scan_policy%rowtype;
  u dv_v16_private.openai_weekly_usage%rowtype;
  w date:=dv_v16_private.week_start_at(now());
  m date:=(date_trunc('month',now() at time zone 'Europe/Berlin'))::date;
  c dv_v16_private.openai_monthly_cost%rowtype;
  v_enabled boolean;
  v_restricted timestamptz;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'authentication required'; end if;
  select * into p from dv_v16_private.openai_scan_policy where singleton;
  if not exists(select 1 from public.profiles where id=auth.uid() and account_status in ('active','beta')) then raise exception 'active account required'; end if;
  select * into u from dv_v16_private.openai_weekly_usage where user_id=auth.uid() and week_start=w;
  select * into c from dv_v16_private.openai_monthly_cost where period_start=m;
  select data_processing_restricted_at into v_restricted from public.profiles where id=auth.uid();
  v_enabled:=v_restricted is null and coalesce(p.enabled,false) and p.accounting_key_sha256 is not null and
    coalesce(c.settled_eur_micros,0)+coalesce(c.reserved_eur_micros,0)+p.reservation_eur_micros<=p.monthly_budget_eur_micros;
  return jsonb_build_object('provider','openai','enabled',v_enabled,'processingRestricted',v_restricted is not null,
    'remaining',case when v_enabled then greatest(0,p.raw_weekly_limit-coalesce(u.raw_used,0)) else 0 end,
    'slabRemaining',case when v_enabled then greatest(0,p.slab_weekly_limit-coalesce(u.slab_used,0)) else 0 end,
    'rawLimit',p.raw_weekly_limit,'slabLimit',p.slab_weekly_limit,
    'resetsAt',(w+7)::timestamp at time zone 'Europe/Berlin',
    'monthlyBudgetEurMicros',p.monthly_budget_eur_micros,
    'monthlyCommittedEurMicros',coalesce(c.settled_eur_micros,0)+coalesce(c.reserved_eur_micros,0),
    'monthlyRemainingEurMicros',greatest(0,p.monthly_budget_eur_micros-coalesce(c.settled_eur_micros,0)-coalesce(c.reserved_eur_micros,0)),
    'budgetResetsAt',(m+interval '1 month')::timestamp at time zone 'Europe/Berlin');
end $function$

CREATE OR REPLACE FUNCTION dv_v16_private.owner_openai_scan_settings_for_caller()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p dv_v16_private.openai_scan_policy%rowtype;
  w date:=dv_v16_private.week_start_at(now());
  m date:=(date_trunc('month',now() at time zone 'Europe/Berlin'))::date;
  v_raw_used bigint:=0; v_slab_used bigint:=0; v_users bigint:=0;
  c dv_v16_private.openai_monthly_cost%rowtype;
begin perform public.require_duelvanta_privileged_session();
  if not dv_v16_private.is_owner_caller() then raise exception 'owner access required'; end if;
  select * into p from dv_v16_private.openai_scan_policy where singleton;
  select coalesce(sum(raw_used),0),coalesce(sum(slab_used),0),count(*)
    into v_raw_used,v_slab_used,v_users from dv_v16_private.openai_weekly_usage where week_start=w;
  select * into c from dv_v16_private.openai_monthly_cost where period_start=m;
  return jsonb_build_object('provider','openai','enabled',coalesce(p.enabled,false),
    'effectiveEnabled',coalesce(p.enabled,false) and p.accounting_key_sha256 is not null and
      coalesce(c.settled_eur_micros,0)+coalesce(c.reserved_eur_micros,0)+p.reservation_eur_micros<=p.monthly_budget_eur_micros,
    'rawLimit',coalesce(p.raw_weekly_limit,0),
    'slabLimit',coalesce(p.slab_weekly_limit,0),'maxRawLimit',50,'maxSlabLimit',10,
    'weekStart',w,'weeklyRawUsed',v_raw_used,'weeklySlabUsed',v_slab_used,'weeklyUsers',v_users,
    'monthlyBudgetEurMicros',p.monthly_budget_eur_micros,'maxMonthlyBudgetEurCents',25000,
    'monthlyEstimatedEurMicros',coalesce(c.settled_eur_micros,0),
    'monthlyReservedEurMicros',coalesce(c.reserved_eur_micros,0),
    'monthlyRemainingEurMicros',greatest(0,p.monthly_budget_eur_micros-coalesce(c.settled_eur_micros,0)-coalesce(c.reserved_eur_micros,0)),
    'monthlyEstimatedUsdMicros',coalesce(c.estimated_usd_micros,0),
    'monthlyInputTokens',coalesce(c.input_tokens,0),'monthlyOutputTokens',coalesce(c.output_tokens,0),
    'monthlySuccessfulScans',coalesce(c.successful_scans,0),'budgetPeriodStart',m,
    'budgetResetsAt',(m+interval '1 month')::timestamp at time zone 'Europe/Berlin',
    'accountingReady',p.accounting_key_sha256 is not null,
    'trackingStartedAt',p.tracking_started_at,'legacyUnclassifiedAttempts',p.legacy_unclassified_attempts,
    'eurPerUsdMicros',p.eur_per_usd_micros,'fxDate',p.fx_date,
    'historicalImportedScans',(select coalesce(sum(successful_scans),0) from dv_v16_private.openai_cost_import where period_start=m));
end $function$

CREATE OR REPLACE FUNCTION dv_v16_private.require_openai_server()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_expected text;
  v_headers jsonb:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
  v_key text;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then
    raise exception 'authentication required';
  end if;
  v_key:=coalesce(v_headers->>'x-dv-accounting-key','');
  select accounting_key_sha256 into v_expected from dv_v16_private.openai_scan_policy where singleton;
  if length(v_key)<32 or v_expected is null or
    encode(sha256(convert_to(v_key,'UTF8')),'hex')<>v_expected then
    raise exception 'server accounting authorization required';
  end if;
end $function$

CREATE OR REPLACE FUNCTION dv_v16_private.reserve_for_caller(p_request_id uuid, p_image_sha256 text, p_tcg text, p_kind text DEFAULT 'raw'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p dv_v16_private.scan_policy%rowtype; b dv_v16_private.credit_period%rowtype;
 u dv_v16_private.weekly_usage%rowtype; w date:=dv_v16_private.week_start_at(now()); cost integer;
begin
 if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'authentication required'; end if;
 if p_request_id is null or p_image_sha256 is null or p_image_sha256 !~ '^[a-f0-9]{64}$' or p_tcg is null or p_tcg not in ('pokemon','one_piece') or p_kind is null or p_kind not in ('raw','slab') then raise exception 'invalid reservation'; end if;
 -- Serialize on central policy, including policy reductions and all users. Small
 -- beta volume; global credit checks and weekly counters commit atomically.
 select * into p from dv_v16_private.scan_policy where singleton for update;
 if not found or not p.enabled then return jsonb_build_object('allowed',false,'reason','closed'); end if;
 select * into b from dv_v16_private.credit_period where active and now()>=starts_at and now()<ends_at for update;
 if not found then return jsonb_build_object('allowed',false,'reason','closed'); end if;
 if exists(select 1 from dv_v16_private.scan_reservation where user_id=auth.uid() and
   (request_id=p_request_id or (period_id=b.id and image_sha256=p_image_sha256 and tcg=p_tcg and kind=p_kind))) then
   return jsonb_build_object('allowed',false,'reason','duplicate'); end if;
 cost:=case when p_kind='raw' then 10 else 15 end;
 if b.prior_credits+b.reserved_credits+cost>b.credit_limit then return jsonb_build_object('allowed',false,'reason','global_limit'); end if;
 insert into dv_v16_private.weekly_usage(user_id,week_start) values(auth.uid(),w) on conflict do nothing;
 select * into u from dv_v16_private.weekly_usage where user_id=auth.uid() and week_start=w for update;
 if (p_kind='raw' and u.raw_used>=p.raw_weekly_limit) or (p_kind='slab' and u.slab_used>=p.slab_weekly_limit) then return jsonb_build_object('allowed',false,'reason','weekly_limit'); end if;
 insert into dv_v16_private.scan_reservation(user_id,request_id,period_id,week_start,image_sha256,tcg,kind,credits)
 values(auth.uid(),p_request_id,b.id,w,p_image_sha256,p_tcg,p_kind,cost);
 update dv_v16_private.weekly_usage set raw_used=raw_used+case when p_kind='raw' then 1 else 0 end,
   slab_used=slab_used+case when p_kind='slab' then 1 else 0 end where user_id=auth.uid() and week_start=w;
 update dv_v16_private.credit_period set reserved_credits=reserved_credits+cost where id=b.id;
 return dv_v16_private.scan_budget_for_caller()||jsonb_build_object('allowed',true,'reservedCredits',cost);
end $function$

CREATE OR REPLACE FUNCTION dv_v16_private.reserve_openai_for_caller(p_request_id uuid, p_image_sha256 text, p_tcg text, p_kind text DEFAULT 'raw'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p dv_v16_private.openai_scan_policy%rowtype;
  u dv_v16_private.openai_weekly_usage%rowtype;
  w date:=dv_v16_private.week_start_at(now());
  m date:=(date_trunc('month',now() at time zone 'Europe/Berlin'))::date;
  c dv_v16_private.openai_monthly_cost%rowtype;
  v_restricted timestamptz;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'authentication required'; end if;
  if p_request_id is null or p_image_sha256 is null or p_image_sha256 !~ '^[a-f0-9]{64}$'
    or p_tcg is null or p_kind is null
    or p_tcg not in ('pokemon','one_piece') or p_kind not in ('raw','slab') then raise exception 'invalid reservation'; end if;
  select * into p from dv_v16_private.openai_scan_policy where singleton for update;
  if not found or not p.enabled or p.accounting_key_sha256 is null then return jsonb_build_object('allowed',false,'reason','closed'); end if;
  perform dv_v16_private.require_openai_server();
  -- Serialize admission with the existing profile Hold/Closure writer.
  select data_processing_restricted_at into v_restricted from public.profiles
    where id=auth.uid() and account_status in ('active','beta') for share;
  if not found then raise exception 'active account required'; end if;
  if v_restricted is not null then
    return jsonb_build_object('allowed',false,'reason','account_data_processing_restricted');
  end if;
  insert into dv_v16_private.openai_monthly_cost(period_start) values(m) on conflict do nothing;
  select * into c from dv_v16_private.openai_monthly_cost where period_start=m for update;
  if c.settled_eur_micros+c.reserved_eur_micros+p.reservation_eur_micros > p.monthly_budget_eur_micros then
    return jsonb_build_object('allowed',false,'reason','monthly_budget');
  end if;
  if exists(select 1 from dv_v16_private.openai_scan_reservation where user_id=auth.uid()
    and (request_id=p_request_id or (week_start=w and image_sha256=p_image_sha256 and tcg=p_tcg and kind=p_kind))) then
    return jsonb_build_object('allowed',false,'reason','duplicate');
  end if;
  insert into dv_v16_private.openai_weekly_usage(user_id,week_start) values(auth.uid(),w) on conflict do nothing;
  select * into u from dv_v16_private.openai_weekly_usage where user_id=auth.uid() and week_start=w for update;
  if (p_kind='raw' and u.raw_used>=p.raw_weekly_limit) or (p_kind='slab' and u.slab_used>=p.slab_weekly_limit) then
    return jsonb_build_object('allowed',false,'reason','weekly_limit');
  end if;
  insert into dv_v16_private.openai_scan_reservation(user_id,request_id,week_start,image_sha256,tcg,kind,reserved_eur_micros,eur_per_usd_micros)
  values(auth.uid(),p_request_id,w,p_image_sha256,p_tcg,p_kind,p.reservation_eur_micros,p.eur_per_usd_micros);
  update dv_v16_private.openai_monthly_cost set reserved_eur_micros=reserved_eur_micros+p.reservation_eur_micros
  where period_start=m;
  update dv_v16_private.openai_weekly_usage
  set raw_used=raw_used+case when p_kind='raw' then 1 else 0 end,
      slab_used=slab_used+case when p_kind='slab' then 1 else 0 end
  where user_id=auth.uid() and week_start=w;
  return dv_v16_private.openai_scan_budget_for_caller()||jsonb_build_object('allowed',true,'eurPerUsdMicros',p.eur_per_usd_micros);
end $function$

CREATE OR REPLACE FUNCTION dv_v16_private.scan_budget_for_caller()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p dv_v16_private.scan_policy%rowtype; b dv_v16_private.credit_period%rowtype;
 u dv_v16_private.weekly_usage%rowtype; w date:=dv_v16_private.week_start_at(now()); live boolean;
begin
 if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'authentication required'; end if;
 select * into p from dv_v16_private.scan_policy where singleton;
 select * into b from dv_v16_private.credit_period where active and now()>=starts_at and now()<ends_at;
 select * into u from dv_v16_private.weekly_usage where user_id=auth.uid() and week_start=w;
 live:=coalesce(p.enabled and b.id is not null,false);
 return jsonb_build_object('enabled',live,
   'remaining',case when live then greatest(0,least(p.raw_weekly_limit-coalesce(u.raw_used,0),(b.credit_limit-b.prior_credits-b.reserved_credits)/10)) else 0 end,
   'slabRemaining',case when live then greatest(0,least(p.slab_weekly_limit-coalesce(u.slab_used,0),(b.credit_limit-b.prior_credits-b.reserved_credits)/15)) else 0 end,
   'rawLimit',p.raw_weekly_limit,'slabLimit',p.slab_weekly_limit,
   'resetsAt',(w+7)::timestamp at time zone 'Europe/Berlin');
end $function$

CREATE OR REPLACE FUNCTION dv_v16_private.settle_openai_for_caller(p_request_id uuid, p_input_tokens integer, p_output_tokens integer, p_estimated_cost_eur_micros bigint, p_estimated_cost_usd_micros bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r dv_v16_private.openai_scan_reservation%rowtype;
  m date;
  p dv_v16_private.openai_scan_policy%rowtype;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'authentication required'; end if;
  if p_request_id is null or p_input_tokens is null or p_output_tokens is null
    or p_estimated_cost_eur_micros is null or p_estimated_cost_usd_micros is null
    or p_input_tokens not between 0 and 1000000 or p_output_tokens not between 0 and 100000
    or p_estimated_cost_eur_micros not between 0 and 1000000 or p_estimated_cost_usd_micros not between 0 and 1000000
    then raise exception 'invalid OpenAI settlement'; end if;
  -- Share a consistent lock order with reserve/update to prevent settlement
  -- racing a policy change or a duplicate reservation.
  select * into p from dv_v16_private.openai_scan_policy where singleton for update;
  perform dv_v16_private.require_openai_server();
  select * into r from dv_v16_private.openai_scan_reservation
    where user_id=auth.uid() and request_id=p_request_id for update;
  if not found then raise exception 'reservation not found'; end if;
  m:=(date_trunc('month',r.reserved_at at time zone 'Europe/Berlin'))::date;
  if r.settled_at is not null then return jsonb_build_object('settled',true,'duplicate',true); end if;
  if p_estimated_cost_eur_micros<>ceil(p_estimated_cost_usd_micros::numeric*r.eur_per_usd_micros/1000000) then raise exception 'invalid currency conversion'; end if;
  if p_estimated_cost_eur_micros > r.reserved_eur_micros then raise exception 'cost exceeds reservation'; end if;
  update dv_v16_private.openai_scan_reservation set estimated_cost_eur_micros=p_estimated_cost_eur_micros,
    estimated_cost_usd_micros=p_estimated_cost_usd_micros,input_tokens=p_input_tokens,
    output_tokens=p_output_tokens,settled_at=now() where user_id=auth.uid() and request_id=p_request_id;
  update dv_v16_private.openai_monthly_cost set
    reserved_eur_micros=reserved_eur_micros-r.reserved_eur_micros,
    settled_eur_micros=settled_eur_micros+p_estimated_cost_eur_micros,
    estimated_usd_micros=estimated_usd_micros+p_estimated_cost_usd_micros,
    input_tokens=input_tokens+p_input_tokens,output_tokens=output_tokens+p_output_tokens,
    successful_scans=successful_scans+1 where period_start=m;
  if not found then raise exception 'accounting period missing'; end if;
  return jsonb_build_object('settled',true,'duplicate',false);
end $function$

CREATE OR REPLACE FUNCTION dv_v16_private.update_openai_scan_policy_for_caller(p_enabled boolean, p_raw_weekly_limit integer, p_slab_weekly_limit integer, p_monthly_budget_eur_cents integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();

 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((false),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();


declare v_before jsonb;
begin perform public.require_duelvanta_privileged_session();
  if not dv_v16_private.is_owner_caller() then raise exception 'owner access required'; end if;
  if p_enabled is null or p_raw_weekly_limit is null or p_slab_weekly_limit is null or p_monthly_budget_eur_cents is null
    or p_raw_weekly_limit not between 0 and 50 or p_slab_weekly_limit not between 0 and 10
    or p_monthly_budget_eur_cents not between 0 and 25000 then raise exception 'invalid OpenAI scanner policy'; end if;
  select jsonb_build_object('enabled',enabled,'rawLimit',raw_weekly_limit,'slabLimit',slab_weekly_limit,
    'monthlyBudgetEurMicros',monthly_budget_eur_micros)
    into v_before from dv_v16_private.openai_scan_policy where singleton for update;
  update dv_v16_private.openai_scan_policy set enabled=p_enabled,
    raw_weekly_limit=p_raw_weekly_limit,slab_weekly_limit=p_slab_weekly_limit,
    monthly_budget_eur_micros=p_monthly_budget_eur_cents::bigint*10000 where singleton;
  insert into public.admin_audit_log(actor_id,target_user_id,action,details)
  values(auth.uid(),auth.uid(),'scanner_v16_openai_policy_updated',jsonb_build_object(
    'provider','openai','before',v_before,'after',jsonb_build_object(
      'enabled',p_enabled,'rawLimit',p_raw_weekly_limit,'slabLimit',p_slab_weekly_limit,
      'monthlyBudgetEurMicros',p_monthly_budget_eur_cents::bigint*10000)));
  return dv_v16_private.owner_openai_scan_settings_for_caller();
end;
end
$function$

CREATE OR REPLACE FUNCTION public.accept_fixed_price_market_offer_v1(p_offer_id uuid, p_attempt_id uuid, p_session_id text, p_payment_requested_at timestamp with time zone, p_live_mode boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  o public.market_offers;l public.market_listings;d public.market_deals;s dv_market_private.market_stripe_accounts%rowtype;
  c dv_market_private.market_payment_configuration%rowtype;snap dv_market_private.market_contract_snapshots%rowtype;
  v_total integer;v_fee integer;v_prefix text:=case when p_live_mode then 'cs_live_' else 'cs_test_' end;
  v_review jsonb;v_f jsonb;v_hash text;v_qty integer;v_listing_id uuid;
begin
  if p_offer_id is null or p_attempt_id is null or p_payment_requested_at is null then raise exception 'fixed_acceptance_invalid'; end if;
  if p_session_id is null or position(v_prefix in p_session_id)<>1 then raise exception 'stripe_session_invalid'; end if;
  if p_payment_requested_at<now()-interval '15 minutes' or p_payment_requested_at>now()+interval '2 minutes' then
    raise exception 'payment_request_timestamp_invalid';
  end if;

  select listing_id into v_listing_id from public.market_offers where id=p_offer_id;
  select * into l from public.market_listings where id=v_listing_id for update;
  if not found then raise exception 'listing_not_available'; end if;
  select * into o from public.market_offers where id=p_offer_id for update;
  if not found or o.listing_id is distinct from l.id or o.offer_type<>'fixed_price' or o.payment_attempt_id<>p_attempt_id then raise exception 'fixed_offer_not_found'; end if;

  if o.payment_live_mode_snapshot is distinct from p_live_mode
     or o.stripe_account_id_snapshot is null
     or o.amount_due_cents_snapshot is null or o.amount_due_cents_snapshot<=0
     or o.platform_fee_cents_snapshot is null or o.platform_fee_cents_snapshot<0
     or o.platform_fee_cents_snapshot>o.amount_due_cents_snapshot
     or o.contract_review_snapshot is null or o.contract_review_snapshot->>'snapshot_version'<>'checkout-contract-v2'
     or o.checkout_hash_snapshot is null then raise exception 'fixed_checkout_snapshot_invalid'; end if;
  v_review:=o.contract_review_snapshot;
  v_hash:=encode(digest(convert_to(v_review::text,'UTF8'),'sha256'),'hex');
  if v_hash<>o.checkout_hash_snapshot
     or (v_review->>'listing_id')::uuid<>o.listing_id
     or (v_review->>'seller_id')::uuid<>o.seller_id
     or (v_review->>'quantity')::integer<>o.requested_quantity
     or v_review->>'buyer_type'<>'consumer'
     or v_review->>'contract_classification' not in ('c2c','b2c')
     or jsonb_typeof(v_review->'seller_party')<>'object'
     or jsonb_typeof(v_review->'product')<>'object'
     or jsonb_typeof(v_review->'fulfillment_snapshot')<>'object'
     or nullif(v_review->'fulfillment_snapshot'->>'product_kind','') is null
     or v_review->>'currency'<>'EUR'
     or v_review->>'payment_provider'<>'stripe_connect'
     or round((v_review->>'goods_total')::numeric,2)<>round(o.amount,2)
     or round((v_review->>'total_price')::numeric*100)::integer<>o.amount_due_cents_snapshot then
    raise exception 'fixed_checkout_snapshot_invalid';
  end if;

  if o.status='accepted' then
    select * into d from public.market_deals where offer_id=o.id;
    select * into snap from dv_market_private.market_contract_snapshots where deal_id=d.id;
    if d.id is null or snap.id is null or o.stripe_checkout_session_id<>p_session_id then raise exception 'fixed_acceptance_conflict'; end if;
    return jsonb_build_object('replayed',true,'deal_id',d.id,'order_id',d.order_id,'contract_snapshot_id',snap.id,'contract_classification',snap.contract_classification);
  end if;
  if o.status<>'pending' or o.reservation_expires_at is null or o.reservation_expires_at<=now() then raise exception 'fixed_offer_expired'; end if;

  perform dv_market_private.require_market_buyer_type(o.buyer_id);
  if o.buyer_type_snapshot is distinct from 'consumer' then raise exception 'buyer_snapshot_invalid'; end if;

  if o.reserved_quantity is distinct from o.requested_quantity or o.reserved_quantity<=0 then
    raise exception 'market_reservation_inventory_inconsistent';
  end if;
  select * into s from dv_market_private.market_stripe_accounts where seller_id=o.seller_id;
  if not found or s.stripe_account_id<>o.stripe_account_id_snapshot
     or s.live_mode is distinct from p_live_mode or s.onboarding_status<>'ready' or not s.charges_enabled then
    raise exception 'stripe_seller_not_ready';
  end if;
  select * into c from dv_market_private.market_payment_configuration where singleton;
  if not found then raise exception 'stripe_payment_configuration_missing'; end if;
  if p_live_mode then
    if not c.live_mode then raise exception 'stripe_live_database_disabled'; end if;
  else
    if c.live_mode or not c.sandbox_enabled then raise exception 'stripe_sandbox_disabled'; end if;
  end if;

  v_total:=round((v_review->>'total_price')::numeric*100)::integer;
  v_fee:=o.platform_fee_cents_snapshot;
  if v_total<>o.amount_due_cents_snapshot then raise exception 'fixed_checkout_amount_mismatch'; end if;
  v_qty:=greatest(coalesce(o.requested_quantity,1),1);
  v_f:=coalesce(v_review->'fulfillment_snapshot','{}'::jsonb);

  perform set_config('dv_market.offer_checkout_authorized',o.id::text,true);
  update public.market_offers
  set status='accepted',responded_at=p_payment_requested_at,payment_requested_at=p_payment_requested_at,
      stripe_checkout_session_id=p_session_id,reserved_quantity=0,reservation_expires_at=null,updated_at=now()
  where id=o.id;

  insert into public.market_deals(
    listing_id,offer_id,seller_id,buyer_id,amount,currency,status,accepted_at,
    shipping_method,shipping_cost,shipping_note,product_kind,sealed_category,item_quantity,
    package_contents,weight_grams,length_mm,width_mm,height_mm,checkout_request_id,
    payment_provider,payment_status
  ) values(
    l.id,o.id,o.seller_id,o.buyer_id,(v_review->>'goods_total')::numeric,'EUR','accepted',p_payment_requested_at,
    v_review->>'shipping_method',(v_review->>'shipping_cost')::numeric,v_review->>'shipping_note',
    coalesce(v_f->>'product_kind',l.product_kind),v_f->>'sealed_category',v_qty,
    v_f->>'package_contents',
    case when nullif(v_f->>'weight_grams','') is null then null else (v_f->>'weight_grams')::integer*v_qty end,
    nullif(v_f->>'length_mm','')::integer,nullif(v_f->>'width_mm','')::integer,nullif(v_f->>'height_mm','')::integer,
    o.checkout_request_id,'stripe_connect','pending'
  ) on conflict (offer_id) do nothing
  returning * into d;

  if d.id is null then select * into d from public.market_deals where offer_id=o.id; end if;
  if d.id is null then raise exception 'fixed_contract_creation_failed'; end if;

  -- AFTER INSERT order attachment updates market_deals.order_id; reload the post-trigger row before payment evidence.
  select * into d from public.market_deals where id=d.id;
  if d.order_id is null then raise exception 'fixed_order_attachment_missing'; end if;

  select * into snap from dv_market_private.market_contract_snapshots where deal_id=d.id;
  if not found then raise exception 'checkout_snapshot_missing'; end if;
  if round(snap.total_price*100)::integer<>v_total
     or snap.seller_party is distinct from v_review->'seller_party'
     or snap.product_snapshot is distinct from v_review->'product'
     or snap.contract_classification is distinct from v_review->>'contract_classification' then
    raise exception 'fixed_contract_snapshot_mismatch';
  end if;

  insert into dv_market_private.market_payment_attempts(
    id,order_id,buyer_id,seller_id,stripe_account_id,idempotency_key,state,currency,
    amount_due_cents,platform_fee_cents,stripe_checkout_session_id,prepared_at,updated_at
  ) values(
    p_attempt_id,d.order_id,o.buyer_id,o.seller_id,o.stripe_account_id_snapshot,o.checkout_request_id,'session_created','EUR',
    v_total,v_fee,p_session_id,p_payment_requested_at,now()
  ) on conflict (id) do nothing;

  select * into s from dv_market_private.market_stripe_accounts where seller_id=o.seller_id;
  if not exists(
    select 1 from dv_market_private.market_payment_attempts a
    where a.id=p_attempt_id and a.order_id=d.order_id and a.stripe_account_id=o.stripe_account_id_snapshot
      and a.amount_due_cents=v_total and a.platform_fee_cents=v_fee and a.stripe_checkout_session_id=p_session_id
  ) then raise exception 'fixed_payment_attempt_conflict'; end if;

  insert into dv_market_private.market_payment_allocations(attempt_id,contract_snapshot_id,gross_cents,platform_fee_cents)
  values(p_attempt_id,snap.id,v_total,v_fee)
  on conflict (attempt_id,contract_snapshot_id) do nothing;

  update public.market_orders
  set payment_provider='stripe_connect',payment_status='pending',paid_amount=0,updated_at=now()
  where id=d.order_id;

  return jsonb_build_object(
    'replayed',false,'deal_id',d.id,'order_id',d.order_id,'contract_snapshot_id',snap.id,
    'contract_classification',snap.contract_classification,'confirmation_sha256',encode(snap.content_sha256,'hex')
  );
end
$function$

CREATE OR REPLACE FUNCTION public.activate_my_beta_account()
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.profiles%rowtype;
  w public.beta_waitlist%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select * into p from public.profiles where id = auth.uid();
  if not found then
    raise exception 'DUELVANTA profile not found';
  end if;

  select * into w
  from public.beta_waitlist
  where lower(email) = lower(p.email)
    and beta_status in ('invited','activated')
  order by created_at asc
  limit 1;

  if not found then
    raise exception 'Beta invitation required';
  end if;

  update public.beta_waitlist
  set beta_status = 'activated',
      activated_at = coalesce(activated_at, now())
  where id = w.id;

  update public.profiles
  set founder_number = case when w.founder_eligible then w.founder_number else founder_number end,
      founder_generation = case when w.founder_eligible then w.founder_generation else founder_generation end,
      founder_since = case when w.founder_eligible then coalesce(founder_since, now()) else founder_since end,
      updated_at = now()
  where id = auth.uid()
  returning * into p;

  return p;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_my_market_listing_image(p_listing_id uuid, p_storage_path text, p_sort_order integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l public.market_listings; v_id uuid; v_prefix text;
begin
  select * into l from public.market_listings where id=p_listing_id;
  if l.id is null or l.seller_id<>auth.uid() then raise exception 'Nicht erlaubt'; end if;
  if l.product_kind<>'sealed' then raise exception 'Nur für Sealed-Angebote'; end if;
  if l.status not in ('draft','active','paused') then raise exception 'Fotos können jetzt nicht geändert werden'; end if;
  if p_sort_order<0 or p_sort_order>5 then raise exception 'Maximal 6 Fotos'; end if;
  v_prefix:=auth.uid()::text||'/'||p_listing_id::text||'/';
  if p_storage_path not like v_prefix||'%' then raise exception 'Ungültiger Bildpfad'; end if;
  if (select count(*) from public.market_listing_images where listing_id=p_listing_id)>=6 then raise exception 'Maximal 6 Fotos'; end if;
  insert into public.market_listing_images(listing_id,seller_id,storage_path,sort_order) values(p_listing_id,auth.uid(),p_storage_path,p_sort_order) returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.apply_market_stripe_event(p_event_id text, p_event_type text, p_account_id text, p_live_mode boolean, p_object_id text, p_payload_sha256 text, p_provider_created_at timestamp with time zone, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare a dv_market_private.market_payment_attempts%rowtype;v_status text:='ignored';v_note text:='event_not_actionable';
  v_amount integer:=coalesce((p_data->>'amount_cents')::integer,0);r record;v_tax jsonb;
begin
  if p_event_id !~ '^evt_[A-Za-z0-9]+$' or p_live_mode or p_payload_sha256 !~ '^[a-f0-9]{64}$' then raise exception 'stripe_event_invalid'; end if;
  insert into dv_market_private.market_stripe_events(stripe_event_id,event_type,stripe_account_id,live_mode,object_id,payload_sha256,normalized_data,provider_created_at)
  values(p_event_id,p_event_type,p_account_id,false,p_object_id,decode(p_payload_sha256,'hex'),coalesce(p_data,'{}'),p_provider_created_at)
  on conflict(stripe_event_id) do nothing;
  if not found then return jsonb_build_object('event_id',p_event_id,'replayed',true); end if;

  if p_event_type='account.updated' then
    if p_object_id<>p_account_id then raise exception 'stripe_account_event_mismatch'; end if;
    update dv_market_private.market_stripe_accounts set
      charges_enabled=coalesce((p_data->>'charges_enabled')::boolean,false),
      payouts_enabled=coalesce((p_data->>'payouts_enabled')::boolean,false),
      details_submitted=coalesce((p_data->>'details_submitted')::boolean,false),
      requirements_due_count=greatest(coalesce((p_data->>'requirements_due_count')::integer,0),0),
      onboarding_status=case
        when nullif(p_data->>'disabled_reason','') is not null or coalesce((p_data->>'past_due_count')::integer,0)>0 then 'restricted'
        when coalesce((p_data->>'charges_enabled')::boolean,false) and coalesce((p_data->>'details_submitted')::boolean,false) then 'ready'
        when coalesce((p_data->>'requirements_due_count')::integer,0)>0 then 'requirements_due'
        else 'pending_review' end,
      provider_state_updated_at=coalesce(p_provider_created_at,now()),updated_at=now()
    where stripe_account_id=p_account_id and not live_mode;
    if not found then raise exception 'stripe_account_not_registered'; end if;
    update dv_market_private.market_stripe_onboarding_requests set
      state=case
        when coalesce((p_data->>'charges_enabled')::boolean,false) and coalesce((p_data->>'details_submitted')::boolean,false) then 'completed'
        when state='completed' then 'account_created'
        else state end,
      updated_at=now() where stripe_account_id=p_account_id;
    update dv_market_private.market_stripe_events set processing_status='applied',processing_note='seller_account_status_updated',processed_at=now()
      where stripe_event_id=p_event_id;
    return jsonb_build_object('event_id',p_event_id,'status','applied','note','seller_account_status_updated');
  end if;

  select * into a from dv_market_private.market_payment_attempts
  where stripe_account_id=p_account_id and (
    (p_data->>'attempt_id' is not null and id::text=p_data->>'attempt_id')
    or (p_data->>'attempt_id' is null and (
      stripe_checkout_session_id=p_object_id or stripe_payment_intent_id=p_object_id or stripe_charge_id=p_object_id
    ))
  ) for update;
  if not found then
    update dv_market_private.market_stripe_events set processing_status='ignored',processing_note='attempt_not_found',processed_at=now() where stripe_event_id=p_event_id;
    return jsonb_build_object('event_id',p_event_id,'status','ignored');
  end if;

  if p_event_type in ('checkout.session.completed','checkout.session.async_payment_succeeded') then
    if p_data->>'payment_intent_id' is null then raise exception 'stripe_payment_intent_missing'; end if;
    if a.stripe_checkout_session_id is null or a.stripe_checkout_session_id<>p_object_id then raise exception 'stripe_checkout_session_mismatch'; end if;
    if a.stripe_payment_intent_id is not null and a.stripe_payment_intent_id<>p_data->>'payment_intent_id' then raise exception 'stripe_payment_intent_mismatch'; end if;
    if a.state in ('paid','refund_pending','partially_refunded','refunded','disputed','failed','expired') then
      v_status:='ignored';v_note:='checkout_state_preserved';
    else
      update dv_market_private.market_payment_attempts set stripe_payment_intent_id=p_data->>'payment_intent_id',
        state=case when p_event_type='checkout.session.completed' then 'processing' else state end,updated_at=now() where id=a.id;
      v_status:='applied';v_note:='session_bound';
    end if;
  elsif p_event_type='payment_intent.succeeded' then
    if lower(coalesce(p_data->>'currency',''))<>'eur' or v_amount<>a.amount_due_cents then raise exception 'stripe_paid_amount_mismatch'; end if;
    if a.stripe_payment_intent_id is not null and a.stripe_payment_intent_id<>p_object_id then raise exception 'stripe_payment_intent_mismatch'; end if;
    if a.stripe_charge_id is not null and a.stripe_charge_id<>p_data->>'charge_id' then raise exception 'stripe_charge_mismatch'; end if;
    if a.state in ('refund_pending','partially_refunded','refunded','disputed') then
      v_status:='ignored';v_note:='post_payment_state_preserved';
    elsif a.state='paid' then
      if a.paid_cents<>v_amount then raise exception 'stripe_paid_amount_mismatch'; end if;
      v_status:='ignored';v_note:='payment_already_confirmed';
    else
      update dv_market_private.market_payment_attempts set stripe_payment_intent_id=p_object_id,
        stripe_charge_id=p_data->>'charge_id',state='paid',paid_cents=v_amount,paid_at=coalesce(p_provider_created_at,now()),updated_at=now() where id=a.id;
      update public.market_orders set payment_status='paid',paid_amount=v_amount/100.0,provider_payment_ref=p_object_id,
        paid_at=coalesce(p_provider_created_at,now()),platform_fee_amount=a.platform_fee_cents/100.0,
        seller_net_amount=(a.amount_due_cents-a.platform_fee_cents)/100.0,updated_at=now() where id=a.order_id;
      update public.market_deals set payment_status='paid',provider_payment_ref=p_object_id,paid_at=coalesce(p_provider_created_at,now()),updated_at=now() where order_id=a.order_id;
      for r in select * from dv_market_private.market_payment_allocations where attempt_id=a.id order by contract_snapshot_id loop
        v_tax:=public.record_market_tax_remuneration(r.contract_snapshot_id,'stripe:'||p_event_id||':'||r.contract_snapshot_id,
          coalesce(p_provider_created_at,now()),r.gross_cents/100.0,r.platform_fee_cents/100.0,0,0,'payment_provider',p_object_id,
          jsonb_build_object('provider','stripe_connect','charge_model','direct_charge','live_mode',false));
        update dv_market_private.market_payment_allocations set tax_event_id=(v_tax->>'event_id')::uuid where attempt_id=a.id and contract_snapshot_id=r.contract_snapshot_id;
      end loop;
      insert into dv_market_private.market_financial_documents(attempt_id,seller_id,document_kind,document_status,issuer_role,currency,gross_cents,tax_treatment,immutable_snapshot,content_sha256,issued_at)
      values(a.id,a.seller_id,'provider_payment_evidence','issued','payment_provider','EUR',v_amount,'provider_event',
        jsonb_build_object('provider','stripe_connect','event_id',p_event_id,'payment_intent_id',p_object_id,'amount_cents',v_amount,'currency','EUR','live_mode',false),
        digest(convert_to(jsonb_build_object('event_id',p_event_id,'payment_intent_id',p_object_id,'amount_cents',v_amount)::text,'UTF8'),'sha256'),coalesce(p_provider_created_at,now()))
      on conflict(attempt_id,document_kind) do nothing;
      v_status:='applied';v_note:='payment_confirmed_by_provider';
    end if;
  elsif p_event_type='payment_intent.payment_failed' then
    if a.stripe_payment_intent_id is not null and a.stripe_payment_intent_id<>p_object_id then raise exception 'stripe_payment_intent_mismatch'; end if;
    if a.state in ('paid','refund_pending','partially_refunded','refunded','disputed') then
      v_status:='ignored';v_note:='post_payment_state_preserved';
    else
      update dv_market_private.market_payment_attempts set stripe_payment_intent_id=coalesce(stripe_payment_intent_id,p_object_id),state='failed',updated_at=now() where id=a.id;
      update public.market_orders set payment_status='failed',updated_at=now() where id=a.order_id and payment_status not in ('paid','refunded');
      v_status:='applied';v_note:='payment_failed_by_provider';
    end if;
  elsif p_event_type='charge.refunded' then
    if a.stripe_charge_id is null or a.stripe_charge_id<>p_object_id then raise exception 'stripe_charge_mismatch'; end if;
    if v_amount<>a.paid_cents or a.paid_cents=0 then raise exception 'stripe_partial_refund_requires_review'; end if;
    if a.state='refunded' and a.refunded_cents=v_amount then
      v_status:='ignored';v_note:='refund_already_confirmed';
    else
      update dv_market_private.market_payment_attempts set state='refunded',refunded_cents=v_amount,updated_at=now() where id=a.id;
      update public.market_orders set payment_status='refunded',refund_status='refunded',refund_amount=v_amount/100.0,
        provider_refund_ref=p_data->>'refund_id',updated_at=now() where id=a.order_id;
      for r in select x.*,e.id original_tax_event_id from dv_market_private.market_payment_allocations x
        join dv_market_private.market_tax_events e on e.id=x.tax_event_id where x.attempt_id=a.id order by x.contract_snapshot_id
      loop
        perform public.correct_market_tax_remuneration(r.original_tax_event_id,'stripe-refund:'||p_event_id||':'||r.contract_snapshot_id,
          coalesce(p_provider_created_at,now()),r.gross_cents/100.0,r.platform_fee_cents/100.0,0,0,true,p_data->>'refund_id',
          jsonb_build_object('provider','stripe_connect','full_refund',true,'live_mode',false));
        update dv_market_private.market_payment_allocations set refunded_cents=gross_cents where attempt_id=a.id and contract_snapshot_id=r.contract_snapshot_id;
      end loop;
      update dv_market_private.market_refund_requests set status='succeeded',stripe_refund_id=p_data->>'refund_id',updated_at=now()
        where attempt_id=a.id and status in ('prepared','submitted','pending');
      v_status:='applied';v_note:='full_refund_confirmed_by_provider';
    end if;
  end if;
  update dv_market_private.market_stripe_events set processing_status=v_status,processing_note=v_note,processed_at=now() where stripe_event_id=p_event_id;
  return jsonb_build_object('event_id',p_event_id,'status',v_status,'note',v_note);
end
$function$

CREATE OR REPLACE FUNCTION public.assign_founder_generation_i()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  next_number integer;
begin
  if new.founder_number is not null then
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtext('duelvanta_founder_gen_i'));

  select coalesce(max(founder_number), 0) + 1
    into next_number
  from public.beta_waitlist
  where founder_generation = 'GEN_I'
    and founder_number is not null;

  if next_number <= 250 then
    new.founder_eligible := true;
    new.founder_number := next_number;
    new.founder_generation := 'GEN_I';
  else
    new.founder_eligible := false;
    new.founder_number := null;
    new.founder_generation := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_market_deal_to_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order uuid;v_group text;v_title text;v_num text;
begin
  if new.order_id is not null then return new; end if;
  v_group:=case when new.shipping_method='pickup' then 'pickup' else 'shipping' end;
  perform pg_advisory_xact_lock(hashtextextended(new.seller_id::text||':'||new.buyer_id::text||':'||v_group,42));
  if new.payment_provider='manual_beta' and new.payment_status='not_required' then
    select id into v_order from public.market_orders
    where seller_id=new.seller_id and buyer_id=new.buyer_id and fulfillment_group=v_group
      and status in ('open','in_progress') and shipped_at is null
      and payment_provider='manual_beta' and payment_status='not_required' and paid_amount=0
    order by created_at desc limit 1 for update;
  end if;
  if v_order is null then
    v_num:='DV-'||to_char(now(),'YYMMDD')||'-'||lpad(nextval('public.market_order_number_seq')::text,6,'0');
    insert into public.market_orders(
      order_number,seller_id,buyer_id,fulfillment_group,shipping_method,shipping_cost,shipping_quote_status,
      payment_provider,payment_status,paid_amount
    ) values(
      v_num,new.seller_id,new.buyer_id,v_group,new.shipping_method,new.shipping_cost,'auto',
      new.payment_provider,new.payment_status,0
    ) returning id into v_order;
  end if;
  select coalesce(o.contract_review_snapshot->'product'->>'title',l.card_name)
  into v_title
  from public.market_listings l
  left join public.market_offers o on o.id=new.offer_id
  where l.id=new.listing_id;
  insert into public.market_order_items(order_id,deal_id,listing_id,item_title,product_kind,sealed_category,quantity,item_amount,individual_shipping_cost,shipping_method,weight_grams)
  values(v_order,new.id,new.listing_id,coalesce(v_title,'DUELVANTA Produkt'),coalesce(new.product_kind,'single'),new.sealed_category,coalesce(new.item_quantity,1),coalesce(new.amount,0),coalesce(new.shipping_cost,0),new.shipping_method,new.weight_grams)
  on conflict(deal_id) do nothing;
  update public.market_deals set order_id=v_order where id=new.id;
  perform public.recalculate_market_order(v_order);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.begin_market_deal(p_deal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.market_deals;
begin
 if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
 select * into d from public.market_deals where id=p_deal_id for update;
 if d.id is null or auth.uid() not in (d.seller_id,d.buyer_id) then raise exception 'Nicht erlaubt'; end if;
 if d.order_id is not null then raise exception 'Dieser Kauf wird über ORDERS verwaltet'; end if;
 if d.status<>'accepted' then raise exception 'Deal kann nicht gestartet werden'; end if;
 if d.payment_provider='stripe_connect' and d.payment_status<>'paid' then raise exception 'Zahlung ist noch nicht bestätigt'; end if;
 update public.market_deals
 set status='in_progress',started_at=coalesce(started_at,now()),
     fulfillment_status=case when payment_status in ('paid','not_required') then 'ready_to_ship' else fulfillment_status end,
     updated_at=now()
 where id=d.id;
end $function$

CREATE OR REPLACE FUNCTION public.begin_my_account_deletion_withdrawal(p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s uuid;challenge uuid;begin
 s:=dv_market_private.c_session();
 if not exists(select 1 from dv_market_private.account_deletion_requests where id=p_request_id and user_id=auth.uid()) then raise exception 'c_request_not_owned' using errcode='42501';end if;
 insert into dv_market_private.c_withdrawal_challenges(request_id,user_id,session_id) values(p_request_id,auth.uid(),s) returning id into challenge;
 return challenge;
end $function$

CREATE OR REPLACE FUNCTION public.buy_market_listing_v1(p_listing_id uuid, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  l public.market_listings;
  d public.market_deals;
  v_qty integer;
  v_left integer;
  v_unit numeric;
  v_total numeric;
  t jsonb;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into l from public.market_listings where id=p_listing_id and status='active' for update;
  if l.id is null then raise exception 'Produkt ist nicht mehr verfügbar'; end if;
  if l.seller_id=auth.uid() then raise exception 'Eigene Produkte können nicht gekauft werden'; end if;
  if l.listing_type not in ('sale','sale_or_trade') or l.pricing_mode<>'fixed' then raise exception 'Dieses Produkt ist kein Festpreisangebot'; end if;
  if l.asking_price is null or l.asking_price<=0 then raise exception 'Ungültiger Festpreis'; end if;
  if l.active_until is not null and l.active_until<=now() then raise exception 'Das Angebot ist abgelaufen'; end if;

  v_qty:=case when l.product_kind='sealed' then p_quantity else 1 end;
  if p_quantity is null or p_quantity<>v_qty or v_qty<1 then raise exception 'Ungültige Menge'; end if;
  if l.product_kind='sealed' and (v_qty<l.minimum_purchase_quantity or v_qty>l.quantity_available) then raise exception 'Gewünschte Menge ist nicht mehr verfügbar'; end if;
  if l.product_kind<>'sealed' and (p_quantity<>1 or l.quantity_available<1) then raise exception 'Produkt ist nicht mehr verfügbar'; end if;

  v_unit:=l.asking_price;
  if l.product_kind='sealed' then
    for t in select value from jsonb_array_elements(coalesce(l.quantity_pricing,'[]'::jsonb)) order by (value->>'min_quantity')::int loop
      if v_qty >= (t->>'min_quantity')::int then v_unit:=(t->>'unit_price')::numeric; end if;
    end loop;
  end if;
  if v_unit is null or v_unit<=0 or v_unit::text in ('NaN','Infinity','-Infinity') then raise exception 'Ungültiger Stückpreis'; end if;
  v_unit:=round(v_unit,2);
  v_total:=round(v_unit*v_qty,2);
  v_left:=l.quantity_available-v_qty;

  update public.market_listings
  set quantity_available=v_left,
      status=case when v_left=0 then 'reserved' else 'active' end,
      deal_price=v_total,
      deal_buyer_id=auth.uid(),
      updated_at=now()
  where id=l.id;

  update public.market_offers
  set status='declined',responded_at=now(),updated_at=now()
  where listing_id=l.id and status='pending' and requested_quantity>v_left;

  insert into public.market_deals(
    listing_id,offer_id,seller_id,buyer_id,amount,currency,status,accepted_at,
    shipping_method,shipping_cost,shipping_note,product_kind,sealed_category,item_quantity,
    package_contents,weight_grams,length_mm,width_mm,height_mm
  ) values(
    l.id,null,l.seller_id,auth.uid(),v_total,'EUR','accepted',now(),
    l.shipping_method,l.shipping_cost,l.shipping_note,l.product_kind,l.sealed_category,v_qty,
    l.package_contents,case when l.weight_grams is null then null else l.weight_grams*v_qty end,
    l.length_mm,l.width_mm,l.height_mm
  ) returning * into d;

  select * into d from public.market_deals where id=d.id;
  return jsonb_build_object(
    'deal_id',d.id,'order_id',d.order_id,'quantity',v_qty,
    'unit_price',round(v_unit,2),'item_total',v_total,'remaining_quantity',v_left
  );
end $function$

CREATE OR REPLACE FUNCTION public.buy_market_listing_v2(p_listing_id uuid, p_quantity integer, p_request_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l public.market_listings; d public.market_deals; result jsonb;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  if p_request_id is null or p_expected_updated_at is null or p_quantity is null or p_quantity not between 1 and 1000 then raise exception 'Ungültige Kaufanfrage'; end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':'||p_request_id::text,43));
  select * into d from public.market_deals where buyer_id=auth.uid() and checkout_request_id=p_request_id;
  if d.id is not null then
    if d.listing_id<>p_listing_id or d.item_quantity<>p_quantity then raise exception 'Diese Kaufanfrage wurde bereits verwendet'; end if;
    return jsonb_build_object('deal_id',d.id,'order_id',d.order_id,'quantity',d.item_quantity,'item_total',d.amount,'replayed',true);
  end if;
  select * into l from public.market_listings where id=p_listing_id for update;
  if l.id is null or l.status<>'active' then raise exception 'Produkt nicht mehr verfügbar'; end if;
  if l.updated_at is distinct from p_expected_updated_at then raise exception 'Angebot wurde geändert. Bitte Menge, Preis und Versand erneut prüfen.'; end if;
  if exists(select 1 from public.profiles where id in (auth.uid(),l.seller_id) and (account_status='suspended' or safety_restricted)) then raise exception 'Kauf für diesen Account nicht verfügbar'; end if;
  if l.asking_price::text in ('NaN','Infinity','-Infinity') then raise exception 'Ungültiger Festpreis'; end if;
  result:=public.buy_market_listing_v1(p_listing_id,p_quantity);
  update public.market_deals set checkout_request_id=p_request_id where id=(result->>'deal_id')::uuid;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.buy_market_listing_v3(p_listing_id uuid, p_quantity integer, p_request_id uuid, p_expected_updated_at timestamp with time zone, p_checkout_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_review jsonb;v_result jsonb;v_snapshot dv_market_private.market_contract_snapshots%rowtype;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  v_review:=public.review_market_checkout(p_listing_id,p_quantity);
  if nullif(lower(trim(coalesce(p_checkout_hash,''))),'') is null
     or lower(p_checkout_hash)<>(v_review->>'checkout_hash') then
    raise exception 'checkout_review_changed';
  end if;
  v_result:=public.buy_market_listing_v2(p_listing_id,p_quantity,p_request_id,p_expected_updated_at);
  select * into v_snapshot from dv_market_private.market_contract_snapshots
  where deal_id=(v_result->>'deal_id')::uuid;
  if not found then raise exception 'checkout_snapshot_missing'; end if;
  return v_result || jsonb_build_object(
    'contract_snapshot_id',v_snapshot.id,'contract_classification',v_snapshot.contract_classification,
    'confirmation_sha256',encode(v_snapshot.content_sha256,'hex')
  );
end
$function$

CREATE OR REPLACE FUNCTION public.cancel_market_deal(p_deal_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.market_deals;
begin
 if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
 select * into d from public.market_deals where id=p_deal_id for update;
 if d.id is null or auth.uid() not in (d.seller_id,d.buyer_id) then raise exception 'Nicht erlaubt'; end if;
 if d.order_id is not null then raise exception 'Dieser Kauf wird über ORDERS verwaltet'; end if;
 if d.status<>'accepted' then raise exception 'Nur ein noch nicht gestarteter Deal kann direkt abgebrochen werden'; end if;
 if d.payment_status='paid' then raise exception 'Bezahlter Deal kann nicht direkt abgebrochen werden. Bitte Problem melden.'; end if;
 update public.market_deals set status='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),cancel_reason=nullif(left(trim(coalesce(p_reason,'')),500),''),updated_at=now() where id=d.id;
 update public.market_listings set status='active',accepted_offer_id=null,deal_price=null,deal_buyer_id=null,updated_at=now() where id=d.listing_id and status='reserved';
end $function$

CREATE OR REPLACE FUNCTION public.checkout_accepted_market_offer_v1(p_offer_id uuid, p_request_id uuid, p_checkout_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare
  o public.market_offers;
  l public.market_listings;
  d public.market_deals;
  v_review jsonb;
  v_snapshot dv_market_private.market_contract_snapshots%rowtype;
  v_qty integer;
  v_deal_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_request_id is null then raise exception 'checkout_request_invalid'; end if;
  perform public.expire_market_offer_reservations_v1();
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':'||p_request_id::text,44));

  select * into d from public.market_deals where buyer_id=auth.uid() and checkout_request_id=p_request_id;
  if found then
    if d.offer_id<>p_offer_id then raise exception 'checkout_request_reused'; end if;
    select * into v_snapshot from dv_market_private.market_contract_snapshots where deal_id=d.id;
    if not found then raise exception 'checkout_snapshot_missing'; end if;
    return jsonb_build_object('deal_id',d.id,'order_id',d.order_id,'quantity',d.item_quantity,
      'item_total',d.amount,'contract_snapshot_id',v_snapshot.id,
      'contract_classification',v_snapshot.contract_classification,
      'confirmation_sha256',encode(v_snapshot.content_sha256,'hex'),'replayed',true);
  end if;

  select o0.* into o from public.market_offers o0 where o0.id=p_offer_id;
  if not found then raise exception 'offer_checkout_not_available'; end if;
  select * into l from public.market_listings where id=o.listing_id for update;
  select * into o from public.market_offers where id=p_offer_id for update;
  if o.buyer_id<>auth.uid() or o.status<>'accepted' or o.reservation_expires_at is null or o.reservation_expires_at<=now() then
    raise exception 'offer_reservation_expired';
  end if;
  if exists(select 1 from public.market_deals x where x.offer_id=o.id) then raise exception 'offer_already_checked_out'; end if;

  v_review:=public.review_market_offer_checkout_v1(o.id);
  if nullif(lower(trim(coalesce(p_checkout_hash,''))),'') is null
     or lower(p_checkout_hash)<>(v_review->>'checkout_hash') then raise exception 'checkout_review_changed'; end if;
  v_qty:=greatest(coalesce(o.reserved_quantity,o.requested_quantity,1),1);

  perform set_config('dv_market.offer_checkout_authorized',o.id::text,true);
  insert into public.market_deals(
    listing_id,offer_id,seller_id,buyer_id,amount,currency,status,accepted_at,
    shipping_method,shipping_cost,shipping_note,product_kind,sealed_category,item_quantity,
    package_contents,weight_grams,length_mm,width_mm,height_mm,checkout_request_id
  ) values(
    l.id,o.id,o.seller_id,o.buyer_id,round(o.amount,2),'EUR','accepted',now(),
    l.shipping_method,l.shipping_cost,l.shipping_note,l.product_kind,l.sealed_category,v_qty,
    l.package_contents,case when l.weight_grams is null then null else l.weight_grams*v_qty end,
    l.length_mm,l.width_mm,l.height_mm,p_request_id
  ) returning id into v_deal_id;

  update public.market_offers
  set reserved_quantity=0,reservation_expires_at=null,updated_at=now()
  where id=o.id;

  select * into d from public.market_deals md where md.id=v_deal_id;
  select * into v_snapshot from dv_market_private.market_contract_snapshots where deal_id=v_deal_id;
  if not found then raise exception 'checkout_snapshot_missing'; end if;
  return jsonb_build_object('deal_id',d.id,'order_id',d.order_id,'quantity',d.item_quantity,
    'item_total',d.amount,'contract_snapshot_id',v_snapshot.id,
    'contract_classification',v_snapshot.contract_classification,
    'confirmation_sha256',encode(v_snapshot.content_sha256,'hex'),'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.claim_account_deletion_requests(p_limit integer, p_lock_token uuid)
 RETURNS TABLE(request_id uuid, user_id uuid, storage_manifest jsonb, delivery_lock_token uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare x record;r dv_market_private.account_deletion_requests%rowtype;n integer:=0;begin
 if p_lock_token is null then raise exception 'lock_token_required';end if;
 -- Existing D policy, unchanged. Withdrawal never calls this worker function.
 update dv_market_private.account_deletion_holds set released_at=now()
 where released_at is null and not manual_review_required and retain_until is not null and retain_until<=now();
 for x in select d.id,d.user_id from dv_market_private.account_deletion_requests d
 where d.status in ('requested','failed','processing','retained') order by d.user_id,d.requested_at,d.id loop
 perform 1 from public.profiles p where p.id=x.user_id for no key update skip locked;
 if not found then continue;end if;
 select * into r from dv_market_private.account_deletion_requests d where d.id=x.id and
 (d.status in ('requested','failed') or (d.status='processing' and d.locked_at<now()-interval '15 minutes')
 or (d.status='retained' and not exists(select 1 from dv_market_private.account_deletion_holds h where h.request_id=d.id and h.released_at is null))) for update skip locked;
 if not found or exists(select 1 from dv_market_private.c_withdrawal_receipts w where w.request_id=x.id) then continue;end if;
 -- Never reissue an old token for the same request, including a lost response retry.
 if exists(select 1 from dv_market_private.c_attempts a where a.request_id=r.id and a.token=p_lock_token) then continue;end if;
 insert into dv_market_private.c_attempts(request_id,token) values(r.id,p_lock_token);
 update dv_market_private.account_deletion_requests d set status='processing',lock_token=p_lock_token,locked_at=now(),processing_started_at=coalesce(d.processing_started_at,now()) where d.id=r.id;
 update public.profiles p set updated_at=now() where p.id=r.user_id;
 request_id:=r.id;user_id:=r.user_id;storage_manifest:=r.storage_manifest;delivery_lock_token:=p_lock_token;return next;
 n:=n+1;if n>=least(greatest(coalesce(p_limit,1),1),20) then exit;end if;
 end loop;
end $function$

