CREATE OR REPLACE FUNCTION public.close_market_swap_thread_v1(p_thread_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_thread dv_market_private.market_swap_threads%rowtype; v_action text:=lower(trim(coalesce(p_action,'')));
begin
  if v_uid is null then raise exception 'not_authenticated';end if;
