CREATE OR REPLACE FUNCTION public.expire_market_offer_reservations_v1()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_offer_id uuid;v_listing_id uuid;v_offer public.market_offers;v_listing public.market_listings;v_count integer:=0;v_restore integer;
begin
  for v_offer_id in
    select o.id from public.market_offers o
    where (
      (o.offer_type='fixed_price' and o.status='pending')
      or (o.offer_type='price' and o.status='accepted' and not exists(select 1 from public.market_deals d where d.offer_id=o.id))
    )
    and o.reservation_expires_at is not null and o.reservation_expires_at<=now()
    order by o.listing_id,o.id
  loop
    select listing_id into v_listing_id from public.market_offers where id=v_offer_id;
    if v_listing_id is null then continue; end if;
    select * into v_listing from public.market_listings where id=v_listing_id for update;
    select * into v_offer from public.market_offers where id=v_offer_id for update;
    if not found or not ((v_offer.offer_type='fixed_price' and v_offer.status='pending')
       or (v_offer.offer_type='price' and v_offer.status='accepted'))
       or v_offer.reservation_expires_at is null or v_offer.reservation_expires_at>now()
       or exists(select 1 from public.market_deals d where d.offer_id=v_offer.id) then continue; end if;
    v_restore:=v_offer.reserved_quantity;
    if v_listing.id is null or v_restore is null or v_restore<=0
       or v_listing.quantity_available+v_restore>v_listing.stock_quantity then
      raise exception 'market_reservation_inventory_inconsistent';
    end if;
    update public.market_offers set status='expired',reserved_quantity=0,reservation_expires_at=null,updated_at=now()
    where id=v_offer.id;
    if v_listing.id is not null then
      update public.market_listings
      set quantity_available=quantity_available+v_restore,
          status=case when status='reserved' then 'active' else status end,
          accepted_offer_id=case when accepted_offer_id=v_offer.id then null else accepted_offer_id end,
          deal_price=case when deal_buyer_id=v_offer.buyer_id then null else deal_price end,
          deal_buyer_id=case when deal_buyer_id=v_offer.buyer_id then null else deal_buyer_id end,
          updated_at=now()
      where id=v_offer.listing_id;
    end if;
    v_count:=v_count+1;
  end loop;
  return v_count;
end
$function$

CREATE OR REPLACE FUNCTION public.finalize_market_order_cancellation(p_order_id uuid, p_cancelled_by uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.market_orders;
  r record;
  v_reason text:=nullif(left(trim(coalesce(p_reason,'')),1000),'');
begin
  select * into o from public.market_orders where id=p_order_id for update;
  if o.id is null then raise exception 'Order nicht gefunden'; end if;
  if o.shipped_at is not null or o.status not in ('open','in_progress') then
    raise exception 'Order kann nicht mehr direkt storniert werden';
  end if;
  if o.payment_provider<>'manual_beta' and o.paid_amount>0 then
    raise exception 'Bezahlte Order benötigt zuerst eine serverseitige Erstattung';
  end if;

  update public.market_orders set
    status='cancelled',cancelled_at=coalesce(cancelled_at,now()),cancelled_by=p_cancelled_by,
    cancel_reason=v_reason,refund_status=case when payment_provider='manual_beta' then 'external_payment_unknown' else 'not_required' end,
    updated_at=now()
  where id=o.id;

  for r in
    select d.listing_id,sum(d.item_quantity)::integer as qty,
           bool_or(d.offer_id is not null) as has_offer
    from public.market_deals d
    where d.order_id=o.id and d.status in ('accepted','in_progress')
    group by d.listing_id
  loop
    update public.market_listings l set
      quantity_available=least(l.stock_quantity,l.quantity_available+r.qty),
      status=case when l.status='reserved' then 'active' else l.status end,
      accepted_offer_id=case when exists(
        select 1 from public.market_deals d2 where d2.order_id=o.id and d2.listing_id=l.id and d2.offer_id=l.accepted_offer_id
      ) then null else l.accepted_offer_id end,
      deal_price=case when exists(
        select 1 from public.market_deals d2 where d2.order_id=o.id and d2.listing_id=l.id and d2.buyer_id=l.deal_buyer_id
      ) then null else l.deal_price end,
      deal_buyer_id=case when exists(
        select 1 from public.market_deals d2 where d2.order_id=o.id and d2.listing_id=l.id and d2.buyer_id=l.deal_buyer_id
      ) then null else l.deal_buyer_id end,
      updated_at=now()
    where l.id=r.listing_id;
  end loop;

  update public.market_offers mo set status='cancelled',cancelled_at=coalesce(cancelled_at,now()),updated_at=now()
  where mo.id in (select d.offer_id from public.market_deals d where d.order_id=o.id and d.offer_id is not null)
    and mo.status='accepted';

  update public.market_deals set
    status='cancelled',cancelled_at=coalesce(cancelled_at,now()),cancelled_by=p_cancelled_by,
    cancel_reason=v_reason,updated_at=now()
  where order_id=o.id and status in ('accepted','in_progress');
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_account_deletion_request(p_request_id uuid, p_lock_token uuid, p_success boolean, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_request dv_market_private.account_deletion_requests%rowtype;v_status text;
begin
  select * into v_request from dv_market_private.account_deletion_requests
  where id=p_request_id and status='processing' and lock_token=p_lock_token for update;
  if not found then raise exception 'deletion_request_lock_invalid'; end if;
  v_status:=case when not p_success then 'failed' when v_request.auth_action='disable_and_retain' then 'retained' else 'completed' end;
  update dv_market_private.account_deletion_requests set status=v_status,completed_at=case when p_success then now() else null end,
    last_error=case when p_success then null else left(coalesce(p_error,'worker_failed'),500) end,
    lock_token=null,locked_at=null where id=p_request_id;
  insert into dv_market_private.account_data_rights_audit(user_id,request_id,event_type,event_data)
  values(v_request.user_id,v_request.id,'deletion_worker_finished',jsonb_build_object('status',v_status));
end
$function$

CREATE OR REPLACE FUNCTION public.finish_my_market_listing(p_listing_id uuid, p_reason text)
 RETURNS market_listings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.market_listings;
begin
  if p_reason not in ('sold','withdrawn') then raise exception 'Invalid reason'; end if;
  update public.market_listings
  set status=p_reason, ended_at=now(), updated_at=now()
  where id=p_listing_id and seller_id=auth.uid() and status in ('active','paused','reserved')
  returning * into v_row;
  if v_row.id is null then raise exception 'Listing not found or cannot be finished'; end if;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_market_tax_export(p_reporting_year integer, p_reporting_quarter integer DEFAULT NULL::integer, p_format text DEFAULT 'json'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private', 'extensions'
AS $function$
declare
  v_format text:=lower(trim(coalesce(p_format,'')));
  v_kind text;
  v_payload text;
  v_export_id uuid;
  v_rows integer;
  v_events integer;
begin
  if p_reporting_year not between 2023 and 2100
     or (p_reporting_quarter is not null and p_reporting_quarter not between 1 and 4)
     or v_format not in ('json','csv') then raise exception 'tax_export_input_invalid'; end if;
  v_kind:=case when p_reporting_quarter is null then 'annual' else 'quarterly' end;

  create temporary table if not exists pg_temp.dv_market_tax_export_work(
    seller_id uuid,reporting_quarter integer,row_payload jsonb
  ) on commit drop;
  truncate pg_temp.dv_market_tax_export_work;
  insert into pg_temp.dv_market_tax_export_work
  select * from dv_market_private.market_tax_export_dataset(p_reporting_year,p_reporting_quarter);
  select count(*) into v_rows from pg_temp.dv_market_tax_export_work;
  select count(*) into v_events from dv_market_private.market_tax_events
  where reporting_year=p_reporting_year
    and (p_reporting_quarter is null or reporting_quarter=p_reporting_quarter);

  if v_format='json' then
    select jsonb_pretty(jsonb_build_object(
      'schema_version','duelvanta-psttg-evidence-v1','export_status','review_evidence_not_bzst_submission',
      'reporting_year',p_reporting_year,'reporting_quarter',p_reporting_quarter,
      'threshold_rule','freigestellt nur bei weniger als 30 Tätigkeiten UND weniger als 2.000 EUR Vergütung',
      'rows',coalesce(jsonb_agg(row_payload order by seller_id,reporting_quarter),'[]'::jsonb)
    )) into v_payload from pg_temp.dv_market_tax_export_work;
  else
    select 'seller_id,reporting_year,reporting_quarter,psttg_subject_type,seller_type,identity_data_ready,legal_name,business_name,country_code,tax_identifier_references,quarter_activity_count,quarter_remuneration_eur,quarter_platform_fees_eur,quarter_commissions_eur,quarter_withheld_taxes_eur,annual_activity_count,annual_remuneration_eur,threshold_result,exactly_30_activities,exactly_2000_eur_remuneration'||E'\n'||
      coalesce(string_agg(
        dv_market_private.market_tax_csv_field(row_payload->>'seller_id')||','||
        dv_market_private.market_tax_csv_field(row_payload->>'reporting_year')||','||
        dv_market_private.market_tax_csv_field(row_payload->>'reporting_quarter')||','||
        dv_market_private.market_tax_csv_field(row_payload->>'psttg_subject_type')||','||
        dv_market_private.market_tax_csv_field(row_payload->>'seller_type')||','||
        dv_market_private.market_tax_csv_field(row_payload->>'identity_data_ready')||','||
        dv_market_private.market_tax_csv_field(concat_ws(' ',row_payload#>>'{identity,legal_first_name}',row_payload#>>'{identity,legal_last_name}'))||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{identity,business_name}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{identity,country_code}')||','||
        dv_market_private.market_tax_csv_field((row_payload#>'{identity,tax_identifier_references}')::text)||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{quarter,activity_count}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{quarter,remuneration}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{quarter,platform_fees}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{quarter,commissions}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{quarter,withheld_taxes}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{annual,activity_count}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{annual,remuneration}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{goods_threshold,threshold_result}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{goods_threshold,exactly_30_activities}')||','||
        dv_market_private.market_tax_csv_field(row_payload#>>'{goods_threshold,exactly_2000_eur_remuneration}'),
        E'\n' order by seller_id,reporting_quarter
      ),'') into v_payload from pg_temp.dv_market_tax_export_work;
  end if;

  insert into dv_market_private.market_tax_exports(
    reporting_year,reporting_quarter,export_format,export_kind,generated_by,
    source_event_count,row_count,payload_text,payload_sha256
  ) values (
    p_reporting_year,p_reporting_quarter,v_format,v_kind,auth.uid(),v_events,v_rows,
    v_payload,digest(convert_to(v_payload,'UTF8'),'sha256')
  ) returning id into v_export_id;

  insert into dv_market_private.market_tax_export_rows(export_id,seller_id,reporting_quarter,row_payload,row_sha256)
  select v_export_id,seller_id,reporting_quarter,row_payload,digest(row_payload::text,'sha256')
  from pg_temp.dv_market_tax_export_work order by seller_id,reporting_quarter;

  return jsonb_build_object(
    'export_id',v_export_id,'export_kind',v_kind,'format',v_format,
    'reporting_year',p_reporting_year,'reporting_quarter',p_reporting_quarter,
    'row_count',v_rows,'source_event_count',v_events,
    'sha256',encode(digest(convert_to(v_payload,'UTF8'),'sha256'),'hex'),
    'status','review_evidence_not_bzst_submission','payload',v_payload
  );
end
$function$

CREATE OR REPLACE FUNCTION public.get_battle_disputes_for_moderation()
 RETURNS TABLE(id uuid, tcg text, mode text, status text, host_display_name text, guest_display_name text, host_result text, guest_result text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin perform public.require_duelvanta_privileged_session();
 if auth.uid() is null then raise exception 'not_authenticated'; end if;
 if not public.has_staff_permission('battle_moderate',auth.uid()) then raise exception 'battle_moderate permission required'; end if;
 return query select m.id,m.tcg,m.mode,m.status,m.host_display_name,m.guest_display_name,m.host_result,m.guest_result,m.created_at
 from public.battle_matches m where m.status='dispute' order by m.created_at asc limit 100;
end $function$

CREATE OR REPLACE FUNCTION public.get_battle_spectator_media_publisher_admission(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.battle_matches%rowtype; s jsonb; role_name text;
begin
  perform battle_spectator_private.actor_session();
  select * into m from public.battle_matches where id=p_match_id;
  if not found or (auth.uid() is distinct from m.host_id and auth.uid() is distinct from m.guest_id) then
    raise exception 'spectator_media_player_only' using errcode='42501';
  end if;
  s:=battle_spectator_media_private.sync_epoch(p_match_id);
  if not coalesce((s->>'media_open')::boolean,false) then
    raise exception 'spectator_media_closed' using errcode='42501';
  end if;
  role_name:=case when auth.uid()=m.host_id then 'host' else 'guest' end;
  return jsonb_build_object('match_id',p_match_id,'epoch',s->>'epoch','publisher_role',role_name,'admission_expires_at',clock_timestamp()+interval '30 seconds');
end
$function$

CREATE OR REPLACE FUNCTION public.get_battle_spectator_status(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_match public.battle_matches%rowtype;
begin
  perform battle_spectator_private.actor_session();
  select * into v_match from public.battle_matches where id=p_match_id;
  if not found or (auth.uid() is distinct from v_match.host_id and auth.uid() is distinct from v_match.guest_id
      and auth.uid() is distinct from v_match.moderator_id) then
    raise exception 'spectator_status_for_participants_only' using errcode='42501'; end if;
  return jsonb_build_object('spectator_count',battle_spectator_private.viewer_count(p_match_id),
    'link_enabled',coalesce((select enabled from battle_spectator_private.links where match_id=p_match_id),false));
end $function$

CREATE OR REPLACE FUNCTION public.get_market_deal_shipping_address(p_deal_id uuid)
 RETURNS TABLE(deal_id uuid, recipient_name text, street_line1 text, street_line2 text, postal_code text, city text, country_code text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  d public.market_deals;
  v_role text;
begin
  select * into d from public.market_deals where id=p_deal_id;
  if d.id is null then raise exception 'Deal nicht gefunden'; end if;
  if auth.uid()=d.buyer_id then
    v_role:='buyer';
  elsif auth.uid()=d.seller_id then
    if d.status not in ('accepted','in_progress','disputed') or d.completed_at is not null or d.cancelled_at is not null then
      raise exception 'Lieferadresse ist für den Verkäufer nicht mehr verfügbar';
    end if;
    v_role:='seller';
  else
    raise exception 'Nicht erlaubt';
  end if;

  if exists(select 1 from public.market_deal_shipping_addresses a where a.deal_id=d.id) then
    insert into public.market_shipping_address_access_log(deal_id,accessor_id,access_role)
    values(d.id,auth.uid(),v_role);
  end if;

  return query
  select a.deal_id,a.recipient_name,a.street_line1,a.street_line2,a.postal_code,a.city,a.country_code,a.updated_at
  from public.market_deal_shipping_addresses a
  where a.deal_id=d.id;
end
$function$

