 if auth.uid()=o.buyer_id then v_role:='buyer';
 elsif auth.uid()=o.seller_id then
   if o.status not in ('open','in_progress','shipped','received','disputed') or o.completed_at is not null or o.cancelled_at is not null then raise exception 'Lieferadresse ist für den Verkäufer nicht mehr verfügbar'; end if;
