CREATE OR REPLACE FUNCTION public.report_battle_user(p_match_id uuid, p_reported_user_id uuid, p_category text, p_details text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
 if auth.uid() is null then raise exception 'Not authenticated'; end if;
 if p_category not in ('nudity','sexual_content','insult','hate','harassment','threat','cheating','other') then raise exception 'Invalid category'; end if;
 if p_reported_user_id=auth.uid() then raise exception 'Cannot report yourself'; end if;
 if not exists(select 1 from public.battle_matches m where m.id=p_match_id and auth.uid() in (m.host_id,m.guest_id) and p_reported_user_id in (m.host_id,m.guest_id)) then raise exception 'Not a participant'; end if;
