 return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.request_market_order_cancellation(p_order_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.market_orders;v_reason text;v_case uuid;v_other uuid;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  v_reason:=nullif(left(trim(coalesce(p_reason,'')),1200),'');
  if v_reason is null or char_length(v_reason)<3 then raise exception 'Bitte Stornogrund angeben'; end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if o.id is null or auth.uid() not in (o.seller_id,o.buyer_id) then raise exception 'Nicht erlaubt'; end if;
  if o.shipped_at is not null or o.status not in ('open','in_progress') then raise exception 'Nach Versand bitte einen Problemfall melden'; end if;
  if exists(select 1 from public.market_order_cases where order_id=o.id and status in ('open','accepted_refund_pending')) then
    raise exception 'Für diese Order ist bereits ein Vorgang offen';
  end if;
  v_other:=case when auth.uid()=o.seller_id then o.buyer_id else o.seller_id end;
  insert into public.market_order_cases(order_id,case_type,status,reason,opened_by,refund_state,refund_amount)
  values(o.id,'cancellation','open',v_reason,auth.uid(),
    case when o.payment_provider='manual_beta' then 'external_payment_unknown' when o.paid_amount>0 then 'provider_required' else 'not_required' end,
    case when o.paid_amount>0 then o.total_amount else null end)
  returning id into v_case;
  insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
  values(v_other,'cancellation_requested','STORNO ANGEFRAGT',o.order_number||' · '||left(v_reason,220),o.id,'cancel_request:'||v_case::text)
  on conflict(dedupe_key) do nothing;
  return v_case;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_market_order_delivery_review_b07(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.market_orders;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into o from public.market_orders where id=p_order_id for update;
  if not found or auth.uid()<>o.seller_id then raise exception 'Nur der Verkäufer kann eine Zustellprüfung anfordern'; end if;
  if o.fulfillment_group<>'shipping' or o.status not in ('shipped','received') or o.shipped_at is null then raise exception 'delivery_review_not_applicable';end if;
  if nullif(trim(coalesce(o.tracking_code,'')),'') is null then raise exception 'delivery_review_requires_tracking'; end if;
  if o.delivery_evidence_at is not null or o.delivery_review_status='verified' then return jsonb_build_object('status','verified','requested_at',o.delivery_review_requested_at,'reviewed_at',o.delivery_reviewed_at);end if;
  if o.delivery_review_status='pending' then return jsonb_build_object('status','pending','requested_at',o.delivery_review_requested_at);end if;
  if exists(select 1 from public.market_order_cases c where c.order_id=o.id and c.case_type='problem' and c.status='open') then raise exception 'Ein Problemfall ist bereits offen';end if;
  update public.market_orders set delivery_review_status='pending',delivery_review_requested_at=now(),delivery_review_requested_by=auth.uid(),delivery_reviewed_at=null,delivery_reviewed_by=null,delivery_review_note=null,updated_at=now() where id=o.id;
  return jsonb_build_object('status','pending','requested_at',now());
end $function$

CREATE OR REPLACE FUNCTION public.request_my_account_deletion(p_confirmation text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_market_private'
AS $function$
declare v_uid uuid:=auth.uid();v_blockers jsonb;v_request uuid;v_manifest jsonb;
begin
 -- B1 request serialization: before request INSERT and profile markers.
 perform 1 from public.profiles where id=auth.uid() for no key update;
  if v_uid is null then raise exception 'authentication_required'; end if;
  if p_request_key is null or p_confirmation<>'KONTO LÖSCHEN' then raise exception 'deletion_confirmation_invalid'; end if;
  select id into v_request from dv_market_private.account_deletion_requests
  where user_id=v_uid and request_key=p_request_key;
  if found then return jsonb_build_object('accepted',true,'request_id',v_request,'replayed',true); end if;
  select id into v_request from dv_market_private.account_deletion_requests
  where user_id=v_uid and status in ('requested','processing','retained') order by requested_at desc limit 1;
  if found then return jsonb_build_object('accepted',true,'request_id',v_request,'replayed',true); end if;
  v_blockers:=dv_market_private.account_deletion_blockers(v_uid);
  if jsonb_array_length(v_blockers)>0 then
    return jsonb_build_object('accepted',false,'blockers',v_blockers);
  end if;
  v_manifest:=jsonb_build_array();
  select coalesce(jsonb_agg(x),'[]'::jsonb) into v_manifest from (
    select jsonb_build_object('bucket','profile-avatars','path',avatar_path) x from public.profiles where id=v_uid and avatar_path is not null
    union all select jsonb_build_object('bucket','collection-cards','path',image_path) from public.collection_items where user_id=v_uid and image_path is not null
    union all select jsonb_build_object('bucket','market-listing-images','path',i.storage_path) from public.market_listing_images i where i.seller_id=v_uid
  ) paths;
  insert into dv_market_private.account_deletion_requests(user_id,request_key,storage_manifest)
  values(v_uid,p_request_key,v_manifest) returning id into v_request;
  perform dv_market_private.c_register_request(v_request,v_uid);
  update public.profiles set account_closure_requested_at=now(),data_processing_restricted_at=now(),
    safety_restricted=true,collection_visibility='private',updated_at=now() where id=v_uid;
  perform dv_market_private.c_own_markers(v_request,v_uid);
  insert into dv_market_private.account_data_rights_audit(user_id,request_id,event_type,event_data)
  values(v_uid,v_request,'deletion_requested',jsonb_build_object('storage_object_count',jsonb_array_length(v_manifest)));
  return jsonb_build_object('accepted',true,'request_id',v_request,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.require_duelvanta_privileged_session()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if auth.jwt()->>'role' is distinct from 'authenticated' then raise exception 'human_session_required' using errcode='42501'; end if;
  if auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'mfa_step_up_required' using errcode='42501'; end if;
  if not public.has_duelvanta_privileged_session() then raise exception 'privileged_session_required' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.reserve_my_magic_transport_v1(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'dv_collect_private'
AS $function$
declare u uuid:=auth.uid();b boolean;policy dv_collect_private.magic_transport_policy_v1%rowtype;
 stamp timestamptz;win timestamptz;subject text;g integer;n integer;
begin
 if u is null or p_request_id is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'transport_denied' using errcode='42501';end if;
 perform 1 from public.profiles where id=u and data_processing_restricted_at is null and account_closure_requested_at is null and account_status not in ('suspended','deleted') for update;
 if not found then raise exception 'transport_denied' using errcode='42501';end if;
 select enabled into b from dv_collect_private.tcg_magic_on_demand_beta where game_key='magic' for share;
 if b is distinct from true or not dv_collect_private.magic_collect_admitted_v1(true)
 or not coalesce((public.get_security_schema_readiness_v1()->>'compatible')::boolean,false)
 or not coalesce((public.get_market_legal_schema_readiness_v1()->>'compatible')::boolean,false)
 then raise exception 'transport_denied' using errcode='42501';end if;
 select * into policy from dv_collect_private.magic_transport_policy_v1 where singleton for update;
 if not found or not policy.enabled or policy.global_limit<=0 or policy.user_limit<=0 then raise exception 'transport_denied' using errcode='42501';end if;
 if not dv_collect_private.magic_collect_admitted_v1(false) then raise exception 'transport_denied' using errcode='42501';end if;
 stamp:=clock_timestamp();win:=to_timestamp(floor(extract(epoch from stamp)/policy.window_seconds)*policy.window_seconds);
 subject:=encode(sha256(convert_to(u::text,'UTF8')),'hex');
 if exists(select 1 from dv_collect_private.magic_transport_reservations_v1 where request_id=p_request_id) then raise exception 'transport_denied' using errcode='42501';end if;
 insert into dv_collect_private.magic_transport_usage_v1 values(win,policy.window_seconds,'GLOBAL',0),(win,policy.window_seconds,subject,0) on conflict do nothing;
 select used into g from dv_collect_private.magic_transport_usage_v1 where window_start=win and window_seconds=policy.window_seconds and subject_hash='GLOBAL';
 select used into n from dv_collect_private.magic_transport_usage_v1 where window_start=win and window_seconds=policy.window_seconds and subject_hash=subject;
 if g>=policy.global_limit or n>=policy.user_limit then raise exception 'transport_denied' using errcode='42501';end if;
 update dv_collect_private.magic_transport_usage_v1 set used=used+1 where window_start=win and window_seconds=policy.window_seconds and subject_hash in ('GLOBAL',subject);
 insert into dv_collect_private.magic_transport_reservations_v1 values(p_request_id,subject,stamp,win,policy.window_seconds,policy.global_limit,policy.user_limit,policy.authorization_ref,'magic-collect-transport/1');
 return jsonb_build_object('contract','magic-collect-transport/1','reserved',true,'request_id',p_request_id,'user_id',u,'reserved_at',stamp);
end$function$

CREATE OR REPLACE FUNCTION public.resolve_battle_dispute(p_match_id uuid, p_result text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d3_targets uuid[]:=array[]::uuid[]; d3_profile record; d3_actor_found boolean:=false;
begin
 -- D3 closed mutation boundary v1
 perform public.require_duelvanta_privileged_session();
 select array[m.host_id,m.guest_id] into d3_targets from public.battle_matches m where m.id=p_match_id;
 for d3_profile in select id,data_processing_restricted_at,role from public.profiles
   where id=auth.uid() or id=any(d3_targets) order by id for no key update loop
  if d3_profile.id=auth.uid() then
   d3_actor_found:=true;
   if d3_profile.data_processing_restricted_at is not null then
    raise exception 'staff_actor_processing_hold' using errcode='42501';
   end if;
  end if;
  if d3_profile.id=any(d3_targets) and d3_profile.data_processing_restricted_at is not null and not coalesce((false),false) then
   raise exception 'staff_target_processing_hold' using errcode='42501';
  end if;
 end loop;
 if not d3_actor_found then raise exception 'not_authenticated' using errcode='42501'; end if;
 -- Recheck the unchanged real session gate after waiting on actor/profile locks.
 perform public.require_duelvanta_privileged_session();
 perform 1 from public.battle_matches m where m.id=p_match_id and array[m.host_id,m.guest_id] is not distinct from d3_targets for update; if not found then raise exception 'd3_case_changed_or_missing' using errcode='42501'; end if;

declare
  v_uid uuid := auth.uid();
  v_match public.battle_matches%rowtype;
  v_winner uuid;
begin perform public.require_duelvanta_privileged_session();
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not public.has_staff_permission('battle_moderate', v_uid) then
    raise exception 'battle_moderate permission required';
  end if;
  if p_result not in ('host','guest','draw') then
    raise exception 'Invalid dispute result';
  end if;

  select * into v_match from public.battle_matches where id=p_match_id for update;
  if not found then raise exception 'Match not found'; end if;
  if v_uid in (v_match.host_id, coalesce(v_match.guest_id,v_match.host_id)) then
    raise exception 'Players cannot resolve own match';
  end if;
  if v_match.status <> 'dispute' then
    raise exception 'Match is not in dispute';
  end if;
  if v_match.guest_id is null then raise exception 'Match has no opponent'; end if;

  v_winner := case when p_result='host' then v_match.host_id
                   when p_result='guest' then v_match.guest_id
                   else null end;

  update public.battle_matches
     set status='completed',
         winner_id=v_winner,
         completed_at=now(),
         moderation_state='resolved',
         moderator_id=coalesce(moderator_id,v_uid),
         moderator_joined_at=coalesce(moderator_joined_at,now()),
         moderation_note=left(nullif(trim(p_note),''),1000),
         paused_at=null,
         paused_by=null,
         updated_at=now()
   where id=p_match_id;

  insert into public.admin_audit_log(actor_id,action,details)
  values(v_uid,'battle_dispute_resolved',
         jsonb_build_object('match_id',p_match_id,'result',p_result,'note',left(p_note,1000)));

  return 'completed';
end;
end
$function$

CREATE OR REPLACE FUNCTION public.respond_market_order_cancellation(p_case_id uuid, p_accept boolean, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  c public.market_order_cases;o public.market_orders;v_other uuid;v_note text:=nullif(left(trim(coalesce(p_note,'')),800),'');
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  select * into c from public.market_order_cases where id=p_case_id and case_type='cancellation' for update;
  if c.id is null or c.status<>'open' then raise exception 'Stornoanfrage ist nicht mehr offen'; end if;
  select * into o from public.market_orders where id=c.order_id for update;
  if o.id is null or auth.uid() not in (o.seller_id,o.buyer_id) or auth.uid()=c.opened_by then raise exception 'Nicht erlaubt'; end if;
  if o.shipped_at is not null then raise exception 'Order wurde inzwischen versendet'; end if;
  v_other:=c.opened_by;
  if not coalesce(p_accept,false) then
    update public.market_order_cases set status='declined',responded_by=auth.uid(),response_note=v_note,responded_at=now(),updated_at=now() where id=c.id;
    insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
    values(v_other,'cancellation_declined','STORNO ABGELEHNT',o.order_number||coalesce(' · '||v_note,''),o.id,'cancel_declined:'||c.id::text)
    on conflict(dedupe_key) do nothing;
    return 'declined';
  end if;

  if o.payment_provider<>'manual_beta' and o.paid_amount>0 then
    update public.market_order_cases set status='accepted_refund_pending',refund_state='provider_required',refund_amount=o.total_amount,
      responded_by=auth.uid(),response_note=v_note,responded_at=now(),updated_at=now() where id=c.id;
    update public.market_orders set status='disputed',refund_status='provider_required',refund_amount=o.total_amount,
      disputed_at=coalesce(disputed_at,now()),disputed_by=c.opened_by,dispute_reason='Storno akzeptiert · Erstattung ausstehend',updated_at=now() where id=o.id;
    update public.market_deals set status='disputed',payout_status=case when payment_provider='stripe_connect' then 'blocked' else payout_status end,
      disputed_at=coalesce(disputed_at,now()),disputed_by=c.opened_by,dispute_reason='Storno akzeptiert · Erstattung ausstehend',updated_at=now()
      where order_id=o.id and status in ('accepted','in_progress');
    insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
    values(v_other,'cancellation_accepted','STORNO AKZEPTIERT · ERSTATTUNG AUSSTEHEND',o.order_number,o.id,'cancel_accepted_refund:'||c.id::text)
    on conflict(dedupe_key) do nothing;
    return 'refund_required';
  end if;

  perform public.finalize_market_order_cancellation(o.id,auth.uid(),coalesce(v_note,c.reason));
  update public.market_order_cases set status='accepted',refund_state=case when o.payment_provider='manual_beta' then 'external_payment_unknown' else 'not_required' end,
    responded_by=auth.uid(),response_note=v_note,responded_at=now(),updated_at=now() where id=c.id;
  insert into public.market_notifications(recipient_id,kind,title,body,order_id,dedupe_key)
  values(v_other,'cancellation_accepted','ORDER STORNIERT',o.order_number||' · Bestand wurde zurückgebucht.',o.id,'cancel_accepted:'||c.id::text)
  on conflict(dedupe_key) do nothing;
  return 'cancelled';
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_market_order_problem(p_case_id uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
